window.__D("text/zohar-hebrew-translation/c016",{"p":[[9522011664,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי נִפְגְּשׁוּ לַיְלָה אֶחָד בְּמִגְדַּל צוֹר. הִתְאָרְחוּ שָׁם וְשָׂמְחוּ זֶה בָּזֶה. אָמַר רַבִּי יוֹסֵי, כַּמָּה שָׂמַחְתִּי שֶׁרָאִיתִי פְּנֵי הַשְּׁכִינָה, שֶׁעַכְשָׁו בְּכָל הַדֶּרֶךְ הַזֹּאת הִצְטַעַרְתִּי בְּזָקֵן אֶחָד סוֹחֵר שֶׁהָיָה שׁוֹאֵל אוֹתִי כָּל הַדֶּרֶךְ:</p>\n<p>מִי הוּא נָחָשׁ הַפּוֹרֵחַ בָּאֲוִיר וְהוֹלֵךְ בְּפֵרוּד, וּבֵין כָּךְ וּבֵין כָּךְ יֵשׁ מְנוּחָה לִנְמָלָה אַחַת שֶׁשּׁוֹכֶבֶת בֵּין שִׁנָּיו, הִתְחִיל בְּחִבּוּר וְסִיֵּם בְּפֵרוּד? וּמַה הוּא נֶשֶׁר שֶׁמְּקַנֵּן בְּאִילָן שֶׁלֹּא הָיָה? בָּנָיו שֶׁנִּגְזְלוּ, וְלֹא מֵהַבְּרִיּוֹת? שֶׁנִּבְרְאוּ בְמָקוֹם שֶׁלֹּא נִבְרְאוּ? כְּשֶׁעוֹלִים יוֹרְדִים, כְּשֶׁיּוֹרְדִים עוֹלִים? שְׁנַיִם שֶׁהֵם אֶחָד, וְאֶחָד שֶׁהֵם שָׁלֹשׁ? מַה זֶּה עַלְמָה יָפָה וְאֵין לָהּ עֵינַיִם, וְהַגּוּף נִסְתָּר וּמִתְגַּלֶּה? הִיא יוֹצֵאת בַּבֹּקֶר וְנִתְכַּסֵּית בַּיּוֹם, וּמִתְקַשֶּׁטֶת בְּקִשּׁוּטִים שֶׁלֹּא הָיוּ?</p>\n<p>כָּל זֶה שָׁאַל בַּדֶּרֶךְ, וְהִצְטַעַרְתִּי. וְעַכְשָׁו יֵשׁ לִי מְנוּחָה. שֶׁאִלּוּ הָיִינוּ כְּאֶחָד, הִתְעַסַּקְנוּ בְּדִבְרֵי תוֹרָה מַה שֶּׁהָיִינוּ בִּדְבָרִים אֲחֵרִים שֶׁל תֹּהוּ. אָמַר רַבִּי חִיָּיא, וְאוֹתוֹ זָקֵן סוֹחֵר יָדַעְתָּ בּוֹ מַשֶּׁהוּ? אָמַר לוֹ, יָדַעְתִּי שֶׁאֵין מַמָּשׁ בִּדְבָרָיו, שֶׁאִלּוּ הָיָה יוֹדֵעַ, יִפְתַּח בַּתּוֹרָה, וְלֹא הָיְתָה הַדֶּרֶךְ בְּרֵיקָנוּת. אָמַר רַבִּי חִיָּיא, וְאוֹתוֹ הַסּוֹחֵר יֶשְׁנוֹ כָּאן, שֶׁהֲרֵי לִפְעָמִים בְּאוֹתָם הָרֵיקָנִים יִמָּצֵא אִישׁ פַּעֲמוֹנֵי זָהָב. אָמַר לוֹ, הֲרֵי הוּא כָּאן, וְהִתְקִין חֲמוֹרוֹ לְמַאֲכָל.</p>\n<p>קָרְאוּ לוֹ וּבָא לִפְנֵיהֶם. אָמַר לָהֶם, כָּעֵת שְׁנַיִם הֵם שְׁלֹשָׁה, וּשְׁלֹשָׁה הֵם כְּאֶחָד. אָמַר רַבִּי יוֹסֵי, וְלֹא אָמַרְתִּי לְךְ שֶׁכָּל דְּבָרָיו רֵיקָנִים וְהֵם בְּרֵיקָנוּת?! יָשַׁב לִפְנֵיהֶם.</p>\n<p>אָמַר לָהֶם, רַבּוֹתֵינוּ, אֲנִי נַעֲשֵׂיתִי סוֹחֵר, וְרַק מִלִּפְנֵי מְעַט יָמִים, שֶׁהֲרֵי בַּהַתְחָלָה לֹא הָיִיתִי סוֹחֵר, אֲבָל בֵּן אֶחָד קָטָן יֵשׁ לִי, וְנָתַתִּי אוֹתוֹ לְבֵית הַסֵּפֶר, וַאֲנִי רוֹצֶה שֶׁיַּעֲסֹק בַּתּוֹרָה, וּכְשֶׁאֲנִי מוֹצֵא אֶחָד מֵהָרַבָּנִים שֶׁהוֹלֵךְ בַּדֶּרֶךְ, אֲנִי טוֹעֵן אַחֲרָיו, וְהַיּוֹם הַזֶּה חָשַׁבְתִּי שֶׁאֶשְׁמַע דְּבָרִים חֲדָשִׁים בַּתּוֹרָה, וְלֹא שָׁמַעְתִּי דָבָר.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בְּכָל הַדְּבָרִים שֶׁשָּׁמַעְתִּי שֶׁאָמַרְתָּ לֹא תָמַהְתִּי, אֶלָּא רַק מֵאֶחָד - אוֹ שֶׁאַתָּה אָמַרְתָּ בִּשְׁטוּת, אוֹ שֶׁהֵם דְּבָרִים רֵיקִים. אָמַר אוֹתוֹ זָקֵן, וּמַה הִיא? אָמַר, נַעֲרָה יָפָה וְכוּ'.</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (תהלים קיח) ה' לִי לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם. ה' לִי בְּעֹזְרָי וְגוֹ'. טוֹב לַחֲסוֹת בַּה' וְגוֹ'. כַּמָּה טוֹבִים וּנְעִימִים וְנִכְבָּדִים וְעֶלְיוֹנִים דִּבְרֵי הַתּוֹרָה, וַאֲנִי אֵיךְ אֹמַר לִפְנֵי רַבּוֹתֵינוּ, שֶׁלֹּא שָׁמַעְתִּי מִפִּיהֶם עַד עַכְשָׁו אֲפִלּוּ דָּבָר אֶחָד?! אֲבָל יֵשׁ לִי לוֹמַר, שֶׁאֵין בּוּשָׁה כְּלָל לוֹמַר דִּבְרֵי תוֹרָה לִפְנֵי הַכֹּל.</p>\n<p>הִתְעַטֵף אוֹתוֹ הַזָּקֵן, פָּתַח וְאָמַר, (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר הִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל. פָּסוּק זֶה סָמוּךְ עַל פָּסוּק אַחֵר - (שם) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ מִלֶּחֶם אָבִיהָ תֹּאכֵל וְכָל זָר לֹא יֹאכַל בּוֹ. פְּסוּקִים הַלָּלוּ כְּמַשְׁמָעָם, אֲבָל דִּבְרֵי הַתּוֹרָה הֵם דְּבָרִים סְתוּמִים.</p>\n<p>וְכַמָּה הֵם דִּבְרֵי חָכְמָה שֶׁסְּתוּמִים בְּכָל דָּבָר וְדָבָר שֶׁבַּתּוֹרָה, וְנוֹדָעִים לְאוֹתָם הַחֲכָמִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה, שֶׁהֲרֵי הַתּוֹרָה אֵינָם דִּבְרֵי חֲלוֹם הֵם, שֶׁנִּמְסְרוּ לְמִי שֶׁפּוֹתֵר אוֹתָם וְנִמְשָׁכִים אַחַר הַפֶּה, וְעִם כָּל זֶה צָרִיךְ לִפְתֹּר אוֹתָם לְפִי דַרְכָּם. וּמָה אִם דִּבְרֵי חֲלוֹם צָרִיךְ לִפְתֹּר אוֹתָם לְפִי דַרְכָּם - דִּבְרֵי הַתּוֹרָה שֶׁהֵם שַׁעֲשׁוּעֵי הַמֶּלֶךְ הַקָּדוֹשׁ עַל אַחַת כַּמָּה וְכַמָּה שֶׁצְּרִיכִים לָלֶכֶת בְּדֶרֶךְ אֱמֶת בָּהֶם, שֶׁכָּתוּב (הושעיד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ'.</p>\n<p>עַכְשָׁו יֵשׁ לוֹמַר, וּבַת כֹּהֵן - זוֹ הַנְּשָׁמָה הָעֶלְיוֹנָה, בִּתּוֹ שֶׁל אַבְרָהָם אָבִינוּ רִאשׁוֹן לַגֵּרִים, וְהוּא מוֹשֵׁךְ אֶת אוֹתָהּ נְשָׁמָה מִמָּקוֹם עֶלְיוֹן. מַה בֵּין פָּסוּק שֶׁאָמַר וּבַת אִישׁ כֹּהֵן, וּבֵין פָּסוּק שֶׁאָמַר וּבַת כֹּהֵן, וְלֹא כָתוּב אִישׁ? אֶלָּא יֵשׁ כֹּהֵן שֶׁנִּקְרָא אִישׁ כֹּהֵן, וְלֹא כֹּהֵן מַמָּשׁ. וְעַל הַדֶּרֶךְ הַזֶּה הָיָה (איש) כֹּהֵן, וְהָיָה סְגָן, וְהָיָה כֹּהֵן גָּדוֹל, וְהָיָה כֹּהֵן שֶׁאֵינוֹ גָּדוֹל. כֹּהֵן סְתָם גָּדוֹל וְעֶלְיוֹן מֵאִישׁ כֹּהֵן. וְעַל זֶה יֵשׁ נְשָׁמָה, וְיֵשׁ רוּחַ, וְיֵשׁ נֶפֶשׁ.</p>\n<p>וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנִּמְשְׁכָה מִמָּקוֹם עֶלְיוֹן וְנִכְנְסָה לְתוֹךְ סֵתֶר עֵץ הַחַיִּים, וּכְשֶׁרוּחַ הַכֹּהֵן הָעֶלְיוֹן נוֹשֶׁבֶת וְנוֹתֶנֶת נְשָׁמוֹת בָּאִילָן הַזֶּה, פּוֹרְחוֹת מִשָּׁם אוֹתָם נְשָׁמוֹת וְנִכְנָסוֹת בְּאוֹצָר אֶחָד.</p>\n<p>אוֹי לָעוֹלָם, שֶׁלֹּא יוֹדְעִים בְּנֵי אָדָם לְהִשָּׁמֵר, שֶׁמּוֹשְׁכִים מְשִׁיכָה עִם יֵצֶר הָרָע, שֶׁהוּא אִישׁ זָר, וּבַת הַכֹּהֵן הַ את פּוֹרַחַת לְמַטָּה וּמוֹצֵאת בִּנְיָן בְּאִישׁ זָר. וּמִשּׁוּם שֶׁהוּא רָצוֹן שֶׁל אֲדוֹנָהּ, נִכְנֶסֶת לְשָׁם וְנִכְפֵּית, וְלֹא יְכוֹלָה לִשְׁלֹט, וְלֹא הִשְׁתַּלְּמָה בָּעוֹלָם הַזֶּה. וּכְשֶׁיּוֹצֵאת מִמֶּנּוּ, הִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל, כִּשְׁאָר כָּל הַנְּשָׁמוֹת שֶׁהִשְׁתַּלְּמוּ בָּעוֹלָם הַזֶּה.</p>\n<p>עוֹד יֵשׁ בַּפָּסוּק הַזֶּה, וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר. עֲלוּבָה הִיא הַנְּשָׁמָה הַקְּדוֹשָׁה כִּי תִהְיֶה לְאִישׁ זָר, שֶׁנִּמְשְׁכָה עַל הַגֵּר שֶׁהִתְגַּיֵּר, וּפָרְחָה אֵלָיו מִגַּן עֵדֶן בְּדֶרֶךְ נִסְתָּר עַל בִּנְיָן שֶׁנִּבְנֶה מֵעָרְלָה טְמֵאָה, זוֹ הָיְתָה לְאִישׁ זָר.</p>\n<p>וְזְהִוּ סוֹד עֶלְיוֹן יוֹתֵר מֵהַכֹּל. בָּעַמּוּד שֶׁעוֹמֵד לַמֹּאזְנַיִם בְּתוֹךְ אֲוִיר שֶׁנּוֹשֵׁב, יֵשׁ מִשְׁקָל אֶחָד בְּצַד זֶה, וְיֵשׁ מִשְׁקָל אַחֵר בְּצַד זֶה. בְּצַד זֶה מֹאזְנֵי צֶדֶק, וּבְצַד זֶה מֹאזְנֵי מִרְמָה. וְהַמִּשְׁקָל הַזֶּה לֹא שׁוֹכֵךְ לְעוֹלָמִים, וּנְשָׁמוֹת עוֹלוֹת וְיוֹרְדוֹת, נִכְנָסוֹת וְיוֹצְאוֹת, וְיֵשׁ נְשָׁמוֹת עֲשׁוּקוֹת, כְּשֶׁשּׁוֹלֵט אָדָם בְּאָדָם, שֶׁכָּתוּב (קהלת ח) עֵת אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ. לְרַע לוֹ וַדַּאי.</p>\n<p>אֲבָל נְשָׁמָה זוֹ שֶׁהָיְתָה לַצַּד הָאַחֵר, אִישׁ זָר, וְנֶעֶשְׁקָה מִמֶּנּוּ, זוֹהִי לְרַע לוֹ. לוֹ - לְאוֹתוֹ אִישׁ זָר, וְהִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל, עַד שֶׁעוֹשֶׂה בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא מַה שֶּׁעוֹשֶׂה. בָּא הַפָּסוּק וְאָמַר, וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר, כָּךְ זֶה.</p>\n<p>כָּאן יֵשׁ סוֹד אֵיךְ נֶעֱשָׁקוֹת הַנְּשָׁמוֹת. אֶלָּא הָעוֹלָם הַזֶּה מִתְנַהֵג הַכֹּל בְּעֵץ הַדַּעַת טוֹב וָרָע. וּכְשֶׁמִּתְנַהֲגִים בְּנֵי הָעוֹלָם בַּצַּד הַטּוֹב, הַמִּשְׁקֹלֶת עוֹמֶדֶת וּמַכְרִיעָה לַצַּד הַטּוֹב, וּכְשֶׁמִּתְנַהֲגִים בַּצַּד הָרָע - מַכְרִיעָה לְאוֹתוֹ הַצַּד. וְכָל הַנְּשָׁמוֹת שֶׁהָיוּ בְּאוֹתָהּ שָׁעָה בַּמִּשְׁקֹלֶת, הָיָה עוֹשֵׁק אוֹתָן וְלוֹקֵחַ אוֹתָן.</p>\n<p>אֲבָל לְרַע לוֹ, שֶׁאוֹתָן נְשָׁמוֹת מַכְנִיעוֹת (מכסות) אֶת כָּל מַה שֶּׁמּוֹצְאוֹת מִצַּד הָרָע וּמַשְׁמִידוֹת אוֹתוֹ, וְסִימָן לָזֶה - אֲרוֹן הַקֹּדֶשׁ שֶׁנֶּעֱשַׁק לְתוֹךְ פְּלִשְׁתִּים וְשָׁלְטוּ לְהָרַע לָהֶם. אַף כָּאן, אֵלּוּ הַנְּשָׁמוֹת נֶעֱשָׁקוֹת מֵהַצַּד הָאַחֵר לְהָרַע לָהֶן.</p>\n<p>מַה נַּעֲשָׂה מֵאוֹתָן נְשָׁמוֹת? רָאִינוּ בְּסִפְרֵי הַקַּדְמוֹנִים, שֶׁמֵּהֶם הָיוּ אוֹתָם חֲסִידֵי אֻמּוֹת הָעוֹלָם. וְאוֹתָם הַמַּמְזֵרִים שֶׁהֵם תַּלְמִידֵי חֲכָמִים שֶׁקּוֹדְמִים לְכֹהֵן גָּדוֹל עַם הָאָרֶץ וְחָשׁוּב בָּעוֹלָם, אַף עַל גַּב שֶׁהוּא נִכְנָס לִפְנַי וְלִפְנִים. בָּכָה הַזָּקֵן הַזֶּה רֶגַע אֶחָד. תָּמְהוּ הַחֲבֵרִים וְלֹא אָמְרוּ דָבָר.</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, אִם רָעָה בְּעֵינֵי אֲדנֶיהָ אֲשֶׁר לֹא יְעָדָהּ וְהֶפְדָּהּ לְעַם נָכְרִי וְגוֹ'. פָּרָשָׁה זוֹ נֶאֶמְרָה עַל הַסּוֹד הַזֶּה, וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים אִם וְגוֹ'. רִבּוֹן הָעוֹלָם, מִי לֹא יִפְחַד מִמְּךְ, שֶׁאַתָּה שׁוֹלֵט עַל כָּל מַלְכֵי הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה י) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה וְגוֹ'.</p>\n<p>כַּמָּה הֵם בְּנֵי הָאָדָם בָּעוֹלָם שֶׁמִּשְׁתַּבְּשִׁים בַּפָּסוּק הַזֶּה, וְכֻלָּם אוֹמְרִים, אֲבָל הַפָּסוּק הַזֶּה לֹא מִתְיַשֵּׁר בְּפִיהֶם. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מֶלֶךְ הַגּוֹיִם?! וַהֲלֹא הוּא מֶלֶךְ יִשְׂרָאֵל, וְכָךְ נִקְרָא! שֶׁהֲרֵי כָּתוּב (דבריםלב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגוֹ', וְכָתוּב (שם) כִּי חֵלֶק ה' עַמּוֹ. וְעַל זֶה הוּא נִקְרָא מֶלֶךְ יִשְׂרָאֵל. וְאִם תֹּאמַר שֶׁהוּא נִקְרָא מֶלֶךְ הַגּוֹיִם, הֲרֵי שֶׁבַח שֶׁלָּהֶם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ עֲלֵיהֶם, וְלֹא כְּמוֹ שֶׁאוֹמְרִים שֶׁהֵם נִמְסְרוּ לַשַּׁמָּשִׁים וְלַמְמֻנִּים שֶׁלּוֹ.</p>\n<p>וְעוֹד סוֹף הַפָּסוּק, שֶׁכָּתוּב (ירמיה י) כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ. כָּל זֶה הוּא שֶׁבַח לִשְׁאָר הָעַמִּים. וּתְמִיהָה הִיא אֵיךְ לֹא מִתְעַלִּים בַּפָּסוּק הַזֶּה לְרוּם הָרָקִיעַ? אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא סִמֵּא אֶת עֵינֵיהֶם וְלֹא יוֹדְעִים בּוֹ כְּלָל, שֶׁהֲרֵי מַה שֶּׁאָנוּ אוֹמְרִים שֶׁכֻּלָּם אַיִן וְאֶפֶס וְתֹהוּ, שֶׁכָּתוּב (ישעיה מ) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ, הֲרֵי הָעִקָּר הָעֶלְיוֹן הַגָּדוֹל וְהַנִּכְבָּד שָׂם אוֹתָם הַכָּתוּב הַזֶּה.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, וַהֲרֵי כָּתוּב מָלַךְ אֱלֹהִים עַל גּוֹיִם וְגוֹ'. אָמַר לוֹ, אֲנִי רָאִיתִי שֶׁאַחַר הַכֹּתֶל שֶׁלָּהֶם הָיִיתָ, וְיָצָאתָ בַּפָּסוּק הַזֶּה לַעֲזר לָהֶם. הָיָה לִי לְהָשִׁיב בַּתְּחִלָּה עַל מַה שֶּׁאָמַרְתִּי. אֲבָל כֵּיוָן שֶׁמָּצָאתִי אוֹתְךְ בַּדֶּרֶךְ, אַעֲבִיר אוֹתְךְ מִשָּׁם, וּמִשָּׁם אֵלֵךְ לְהַעֲבִיר אֶת הַכֹּל.</p>\n<p>בֹּא וּרְאֵה, כָּל הַשֵּׁמוֹת וְכָל כִּנּוּיֵי הַשֵּׁמוֹת שֶׁיֵּשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כֻּלָּם מִתְפַּשְּׁטִים לְדַרְכֵיהֶם, וְכֻלָּם מִתְלַבְּשִׁים אֵלֶּה בְּאֵלֶּה, וְכֻלָּם נֶחֱלָקִים לִדְרָכִים וּשְׁבִילִים יְדוּעִים, פְּרָט לַשֵּׁם הַיְחִידִי, הַנִּבְחָר שֶׁל כָּל שְׁאָר הַשֵּׁמוֹת, שֶׁהוֹרִישׁ לָעָם הַיָּחִיד הַנִּבְחָר מִכָּל הָעַמִּים, וְהוּא - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ. וְכָתוּב (שם) וְאַתֶּם הַדְּבֵקִים בַּה', בְּשֵׁם זֶה מַמָּשׁ יוֹתֵר מִכָּל שְׁאָר הַשֵּׁמוֹת.</p>\n<p>וְשֵׁם אֶחָד מִכָּל שְׁאָר שְׁמוֹתָיו, אוֹתוֹ שֶׁהִתְפַּשֵּׁט וְנֶחֱלָק לְכַמָּה דְרָכִים וּשְׁבִילִים וְנִקְרָא אֱלֹהִים. וְהוֹרִישׁ אֶת הַשֵּׁם הַזֶּה, וְנֶחֱלָק לַתַּחְתּוֹנִים שֶׁל הָעוֹלָם הַזֶּה, וְנֶחֱלָק הַשֵּׁם הַזֶּה לְשַׁמָּשִׁים וְלִמְמֻנִּים שֶׁמַּנְהִיגִים אֶת שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. (בראשית כ) וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה. וְכֵן כָּל מְמֻנֶּה וּמְמֻנֶּה שֶׁהוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם לִשְׁאָר הָעַמִּים נִכְלָלִים בַּשֵּׁם הַזֶּה, וַאֲפִלּוּ עֲבוֹדָה זָרָה נִקְרֵאת בַּשֵּׁם הַזֶּה. וְשֵׁם זֶה מָלַךְ עַל גּוֹיִם, וְלֹא אוֹתוֹ הַשֵּׁם, שֶׁהוּא מֶלֶךְ עַל יִשְׂרָאֵל, שֶׁהוּא יְחִידִי לָעָם הַיְחִידִי, לְעַם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ.</p>\n<p>וְאִם תֹּאמַר, עַל דֶּרֶךְ זוֹ נְבָאֵר אֶת הַפָּסוּק, שֶׁכָּתוּב (ירמיהי) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם, שֶׁהֲרֵי הוּא שֵׁם שֶׁמּוֹלֵךְ עַל גּוֹיִם - אֱלֹהִים, שֶׁהֲרֵי הַיִּרְאָה שְׁרוּיָה בּוֹ וְהַדִּין שָׁרוּי בּוֹ - לֹא כָּךְ, וְלֹא עַל זֶה נֶאֱמַר. שֶׁאִם כָּךְ, אֲפִלּוּ עֲבוֹדָה זָרָה בִּכְלַל זֶה הִיא.</p>\n<p>אֲבָל כֵּיוָן שֶׁהַכֹּתֶל שֶׁהָיִיתָ סָמוּךְ אַחֲרָיו נֶעֱקַר, הַפָּסוּק עוֹמֵד עַל קִיּוּמוֹ בְּהִסְתַּכְּלוּת קְטַנָּה. מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם. וְאִם תֹּאמַר שֶׁמֶּלֶךְ הַגּוֹיִם נֶאֱמַר עַל הַקָּדוֹשׁ בָּרוּךְ הוּא - לֹא כָּךְ. אֶלָּא מִי הוּא מֶלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ, שֶׁלֹּא פוֹחֵד מִמְּךְ וְלֹא יִזְדַּעֲזַע מִמְּךְ, מִי מֶלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ? כְּמוֹ זֶה, (תהלים קיג) הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. מִי שֶׁשָּׁמַע אוֹתוֹ, לֹא יוֹדֵעַ מָה אָמַר. כֵּיוָן שֶׁאָמַר הַלְלוּיָהּ, אַף כָּךְ הַלְלוּ עַבְדֵי ה'! שֶׁהָיָה לוֹ לִכְתֹּב, עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. אַף כָּאן הָיָה לוֹ לִכְתֹּב, מִי מִמֶּלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ, אֶלָּא הַכֹּל עַל תִּקּוּנוֹ נִתְבָּאֵר.</p>\n<p>כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ. מָה הַדָּבָר שֶׁהִתְפַּשֵּׁט בֵּינֵיהֶם בַּחָכְמָה שֶׁלָּהֶם? מֵאֵין כָּמוֹךְ, וְכֻלָּם מוֹדִים עַל זֶה. כְּשֶׁרוֹאִים בְּחָכְמָתָם מַעֲשֶׂיךְ וּגְבוּרוֹתֶיךְ, הִתְפַּשֵּׁט דָּבָר זֶה בֵּינֵיהֶם, וְאוֹמְרִים מֵאֵין כָּמוֹךְ בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם. מֵאֵין כָּמוֹךְ אוֹמְרִים, וְהִתְפַּשֵּׁט בֵּינֵיהֶם. שָׂמְחוּ הַחֲבֵרִים, וּבָכוּ וְלֹא אָמְרוּ דָבָר. אַף כָּךְ הוּא בָּכָה כְּמִקֹּדֶם.</p>\n<p>פָּתַח וְאָמַר, (בראשית כא) וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַ את וְאֶת בְּנָהּ וְגוֹ'. הַחֲבֵרִים הִתְעוֹרְרוּ, שֶׁרָצְתָה שָׂרָה לְפַנּוֹת מִבֵּיתָהּ עֲבוֹדָה זָרָה, וְעַל זֶה כָּתוּב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ. כָּאן כָּתוּב וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ - זוֹ הַנְּשָׁמָה בְּגִלְגּוּלִים עַל מַעֲשִׂים רָעִים שֶׁבָּעוֹלָם. לְאָמָה - לְאוֹתוֹ הַצַּד הָאַחֵר בְּגִלְגּוּל רַע שֶׁל הַמִּשְׁקָל שֶׁחוֹזֵר, וַהֲרֵי נֶעֶשְׁקָה לְהוֹצִיא אוֹתָהּ מִשָּׁם. וַדַּאי לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, כָּל אוֹתָן נְשָׁמוֹת שֶׁנֶּעֱשָׁקוֹת.</p>\n<p>מִי הֵן כָּאן? הוּא סוֹד אֵלֶּה אוֹתָן נִשְׁמוֹת הַתִּינוֹקוֹת הַקְּטַנִּים, כְּשֶׁהֵם יוֹנְקִים מִתּוֹךְ תֹּקֶף שֶׁל אִמָּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה שֶׁאִם יִתְקַיְּמוּ בָּעוֹלָם, יִבְאַשׁ רֵיחָם וְיַחֲמִיצוּ כְּמוֹ הַחֹמֶץ הַזֶּה. לוֹקֵחַ אוֹתָם קְטַנִּים, בְּעוֹדָם נוֹתְנִים רֵיחַ.</p>\n<p>מָה עוֹשֶׂה? מַשְׁאִיר אוֹתָם לְהֵעָשֵׁק בְּיַד אוֹתָהּ הָאָמָה, וְזוֹהִי לִילִי\"ת. שֶׁכֵּיוָן שֶׁנִּתְּנוּ בִּרְשׁוּתָהּ, שְׂמֵחָה (אוחזת) בְּאוֹתוֹ תִינוֹק וְעוֹשֶׁקֶת אוֹתוֹ, וּמוֹצִיאָה אוֹתוֹ מִן הָעוֹלָם כְּשֶׁהוּא יוֹנֵק מִכֹּחַ אִמּוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁאוֹתָן נְשָׁמוֹת יַעֲשׂוּ טוֹב לָעוֹלָם - לֹא כָּךְ, שֶׁכָּתוּב אִם רָעָה בְּעֵינֵי אֲדנֶיהָ, שֶׁיַּחֲמִיץ אוֹתוֹ הָאִישׁ בָּהּ לְאַחַר יָמִים, אִם יִתְקַיֵּם בָּהּ. זוֹ נֶעֱשֶׁקֶת, וְאַחֶרֶת לֹא נֶעֱשֶׁקֶת, וְעַל אֵלֶּה כָּתוּב, (קהלת ד) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים וְגוֹ', וְהַיְנוּ אִם רָעָה בְּעֵינֵי אֲדנֶיהָ.</p>\n<p>אֲשֶׁר לֹא יְעָדָהּ. לֹא - כָּתוּב בְּאָלֶ\"ף. אִם תֹּאמַר שֶׁהֲרֵי בְּאוֹתוֹ הַצַּד הָאַחֵר הִזְמִין לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁהָיְתָה - לֹא! וְעַכְשָׁו בְּגִלְגּוּלֵי הַמֹּאזְנַיִם - לוֹ יְעָדָהּ, בְּוָא\"ו, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן.</p>\n<p>וְהֶפְדָּהּ, מַה זֶּה וְהֶפְדָּהּ? גָּאַל אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא עַכְשָׁו, שֶׁמַּעֲלָה רֵיחַ, טֶרֶם שֶׁתַּחֲמִיץ, וּמַעֲלֶה אוֹתָהּ לְרוּמֵי מְרוֹמִים בַּיְשִׁיבָה שֶׁלּוֹ. וְאִם תֹּאמַר, כֵּיוָן שֶׁנֶּעֶשְׁקָה מֵאוֹתוֹ הַצַּד הָרָע, נוֹתֵן אוֹתָהּ, כְּמוֹ שֶׁאָמְרוּ לַחֲסִידֵי אֻמּוֹת הָעוֹלָם וּלְאוֹתָם מַמְזֵרִים תַּלְמִידֵי חֲכָמִים - בָּא הַכָּתוּב וּמוֹכִיחַ, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ, וַדַּאי, בְּבִגְדוֹ בָהּ, שֶׁעוֹשֵׁק אוֹתָהּ בָּעֹשֶׁק שֶׁל גִּלְגּוּל הַמֹּאזְנַיִם, אֶלָּא לְיִשְׂרָאֵל וַדַּאי, וְלֹא לְאַחֵר. וּכְשֶׁיּוֹצֵאת מִן הַמֹּאזְנַיִם, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, אֶלָּא מִתְעַטֶּרֶת בַּעֲטַרְתָּהּ בַּהֲרָמַה עַל רֹאשָׁהּ.</p>\n<p>וְאִם תֹּאמַר שֶׁהַצַּד הַזֶּה הִכְנִיס אוֹתוֹ לְאוֹתוֹ תִינוֹק - לֹא כָּךְ, אֶלָּא נוֹטֶלֶת אוֹתָהּ וּשְׂמֵחָה עִמָּהּ וּפוֹרַחַת מִיָּדָהּ וְנִכְנֶסֶת לְאוֹתוֹ מָקוֹם, וְהִיא פּוֹקֶדֶת אֶת אוֹתוֹ תִינוֹק וּשְׂמֵחָה בּוֹ וְצוֹחֶקֶת בּוֹ, וּתְאֵבָה אֶת אוֹתוֹ הַבָּשָׂר, עַד שֶׁאַחַר כָּךְ נוֹטֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נִשְׁמָתוֹ, וְהִיא לַגּוּף. וְאַחַר כָּךְ הַכֹּל בִּרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא וּרְאֵה, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, מַה זֶּה? אֶלָּא בְּשָׁעָה שֶׁיּוֹצֵאת מִן הַמֹּאזְנַיִם וְאוֹתוֹ הַצַּד בְּשִׂמְחָה, רוֹשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא וְחוֹתֵם אוֹתָהּ בְּחוֹתֶמֶת אַחַת, וּפוֹרֵס עָלֶיהָ לְבוּשׁ כָּבוֹד שֶׁלּוֹ, וּמִיהוּ? הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא אֱלוֹהַּ. וְזֶהוּ בְּבִגְדוֹ בָהּ, הַלְּבוּשׁ הַנִּכְבָּד שֶׁל הַמֶּלֶךְ פּוֹרֵשׂ עָלֶיהָ, וְאָז הִיא שְׁמוּרָה, שֶׁלֹּא נִמְסְרָה לְעַם נָכְרִי אֶלָּא לְיִשְׂרָאֵל לְחוּד.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב (איוב כטו) כִּימֵי אֱלוֹהַּ יִשְׁמְרֵנִי, וְעַל סוֹד זֶה כָּתוּב כָּאן, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ בְּבִגְדוֹ בָהּ, בְּעוֹד שֶׁלְּבוּשׁ כְּבוֹד הַמֶּלֶךְ בָּהּ. כֵּיוָן שֶׁבִּגְדוֹ בָהּ, כָּתוּב לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ.</p>\n<p>מָה רְשׁוּת יֵשׁ לְאוֹתוֹ צַד בָּהּ? בֹּא וּרְאֵה, כָּל בְּנֵי הָעוֹלָם כֻּלָּם בִּרְשׁוּת הַמֶּלֶךְ הַקָּדוֹשׁ, וּלְכֻלָּם יֵשׁ זְמַן בָּעוֹלָם הַזֶּה, עַד שֶׁהוּא רוֹצֶה לְסַלְּקָם מִן הָעוֹלָם, וְזֶה אֵין לוֹ זְמַן, וְעַל כָּךְ הִיא צוֹחֶקֶת בָּהֶם וּשְׂמֵחָה בָהֶם.</p>\n<p>עוֹד, אַזְהָרָה לָאָדָם (בעולם הזה) יֵשׁ בַּפְּסוּקִים הַלָּלוּ וְכַמָּה עֵצוֹת טוֹבוֹת עֶלְיוֹנוֹת הֵן בְּכָל דִּבְרֵי הַתּוֹרָה, וְכֻלָּן אֱמֶת בְּדֶרֶךְ אֱמֶת, וְנוֹדָעוֹת לַחֲכָמִים שֶׁיּוֹדְעִים וְהוֹלְכִים בְּדֶרֶךְ אֱמֶת. בִּזְמַן שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, עָלָה בְרָצוֹן לְפָנָיו, וְצִיֵּר אֶת כָּל הַנְּשָׁמוֹת שֶׁהֵן עֲתִידוֹת לְהִנָּתֵן בִּבְנֵי אָדָם אַחַר כָּךְ, וְכֻלָּן הִצְטַיְּרוּ לְפָנָיו בְּאוֹתוֹ צִיּוּר מַמָּשׁ שֶׁעֲתִידִים לִהְיוֹת בְּנֵי אָדָם לְאַחַר מִכֵּן, וְרָאָה כָּל אֶחָד וְאֶחָד.</p>\n<p>וְיִשִׁ מֵהֶן שֶׁעֲתִידוֹת לְהָרַע אֶת דַּרְכֵיהֶן בָּעוֹלָם, וּבְשָׁעָה שֶׁמַּגִּיעַ זְמַנָּן, קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ נְשָׁמָה וְאוֹמֵר לָהּ: לְכִי וְהִכָּנְסִי בְּמָקוֹם פְּלוֹנִי לְגוּף פְּלוֹנִי. וְהִיא מְשִׁיבָה לְפָנָיו: רִבּוֹן הָעוֹלָם, דַּי לִי בָּעוֹלָם הַזֶּה שֶׁאֲנִי יוֹשֶׁבֶת בּוֹ, וְלֹא אֵלֵךְ לְעוֹלָם אַחֵר שֶׁיִּשְׁתַּעְבְּדוּ בִי וְאֶהְיֶה מְלֻכְלֶכֶת בֵּינֵיהֶם. אוֹמֵר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: מִיּוֹם שֶׁנִּבְרֵאת, עַל מְנָת כֵּן נִבְרֵאת, לִהְיוֹת בְּאוֹתוֹ עוֹלָם. כֵּיוָן שֶׁרוֹאָה הַנְּשָׁמָה כָּךְ, בְּעַל כָּרְחָהּ יוֹרֶדֶת וְנִכְנֶסֶת לְשָׁם.</p>\n<p>הַתּוֹרָה שֶׁנּוֹתֶנֶת עֵצָה לְכָל הָעוֹלָם רוֹאָה כָּךְ, וּמַזְהִירָה אֶת בְּנֵי הָעוֹלָם וְאוֹמֶרֶת: רְאוּ כַּמָּה חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיכֶם. מַרְגָּלִית טוֹבָה שֶׁהָיְתָה לוֹ, מָכַר לָכֶם בְּחִנָּם כְּדֵי שֶׁתִּשְׁתַּעְבְּדוּ בָהּ בָּעוֹלָם הַזֶּה.</p>\n<p>וְכִי יִמְכֹּר אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֶת בִּתּוֹ - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה. לְאָמָה - לִהְיוֹת אָמָה מְשֻׁעְבֶּדֶת בֵּינֵיכֶם בָּעוֹלָם הַזֶּה. בְּבַקָּשָׁה מִכֶּם, בְּשָׁעָה שֶׁמַּגִּיעַ זְמַנָּהּ לָצֵאת מִן הָעוֹלָם הַזֶּה, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, לֹא תֵצֵא מְטֻנֶּפֶת בַּחֲטָאִים. תֵּצֵא בַּת חוֹרִין, בְּרוּרָה נְקִיָּה, כְּדֵי שֶׁיִּשְׂמַח בָּהּ אֲדוֹנָהּ וְיִשְׁתַּבַּח בָּהּ וְיִתֵּן לָהּ שָׂכָר טוֹב בְּצִחְצוּחֵי גַּן עֵדֶן, כְּמוֹ שֶׁנֶּאֱמַר וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. וַדַּאי כַּאֲשֶׁר תֵּצֵא בְּרוּרָה נְקִיָּה כָּרָאוּי.</p>\n<p>אֲבָל אִם רָעָה בְּעֵינֵי אֲדנֶיהָ, כְּשֶׁיּוֹצֵאת מְלֻכְלֶכֶת בְּטִנּוּפֵי הַחֲטָאִים וְלֹא נִרְאֵית לְפָנָיו כָּרָאוּי - אוֹי לְאוֹתוֹ הַגּוּף שֶׁאָבַד מֵאוֹתָהּ נְשָׁמָה לְעוֹלָמִים. מִשּׁוּם שֶׁכַּאֲשֶׁר הַנְּשָׁמוֹת עוֹלוֹת בְּרוּרוֹת וְיוֹצְאוֹת נְקִיּוֹת מִן הָעוֹלָם הַזֶּה, כָּל נְשָׁמָה וּנְשָׁמָה נִכְנֶסֶת לְסֵפֶר אוֹצַר הַמֶּלֶךְ, וְכֻלָּן בְּשֵׁמוֹת, וְאוֹמֵר: זוֹ הִיא נִשְׁמַת פְּלוֹנִי עֲתִידָה תִּהְיֶה לְאוֹתוֹ הַגּוּף שֶׁעָזְבָה. וְאָז כָּתוּב לוֹ יְעָדָהּ, בְּו'.</p>\n<p>וּכְשֶׁיּוֹצֵאת רָעָה בְּעֵינֵי אֲדנֶיהָ, שֶׁנִּטְמְאָה בַּחֲטָאִים וּבַטִּנּוּף שֶׁל הַחֲטָאִים, אָז לֹא יְעָדָהּ, בְּא'. וְנֶאֱבָד אוֹתוֹ הַגּוּף מִמֶּנָּה, וְהִיא לֹא מִזְדַּמֶּנֶת אֵלָיו, פְּרָט לְאוֹתָה שֶׁבַּעְלָהּ הִתְרַצָּה וְשָׁב בִּתְשׁוּבָה שֶׁל הַגּוּף בָּהּ, אָז כָּתוּב וְהֶפְדָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) פָּדָה נַפְשׁוֹ מֵעֲבֹר בַּשָּׁחַת. וְהֶפְדָּהּ, זֶהוּ בָּאָדָם, שֶׁהָעֵצָה שֶׁלּוֹ שֶׁיִּפְדֶּה אוֹתָהּ וְיָשׁוּב בִּתְשׁוּבָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אֶת זֶה לִשְׁנֵי צְדָדִים, וְהֶפְדָּהּ בִּתְשׁוּבָה. אַחַר שֶׁשָּׁב בִּתְשׁוּבָה, פָּדָה אוֹתָהּ מִדֶּרֶךְ הַגֵּיהִנֹּם.</p>\n<p>לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ. מִי זֶה עַם נָכְרִי? עֲלוּבָה הִיא הַנְּשָׁמָה, שֶׁכַּאֲשֶׁר יוֹצֵאת מִן הָעוֹלָם וּבֶן אָדָם מַסְטֶה דַרְכּוֹ עִמָּהּ, הִיא רוֹצָה לַעֲלוֹת לְמַעְלָה לְתוֹךְ הַמַּחֲנוֹת הַקְּדוֹשִׁים, מִשּׁוּם שֶׁהַמַּחֲנוֹת הַקְּדוֹשִׁים עוֹמְדִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל גַּן עֵדֶן, וּמַחֲנוֹת נָכְרִיִּים עוֹמְדִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל הַגֵּיהִנֹּם.</p>\n<p>זָכְתָה הַנְּשָׁמָה, וְאוֹתָהּ שְׁמִירָה וּפְרִישַׂת לְבוּשׁ הַנִּכְבָּד עָלֶיהָ. כַּמָּה מַחֲנוֹת קְדוֹשִׁים מְעֻתָּדִים לָהּ לְהִתְחַבֵּר עִמָּהּ וּלְהַכְנִיס אוֹתָהּ לְגַן עֵדֶן. לֹא זָכְתָה - כַּמָּה מַחֲנוֹת נָכְרִיִּים מְזֻמָּנִים לְהַכְנִיס אוֹתָהּ בְּדֶרֶךְ הַגֵּיהִנָּם, וְאוֹתָם מַחֲנוֹת שֶׁל מַלְאֲכֵי חַבָּלָה מְזֻמָּנִים לַעֲשׂוֹת בָּהּ נְקָמוֹת. בָּא הַכָּתוּב וּמוֹכִיחַ, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ - אֵלּוּ מַלְאֲכֵי חַבָּלָה. בְּבִגְדוֹ בָהּ - אוֹתָהּ שְׁמִירָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לָהּ שְׁמִירָה שֶׁלֹּא יִשְׁלֹט בָּה עַם נָכְרִי בְּאוֹתָהּ הַפְּרִיסָה שֶׁשּׁוֹמֶרֶת עָלֶיהָ.</p>\n<p>וְאִם לִבְנוֹ יִיעָדֶנָּה. בּא וּרְאֵה כַּמָּה יֵשׁ לָאָדָם לְהִזָּהֵר שֶׁלֹּא יִסְטוּ דְרָכָיו בָּעוֹלָם הַזֶּה. שֶׁאִם זָכָה אָדָם בָּעוֹלָם הַזֶּה וְשׁוֹמֵר אֶת הַנְּשָׁמָה כָּרָאוּי, זֶהוּ אָדָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מִמֶּנּוּ, וּמִשְׁתַּבֵּחַ בּוֹ בְּכָל הַיָּמִים בַּפָּמַלְיָה שֶׁלּוֹ וְאוֹמֵר: רְאוּ בֵן קָדוֹשׁ שֶׁיֵּשׁ לִי בְּאוֹתוֹ הָעוֹלָם, כָּךְ וְכָךְ עָשָׂה, כָּךְ וְכָךְ מַעֲשָׂיו מְתֻקָּנִים.</p>\n<p>וּכְשֶׁנְּשָׁמָה זוֹ יוֹצֵאת מֵהָעוֹלָם הַזֶּה זַכָּה נְקִיָּה וּבְרוּרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר לָהּ בְּכַמָּה אוֹרוֹת, בְּכָל יוֹם קוֹרֵא עָלֶיהָ: זוֹהִי נִשְׁמַת פְּלוֹנִי בְּנִי, שְׁמִירָה תִּהְיֶה לְאוֹתוֹ הַגּוּף שֶׁעָזְבָה.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ. מַה זֶּה כְּמִשְׁפַּט הַבָּנוֹת? כָּאן יֵשׁ סוֹד לַחֲכָמִים. בְּתוֹךְ הַסֶּלַע הֶחָזָק, הָרָקִיעַ הַטָּמוּן, יֵשׁ הֵיכָל אֶחָד שֶׁנִּקְרָא הֵיכַל הָאַהֲבָה, וְשָׁם הַגְּנָזִים טְמוּנִים, וְכָל נְשִׁיקוֹת הָאַהֲבָה שֶׁל מֶלֶךְ הֵן שָׁם, וְאוֹתָן נְשָׁמוֹת אֲהוּבוֹת הַמֶּלֶךְ נִכְנָסוֹת לְשָׁם.</p>\n<p>כֵּיוָן שֶׁהַמֶּלֶךְ נִכְנָס לְאוֹתוֹ הֵיכַל הַמֶּלֶךְ, שָׁם כָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצֵא שָׁם אֶת אוֹתָהּ נְשָׁמָה קְדוֹשָׁה, מַקְדִּים מִיָּד וְנוֹשֵׁק לָהּ, וּמְגַפֵּף אוֹתָהּ וּמַעֲלֶה אוֹתָהּ אֵלָיו וּמִשְׁתַּעֲשֵׁעַ בָּהּ.</p>\n<p>וְזְהִוּ כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ, כְּדִין שֶׁאָב עוֹשֶׂה לְבִתּוֹ, שֶׁהִיא חֲבִיבָה עָלָיו, שֶׁנּוֹשֵׁק לָהּ וּמְגַפֵּף אוֹתָהּ וְנוֹתֵן לָהּ מַתָּנוֹת. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לַנְּשָׁמָה הַצַּדִּיקָה בְּכָל יוֹם, כְּמוֹ שֶׁכָּתוּב כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ.</p>\n<p>הַיְנוּ שֶׁכָּתוּב (ישעיה סד) יַעֲשֶׂה לִמְחַכֵּה לוֹ. כְּמוֹ שֶׁהַבַּת הַזֹּאת מַשְׁלִימָה עֲשִׂיָּה בָּעוֹלָם הַזֶּה, אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁלִים לָהּ עֲשִׂיָּה אַחֶרֶת בָּעוֹלָם הַבָּא, שֶׁכָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְכָאן כָּתוּב יַעֲשֶׂה לָּהּ. עַד כָּאן. אוֹתוֹ הַזָּקֵן הִשְׁתַּטַּח וְהִתְפַּלֵּל תְּפִלָּה, וּבָכָה כְּמִקֹּדֶם.</p>\n<p>וְאָמַר, אִם אַחֶרֶת יִקַּח לוֹ וְגוֹ', מַה זֶּה אִם אַחֶרֶת? וְכִי נְשָׁמָה אַחֶרֶת עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב לַצַּדִּיקִים בָּעוֹלָם הַזֶּה, וְלֹא נְשָׁמָה זוֹ שֶׁהִשְׁלִימָה בָּעוֹלָם הַזֶּה אֶת רְצוֹן רִבּוֹנָהּ? אִם כָּךְ, אָז אֵין הַבְטָחָה לַצַּדִּיקִים כְּלָל. מַה זֶּה אִם אַחֶרֶת יִקַּח לוֹ?</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (קהלת יב) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים בְּחֻרְבַּן בֵּית הַמִּקְדָּשׁ. (ושם שנינו) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה. כָּאן הוּא מַה שֶּׁכָּתוּב וְהַכְּנַעֲנִי אָז בָּאָרֶץ, כְּשֶׁהָיָה וַדַּאי. וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, מַה זֶּה וְהָרוּחַ תָּשׁוּב? זוֹ שְׁכִינָה, שֶׁהִיא רוּחַ הַקֹּדֶשׁ. כְּשֶׁרָאֲתָה שְׁכִינָה בְּאוֹתָם עֲשָׂרָה מַסָּעוֹת שֶׁנָּסְעָה, וְלֹא רָצוּ בְּנֵי יִשְׂרָאֵל לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשׁוֹלֵט הַסִּטְרָא אַחֲרָא עַל הָאָרֶץ הַקְּדוֹשָׁה, וּפֵרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>בֹּא וּרְאֵה, רוּחַ שֶׁל אִישׁ צַדִּיק מִתְעַטֶּרֶת בִּדְמוּת בְּגַן עֵדֶן שֶׁלְּמַטָּה, וּבְכָל הַשַּׁבָּתוֹת וְהַמּוֹעֲדִים וְרָאשֵׁי חֳדָשִׁים מִתְעַטְּרוֹת רוּחוֹת וּמִתְפַּשְּׁטוֹת, וְעוֹלוֹת לְמַעְלָה. כְּמוֹ שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ נְשָׁמָה עֶלְיוֹנָה קְדוֹשָׁה לְמַעְלָה, כָּךְ גַּם עוֹשֶּׂה בָּרוּחַ הַ את לְמַטָּה בְּגַן עֵדֶן הַתַּחְתּוֹן כְּשֶׁעוֹלָה לְפָנָיו, וְאוֹמֵר: זוֹהִי רוּחַ פְּלוֹנִי הַגּוּף. מִיָּד מְעַטֵּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ רוּחַ בְּכַמָּה עֲטָרוֹת וּמִשְׁתַּעֲשֵׁעַ בָּהּ.</p>\n<p>וְאִם תֹּאמַר, שֶׁהֲרֵי מִשּׁוּם רוּחַ זוֹ הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא מַה שֶּׁעָשָׂה לַנְּשָׁמָה - לֹא כָּךְ! אֶלָּא שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע. אֵלֶּה אוֹתָם שְׁלֹשֶׁת הַשֵּׁמוֹת הָעֶלְיוֹנִים שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ.</p>\n<p>וְכֻלָּם בָּעוֹלָם הַבָּא וְנִמְשְׁכוּ מִשָּׁם. אֶחָד מֵהֶם שְׁאֵרָהּ - מְשִׁיכָה שֶׁל הִתְנוֹצְצוּת וְאוֹר שֶׁמֵּאִיר בְּדֶרֶךְ נִסְתָּר, מָזוֹן (לנו) שֶׁזָּן לַכֹּל, וְנִקְרָא יהו\"ה עִם נִקּוּד אֱלֹהִי\"ם. שְׁאֵרָהּ בְּהִפּוּךְ אוֹתִיּוֹת - אָשֵׁר ה', וְזֶה (בראשית מט) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, וְזה הוּא שְׁאֵרָהּ.</p>\n<p>כְּסוּתָהּ - פְּרִישָׂה שֶׁל הַמֶּלֶךְ. זוֹ מְשִׁיכָה אַחֶרֶת שֶׁמְּאִירָה וְשׁוֹמֶרֶת אוֹתָהּ תָּמִיד, פְּרִישָׂה שֶׁל לְבוּשׁ הַמֶּלֶךְ שֶׁפּוֹרֵשׂ עָלֶיהָ אֱלוֹהַּ. זֶה בְּבִגְדוֹ בָהּ תָּמִיד, שֶׁלֹּא זָז מִמֶּנָּה, וְזֶהוּ כְּסוּתָהּ.</p>\n<p>וְעֹנָתָהּ, מִי הוּא? זוֹ מְשִׁיכָה מִן הָעוֹלָם הַבָּא שֶׁבּוֹ הַכֹּל. ה' צְבָאוֹת הוּא, וְזֶהוּ שֶׁמֵּאִיר בְּכָל הָאוֹרוֹת הַנִּסְתָּרִים הָעֶלְיוֹנִים שֶׁל עֵץ הַחַיִּים שֶׁבּוֹ שְׁמוּרָה עוֹנָה, שֶׁמִּשָּׁם הִיא יוֹצֵאת, וְכָל זֶה בְּעִדּוּן וּתְשׁוּקָה שֶׁל הָעוֹלָם הַבָּא.</p>\n<p>שְׁלש אֵלֶּה לֹא יִגְרַע לָהּ, כְּשֶׁהִיא זַכָּאִית כָּרָאוּי. וְאִם אֵינָהּ כָּרָאוּי, שְׁלֹשׁ אֵלֶּה נִגְרָעוֹת מִמֶּנָּה, שֶׁלֹּא יַעֲשֶׂה לָהּ עֲטָרָה אֲפִלּוּ מֵאֶחָד מֵהֶם. בֹּא וּרְאֵה מַה כָּתוּב, וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ - שֶׁלֹּא זָכְתָה בָהֶם, וְיָצְאָה חִנָּם אֵין כָּסֶף - תֵּצֵא מִלְּפָנָיו, וְדוֹחֶה אוֹתָהּ הַחוּצָה. אֵין כָּסֶף - אֵין לָהּ כִּסּוּף וְלֹא עִדּוּן כְּלָל.</p>\n<p>עֵד כָּאן מוֹכִיחָה הַתּוֹרָה שֶׁכָּל הָעֵצוֹת תְּלוּיוֹת בָּהּ, וְנוֹתֶנֶת עֵצָה טוֹבָה לִבְנֵי אָדָם. מִכָּאן וָהָלְאָה נַחֲזֹר לַדְּבָרִים הָרִאשׁוֹנִים, בְּאוֹתָהּ שְׁמִירָה עֶלְיוֹנָה שֶׁפּוֹרֵשׂ עָלֶיהָ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁלֹּא תִהְיֶה לְעַם נָכְרִי, שֶׁהֲרֵי בִּגְדוֹ בָהּ, וּשְׁמִירָה הִיא לָהּ תָּמִיד.</p>\n<p>וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ. אָמַר אוֹתוֹ זָקֵן, חֲבֵרִים, כְּשֶׁתֵּלְכוּ לְאוֹתוֹ הַסֶּלַע שֶׁהָעוֹלָם סָמוּךְ עָלָיו, אִמְרוּ לוֹ שֶׁיִּזְכֹּר אֶת יוֹם הַשֶּׁלֶג שֶׁנִּזְרְעוּ פּוֹלִים לַחֲמִשִּׁים וּשְׁנַיִם גְּוָנִים, וְאַחַר כָּךְ קִרְאוּ אֶת הַפָּסוּק הַזֶּה, וְהוּא יֹאמַר לָכֶם.</p>\n<p>אָמְרוּ, בְּבַקָּשָׁה מִמְּךְ, מִי שֶׁהִתְחִיל אֶת הַדָּבָר - הוּא שֶׁיֹּאמַר! אָמַר לָהֶם, וַדַּאי שֶׁיָּדַעְתִּי שֶׁאַתֶּם צַדִּיקִים, וְיֵשׁ לִרְמֹז לָכֶם רֶמֶז שֶׁל חֲכָמִים. וְעַל מַה שֶּׁאֲנִי אוֹמֵר, כְּשֶׁתַּזְכִּירוּ לוֹ סִימָן זֶה, הוּא יַשְׁלִים אֶת זֶה. עַכְשָׁו יֵשׁ לוֹמַר מִי הוּא שֶׁנִּקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא.</p>\n<p>בֹּא וּרְאֵה, כָּל מִי שֶׁהוּא זוֹכֶה לִשְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, נִקְרָא בֵּן לִכְנֶסֶת יִשְׂרָאֵל. וְכָל מִי שֶׁהוּא מִבֶּן עֶשְׂרִים שָׁנָה וָמַעְלָה וְזוֹכֶה בָהֶם, נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא וַדַּאי. (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם.</p>\n<p>כְּשֶׁהִגִּיעַ דָּוִד לִשְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְזָכָה בְּאוֹתוֹ יוֹם שֶׁנִּכְנַס לָאַרְבַּע עֶשְׂרֵה, אָז כָּתוּב (תהלים ב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. מָה הַטַּעַם? שֶׁהֲרֵי מִקֹּדֶם לָזֶה לֹא הָיָה לוֹ בֵּן, וְלֹא שָׁרְתָה עָלָיו נְשָׁמָה עֶלְיוֹנָה, שֶׁהֲרֵי בִּשְׁנוֹת עָרְלָה הוּא הָיָה, וּמִשּׁוּם כָּךְ אֲנִי הַיּוֹם יְלִדְתִּיךְ, הַיּוֹם וַדַּאי יְלִדְתִּיךְ. אֲנִי, וְלֹא הַצַּד הָאַחֵר, כְּמוֹ שֶׁהָיָה עַד עַכְשָׁו, אֲנִי לְבַדִּי. בֶּן עֶשְׂרִים שָׁנִים, מַה כָּתוּב בִּשְׁלֹמֹה? (משלי ד) כִּי בֵן הָיִיתִי לְאָבִי, לְאָבִי מַמָּשׁ וַדַּאי.</p>\n<p>וְאִם לִבְנוֹ יִיעָדֶנָה. בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, שֶׁהֲרֵי יָצָא מֵרְשׁוּת הַצַּד הָאַחֵר שֶׁהִזְדַּמֵּן לוֹ. מַה כָּתוּב? כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ. מַה זֶּה כְּמִשְׁפַּט הַבָּנוֹת? שָׁנִינוּ, בְּכָל יוֹם וָיוֹם רוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ תִינוֹק שֶׁעוֹמֵד בִּרְשׁוּת הָעָרְלָה, וְהוּא יוֹצֵא מִמֶּנָּה וְנִמְשָׁךְ לְבֵית הַסֵּפֶר, וְשׁוֹבֵר אוֹתָהּ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ נְשָׁמָה? מַכְנִיס אוֹתָהּ לַגֹּרֶן (חדר למוד) שֶׁלּוֹ, וְנוֹתֵן לָהּ מַתָּנוֹת וְאוֹצָרוֹת רַבִּים וּמְקַשֵּׁט אוֹתָהּ בְּקִשּׁוּטִים עִלָּאִיִּים, עַד הַזְּמַן שֶׁמַּכְנִיסָהּ לַחֻפָּה עִם אוֹתוֹ (תוך אותו) בֵּן מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה.</p>\n<p>אִם אַחֶרֶת יִקַּח לוֹ. כָּאן יֵשׁ סוֹד הַסּוֹדוֹת שֶׁלַּחֲכָמִים נִמְסְרוּ, וְיֵשׁ לְהוֹדִיעַ בָּרִאשׁוֹנָה דָּבָר אֶחָד. בֹּא וּרְאֵה, בְּיוֹם הַשַּׁבָּת, בְּשָׁעָה שֶׁמִּתְקַדֵּשׁ הַיּוֹם, יוֹצְאוֹת נְשָׁמוֹת מִתּוֹךְ עֵץ הַחַיִּים, וּמְנַשְּׁבוֹת אוֹתָן הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת לַתַּחְתּוֹנִים וְנָחִים בָּהֶם כָּל יוֹם הַשַּׁבָּת. וְאַחַר שֶׁיּוֹצֵאת הַשַּׁבָּת, עוֹלוֹת כָּל הַנְּשָׁמוֹת וּמִתְעַטְּרוֹת בַּעֲטָרוֹת קְדוֹשׁוֹת לְמַעְלָה. (וכשמתעטרותבאותו טוב, אלו הם בעליו של אותו טוב ודאי) אַף כָּאן מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ הָאִישׁ, וְזוֹהִי נְשָׁמָה אַחֶרֶת, וְאַף עַל גַּב שֶׁזּוֹ מְזֻמֶּנֶת לוֹ, הַנְּשָׁמָה שֶׁהָיְתָה לוֹ בָּרִאשׁוֹנָה, שְׁאֵרָהּ הָרִאשׁוֹנָה, כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בָּכָה אוֹתוֹ זָקֵן כְּמִקֹּדֶם, וְהוּא אָמַר לְנַפְשׁוֹ, זָקֵן זָקֵן, כַּמָּה יָגַעְתָּ לְהַשִּׂיג דְּבָרִים קְדוֹשִׁים אֵלּוּ, וְעַכְשָׁו תֹּאמַר אוֹתָם בְּרֶגַע אֶחָד?! אִם תֹּאמַר שֶׁתָּחוּס עַל אוֹתָם הַדְּבָרִים וְלֹא תֹאמַר אוֹתָם - הֲרֵי כָּתוּב (משלי ג) אַל תִּמְנַע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת.</p>\n<p>מַה זֶּה אַל תִּמְנַע טוֹב מִבְּעָלָיו? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל הֵם כָּאן, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁנֶּאֱמָרִים דִּבְרֵי תוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל שָׁם וּמַקְשִׁיבִים לָהֶם. וְאָז אוֹתוֹ עֵץ שֶׁל טוֹב וָרָע, בְּשָׁעָה שֶׁהוֹלְכִים מִשָּׁם וּמַקְשִׁיבִים לְאוֹתָם דְּבָרִים, אוֹתוֹ צַד הַטּוֹב מִתְגַּבֵּר וּמִתְעַלֶּה לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל מִתְעַטְּרִים בְּאוֹתוֹ טוֹב, וְאֵלֶּה הֵם בְּעָלָיו שֶׁל אוֹתוֹ טוֹב.</p>\n<p>זָקֵן זָקֵן, אַתָּה אָמַרְתָּ דְּבָרִים אֵלּוּ וְלֹא יָדַעְתָּ אִם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן, וְאִם אֵלֶּה שֶׁעוֹמְדִים כָּאן זַכָּאִים לַדְּבָרִים הָאֵלֶּה. אַל תִּפְחַד, זָקֵן, שֶׁהֲרֵי הָיִיתָ בְּכַמָּה קְרָבוֹת שֶׁל גְּבָרִים חֲזָקִים וְלֹא פָחַדְתָּ, וְעַכְשָׁו אַתָּה פּוֹחֵד?! אֱמֹר דְּבָרֶיךְ, שֶׁהֲרֵי וַדַּאי כָּאן הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל, וְאַשְׁרֵי הֵם אֵלֶּה שֶׁכָּאן. וְאִם לֹא כָּךְ, לֹא הָיִינוּ פּוֹגְשִׁים אוֹתָם וְלֹא הִתְחַלְנוּ בַּדְּבָרִים הַלָּלוּ. אֱמֹר דִּבּוּרְךְ, זָקֵן, אֱמֹר לְלֹא פַּחַד.</p>\n<p>פָּתַח וְאָמַר, (תהלים קד) ה' אֱלֹהַי גָּדַלְתָּ מְּאֹד הוֹד וְהָדָר לָבָשְׁתָּ. ה' אֱלֹהַי - זוֹ רֵאשִׁית הָאֱמוּנָה, עֲלִיַּת הַמַּחֲשָׁבָה וְהָעוֹלָם הַבָּא, סוֹד אֶחָד בְּלֹא פֵרוּד. גָּדַלְתָּ - זוֹ הָרֵאשִׁית, הַיּוֹם הָרִאשׁוֹן וְאוֹתָם יָמִים עַתִּיקִים, צַד הַיָּמִין. מְאֹד - זֶהוּ צַד הַשְּׂמֹאל.</p>\n<p>הוֹד וְהָדָר לָבָשְׁתָּ - אֵלּוּ שְׁנֵי בַּדֵּי עֲרָבוֹת. עַד כָּאן, כֵּיוָן שֶׁהִגִּיעַ לְתוֹךְ עֵץ הַחַיִּים, נִטְמַן וְלֹא הִתְעַלֶּה לִהְיוֹת בְּמִנְיָן מִשּׁוּם אוֹתוֹ מְאֹד. מַה זֶּה מְאֹד? הַשְּׂמֹאל, שֶׁכָּל הָעֲנָפִים שֶׁלְּמַטָּה וּבִכְלָל עָנָף מַר אֶחָד. וְלָכֵן נִטְמַן אוֹתוֹ עֵץ הַחַיִּים וְלֹא רָצָה לִהְיוֹת בַּמִּנְיָן הַזֶּה, עַד שֶׁחָזַר כְּמוֹ מִקֹּדֶם וְשִׁבַּח בְּגָוֶן אַחֵר.</p>\n<p>וְאָמַר, עֹטֶה אוֹר כַּשַּׂלְמָה - זוֹ רֵאשִׁיתוֹ (של האור) שֶׁל הַיּוֹם הָרִאשׁוֹן. נוֹטֶה שָׁמַיִם - כָּאן נִכְלָל הַשְּׂמֹאל, וְלֹא אָמַר מְאֹד, נִכְלָל הַשְּׂמֹאל בַּיָּמִין לִהְיוֹת מֵאִיר בִּכְלָל שֶׁל שָׁמַיִם. הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו - כָּאן יוֹצֵא בְשִׂמְחָה אוֹתוֹ עֵץ הַחַיִּים, הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְנִשְׁרְשׁוּ בוֹ בְּמֵימָיו אוֹתָם שְׁנֵי בַּדֵּי עֲרָבוֹת, שֶׁהֵם גְּדֵלִים בְּמֵימָיו. זֶהוּ שֶׁכָּתוּב (אותו אילן החיים, ונשרשו בו אותם שני בדי ערבות, שהם גדלים במימיו, ואותו נהר יוצא מעדן, וזהו) (תהלים קד) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. מִי הֵם עֲלִיּוֹתָיו? אֵלּוּ בַּדֵּי עֲרָבוֹת.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב (ירמיה יז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְזֶהוּ סוֹד הַכָּתוּב (תהלים מו) נָהָר פְּלָגָיו יְשַׂמְּחוּ עִיר אֱלֹהִים. מִי הֵם פְּלָגָיו? אֵלּוּ הֵם שָׁרָשָׁיו, וְכָךְ נִקְרָאִים. עֲלִיּוֹתָיו, שָׁרָשָׁיו, פְּלָגָיו - כֻּלָּם נִשְׁרְשׁוּ בְּאוֹתָם הַמַּיִם שֶׁל אוֹתוֹ נָהָר.</p>\n<p>הַשָּׂם עָבִים רְכוּבוֹ - זֶה מִיכָאֵל וְגַבְרִיאֵל, אֵלֶּה הֵם עָבִים. הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ, לָתֵת רְפוּאָה לָעוֹלָם, וְזֶהוּ רְפָאֵל. מִכָּאן וָהָלְאָה עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. זָקֵן זָקֵן, אִם כָּל אֵלֶּה יָדַעְתָּ, אֱמֹר וְאַל תִּפְחַד, אֱמֹר דְּבָרֶיךְ וְיָאִירוּ דִּבְרֵי פִיךְ! שָׂמְחוּ הַחֲבֵרִים, וְהָיוּ מַקְשִׁיבִים בְּשִׂמְחָה לִדְבָרָיו הַקְּדוֹשִׁים. אָמַר, אִי זָקֵן, אִי זָקֵן, בַּמָּה הִכְנַסְתָּ אֶת עַצְמְךְ, נִכְנַסְתָּ לַיָּם הַגָּדוֹל? יֵשׁ לְךְ לְשׁוֹטֵט וְלָצֵאת מִשָּׁם.</p>\n<p>אִם אַחֶרֶת יִקַּח לוֹ. כַּמָּה גִלְגּוּלִים עַתִּיקִים יֵשׁ כָּאן שֶׁלֹּא הִתְגַּלּוּ עַד עַכְשָׁו, וְכֻלָּם אֱמֶת כָּרָאוּי, שֶׁאֵין לִסְטוֹת מִדֶּרֶךְ אֱמֶת אֲפִלּוּ כִּמְלֹא נִימָה. בַּתְּחִלָּה (עתה) יֵשׁ לְהִתְעוֹרֵר, נִשְׁמוֹת הַגֵּרִים כֻּלָּן פּוֹרְחוֹת מִתּוֹךְ גַּן עֵדֶן בְּדֶרֶךְ נִסְתָּר. כְּשֶׁמִּסְתַּלְּקוֹת מִן הָעוֹלָם הַזֶּה, נִשְׁמוֹתָם שֶׁהִרְוִיחוּ מִתּוֹךְ גַּן הָעֵדֶן, לְאֵיזֶה מָקוֹם חוֹזְרוֹת?</p>\n<p>אֶלָּא שָׁנִינוּ, מִי שֶׁנּוֹטֵל וְאוֹחֵז בְּנִכְסֵי הַגֵּר בַּתְּחִלָּה, זוֹכֶה בָהֶם. אַף כָּךְ כָּל אוֹתָן הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת שֶׁמַּזְמִין אוֹתָן הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, כְּפִי שֶׁאָמַרְנוּ, כֻּלָּן יוֹצְאוֹת לִזְמַנִּים יְדוּעִים, (ועולות) כְּדֵי לְהִשְׁתַּעֲשֵׁעַ בְּגַן עֵדֶן (העליון), וּפוֹגְעוֹת בְּאוֹתָן נִשְׁמוֹת הַגֵּרִים. מִי שֶׁאוֹחֵז בָּהֶן מֵאוֹתָן הַנְּשָׁמוֹת (שעולות), אוֹחֵז בָּהֶם וְזוֹכֶה בָהֶם, וּמִתְלַבְּשִׁים בָּהֶם וְעוֹלִים. וְכֻלָּן עוֹמְדוֹת בִּלְבוּשׁ זֶה, וְיָרְדוּ לְתוֹךְ הַגָּן בַּלְּבוּשׁ הַזֶּה, מִשּׁוּם שֶׁבְּגַן עֵדֶן לֹא עוֹמְדוֹת שָׁם אֶלָּא בִּלְבוּשׁ כָּל אֵלּוּ שֶׁעוֹמְדוֹת שָׁם.</p>\n<p>אִם תֹּאמַר שֶׁבִּשְׁבִיל הַלְּבוּשׁ הַזֶּה גּוֹרְעִים אוֹתָן נְשָׁמוֹת מִכָּל הָעֹנֶג שֶׁהָיָה לָהֶן בַּתְּחִלָּה, הֲרֵי כָּתוּב אִם אַחֶרֶת יִקַּח לוֹ שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע? בַּגָּן עוֹמְדוֹת בִּלְבוּשׁ זֶה, שֶׁקָּדְמוּ לֶאֱחֹז בָּהֶם וְזוֹכוֹת בָּהֶם, וּכְשֶׁעוֹלוֹת לְמַעְלָה מִתְפַּשְּׁטוֹת מִמֶּנּוּ, שֶׁהֲרֵי שָׁם לֹא עוֹמְדוֹת בִּלְבוּשׁ.</p>\n<p>בָּכָה אוֹתוֹ זָקֵן כְּמִקֹּדֶם וְאָמַר לְנַפְשׁוֹ, זָקֵן זָקֵן, בְּוַדַּאי יֵשׁ לְךְ לִבְכּוֹת, בְּוַדַּאי יֵשׁ לְךְ לִשְׁפֹּךְ דְּמָעוֹת עַל כָּל דָּבָר וְדָבָר, אֲבָל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ הַקְּדוֹשָׁה שֶׁאֲנִי בִּרְצוֹן הַלֵּב וּבַעֲבוֹדָתָם אָמַרְתִּי, מִשּׁוּם שֶׁהֵם בְּעָלָיו שֶׁל כָּל דָּבָר וּמִתְעַטְּרִים בָּהֶם.</p>\n<p>כָּל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, כְּשֶׁיּוֹרְדוֹת לָעוֹלָם הַזֶּה כְּדֵי לִשְׁרוֹת כָּל אַחַת עַל מְקוֹמָן שֶׁרְאוּיִים לָהֶם לִבְנֵי אָדָם, כֻּלָּן יוֹרְדוֹת מְלֻבָּשׁוֹת בְּאוֹתָן הַנְּשָׁמוֹת שֶׁאָמַרְנוּ, וְכָךְ נִכְנָסוֹת לְזֶרַע הַקֹּדֶשׁ. וּבְמַלְבּוּשׁ זֶה עוֹמְדוֹת לְהִשְׁתַּעְבֵּד מֵהֶם בָּעוֹלָם הַזֶּה. וּכְשֶׁנִּשְׁאָבִים אוֹתָם לְבוּשִׁים מִדִּבְרֵי הָעוֹלָם הַזֶּה, אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת נִזּוֹנוֹת (נהנות) מֵהָרֵיחַ שֶׁמֵּרִיחַ מִתּוֹךְ הַלְּבוּשִׁים הַלָּלוּ.</p>\n<p>כָּל הַדְּבָרִים הַנִּסְתָּרִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה, הִכְנִיס אוֹתָם לַתּוֹרָה הַקְּדוֹשָׁה, וְהַכֹּל נִמְצָא בַּתּוֹרָה, וְאוֹתוֹ דָבָר נִסְתָּר גִּלְּתָה אוֹתוֹ הַתּוֹרָה, וּמִיָּד הִתְלַבֵּשׁ בִּלְבוּשׁ אַחֵר, וְנִטְמַן שָׁם וְלֹא הִתְגַּלָּה. וְהַחֲכָמִים שֶׁהֵם מְלֵאִים עֵינַיִם, אַף עַל גַּב שֶׁאוֹתוֹ הַדָּבָר נִסְתָּר בִּלְבוּשׁוֹ (שם), רוֹאִים אוֹתוֹ מִתּוֹךְ לְבוּשׁוֹ, וּבְשָׁעָה שֶׁהִתְגַּלָּה אוֹתוֹ דָבָר, טֶרֶם יִכָּנֵס לַלְּבוּשׁ, זוֹרְקִים בּוֹ פְּקִיחַת עַיִן, וְאַף עַל גַּב שֶׁמִּיָּד נִסְתָּר, לֹא נֶאֱבָד מֵעֵינֵיהֶם (נ\"א מהם).</p>\n<p>בְּכַמָּה מְקוֹמוֹת הִזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַגֵּר (כדי) שֶׁיִּזָּהֲרוּ בוֹ זֶרַע הַקֹּדֶשׁ, וְאַחַר הוֹצִיא דָבָר נִסְתָּר מִנַּרְתִּיקוֹ. וְכֵיוָן שֶׁהִתְגַּלָּה, חוֹזֵר מִיָּד לְנַרְתִּיקוֹ וְהִתְלַבֵּשׁ שָׁם.</p>\n<p>כֵּיוָן שֶׁהִזְהִיר עַל הַגֵּר בְּכָל אוֹתָם מְקוֹמוֹת, יָצָא הַדָּבָר מִנַּרְתִּיקוֹ וְהִתְגַּלָּה וְאָמַר, וְאַתֶּם יְדַעְתֶּם אֶת נֶפֶשׁ הַגֵּר. מִיָּד נִכְנְסָה לְנַרְתִּיקָהּ, וְחָזְרָה בִּלְבוּשׁ וְנִטְמְנָה, שֶׁכָּתוּב כִּי גֵרִים הֱיִיתֶם בְּאֶרֶץ מִצְרָיִם, שֶׁחָשַׁב הַכָּתוּב, שֶׁבִּגְלַל שֶׁמִּיָּד הִתְלַבֵּשׁ, לֹא הָיָה מִי שֶׁיַּשְׁגִּיחַ בּוֹ. בְּנֶפֶשׁ הַגֵּר הַזּוֹ יוֹדַעַת הַנְּשָׁמָה הַקְּדוֹשָׁה בְּדִבְרֵי הָעוֹלָם הַזֶּה וְנֶהֱנֵית (ושואבת) מֵהֶם.</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (שם כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר וְגוֹ'. עָנָן זֶה מַהוּ? אֶלָּא זֶהוּ הַכָּתוּב (בראשית ט) אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. שָׁנִינוּ שֶׁאוֹתָהּ קֶשֶׁת הִפְשִׁיטָה אֶת לְבוּשֶׁיהָ וְנָתְנָה אוֹתָם לְמֹשֶׁה, וּבְאוֹתוֹ לְבוּשׁ עָלָה מֹשֶׁה לָהָר, וּמִמֶּנּוּ רָאָה מַה שֶּׁרָאָה וְנֶהֱנָה מֵהַכֹּל. עַד אוֹתוֹ מָקוֹם בָּאוּ אוֹתָם הַחֲבֵרִים, וְהִשְׁתַּטְּחוּ לִפְנֵי אוֹתוֹ זָקֵן וּבָכוּ וְאָמְרוּ, אִלְמָלֵא לֹא בָאנוּ לָעוֹלָם אֶלָּא כְּדֵי לִשְׁמֹעַ דְּבָרִים אֵלּוּ מִפִּיךְ - דַּי לָנוּ!</p>\n<p>אָמַר אוֹתוֹ זָקֵן, (אם אחרת יקח לו) חֲבֵרִים, לֹא בִּשְׁבִיל זֶה בִּלְבַד הִתְחַלְתִּי אֶת הַדָּבָר, שֶׁהֲרֵי זָקֵן כָּמוֹנִי לֹא בְּדָבָר אֶחָד עוֹשֶׂה קִישׁ קִישׁ וְלֹא קוֹרֵא, כַּמָּה בְּנֵי הָעוֹלָם שֶׁהֵם בְּעִרְבּוּבְיָה בַּתְּבוּנָה שֶׁלָּהֶם, וְלֹא רוֹאִים בְּדֶרֶךְ אֱמֶת בַּתּוֹרָה, וְתוֹרָה קוֹרֵאת בְּכָל יוֹם בִּנְהִימָה (באהבה) אֲלֵיהֶם, וְלֹא רוֹצִים לְהָשִׁיב רֹאשָׁם.</p>\n<p>וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁהֲרֵי הַתּוֹרָה הוֹצִיאָה דָבָר מִנַּרְתִּיקָהּ, וְנִרְאָה קָטָן וּמִיָּד נִטְמַן - כָּךְ הוּא וַדַּאי. וּבִזְמַן שֶׁנִּתְגַּלָּה מִתּוֹךְ נַרְתִּיקָהּ וְנִטְמַן מִיָּד, לֹא עוֹשֶׂה אֶת זֶה אֶלָּא לְאוֹתָם שֶׁיּוֹדְעִים בָּהּ וְנוֹדָעִים בָּהּ.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לַאֲהוּבָה, שֶׁהִיא יָפָה בְּמַרְאֶה וְיָפָה בְּתֹאַר, וְהִיא טְמוּנָה בְּהֶסְתֵּר בְּתוֹךְ הַהֵיכָל שֶׁלָּהּ, וְיֵשׁ לָהּ אוֹהֵב יְחִידִי שֶׁלֹּא יוֹדְעִים עָלָיו בְּנֵי אָדָם, אֶלָּא שֶׁהוּא בְּנִסְתָּר. אוֹתוֹ אוֹהֵב, מִתּוֹךְ הָאַהֲבָה שֶׁאוֹהֵב אוֹתָהּ, עוֹבֵר עַל שַׁעַר בֵּיתָהּ תָּמִיד, מֵרִים עֵינָיו לְכָל צַד. הִיא יוֹדַעַת שֶׁהֲרֵי הָאוֹהֵב סוֹבֵב שַׁעַר בֵּיתָהּ תָּמִיד. מָה עוֹשָׂה? פּוֹתַחַת פֶּתַח קָטָן בְּאוֹתוֹ הֵיכָל נִסְתָּר שֶׁהִיא שָׁם וּמְגַלָּה אֶת פָּנֶיהַ לְאוֹהֲבָהּ, וּמִיָּד חוֹזֶרֶת וְנִתְכַּסֵּית. כָּל אוֹתָם שֶׁהָיוּ אֵצֶל הָאוֹהֵב, לֹא רָאוּ וְלֹא הִסְתַּכְּלוּ, פְּרָט לָאוֹהֵב לְבַדּוֹ, וּמֵעָיו וְלִבּוֹ וְנַפְשׁוֹ הָלְכוּ אַחֲרֶיהָ. וְיוֹדֵעַ שֶׁמִּתּוֹךְ הָאַהֲבָה שֶׁהִיא אוֹהֶבֶת אוֹתוֹ, נִגְלֵית אֵלָיו רֶגַע אֶחָד לְעוֹרֵר (אליו אהבה) אוֹתוֹ. כָּךְ הוּא דְּבַר הַתּוֹרָה לֹא נִגְלֶה אֶלָּא לְאוֹהֲבוֹ. יוֹדַעַת הַתּוֹרָה שֶׁאוֹתוֹ חֲכַם לֵב סוֹבֵב שַׁעַר בֵּיתָהּ כָּל יוֹם. מַה הִיא עוֹשָׂה? מְגַלָּה פָנֶיהָ אֵלָיו מִתּוֹךְ הַהֵיכָל, וְרוֹמֶזֶת לוֹ רֶמֶז, וּמִיָּד חוֹזֶרֶת לִמְקוֹמָהּ וְנִסְתֶּרֶת. כָּל אֵלּוּ שֶׁשָּׁם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים, אֶלָּא רַק הוּא בִּלְבַדּוֹ, וּמֵעָיו וְלִבּוֹ וְנַפְשׁוֹ הוֹלְכִים אַחֲרֶיהָ, וְעַל זֶה הַתּוֹרָה נִגְלֵית וְנִכְסֵית וְהוֹלֶכֶת בְּאַהֲבָה לַאֲהוּבָה לְעוֹרֵר עִמּוֹ אַהֲבָה.</p>\n<p>בֹּא וּרְאֵה, כָּךְ הִיא דַּרְכָּהּ שֶׁל תּוֹרָה: בָּרִאשׁוֹנָה כְּשֶׁמַּתְחִילָה לְהִתְגַּלּוֹת אֶל הָאָדָם, (ברגע) רוֹמֶזֶת לוֹ בְּרֶמֶז. אִם יוֹדֵעַ - אָז טוֹב, וְאִם לֹא יוֹדֵעַ - שׁוֹלַחַת אֵלָיו וְקוֹרֵאת לוֹ פֶּתִי. וְהַתּוֹרָה אוֹמֶרֶת לְאוֹתוֹ שֶׁשָּׁלְחָה אֵלָיו: אִמְרוּ לְאוֹתוֹ הַפֶּתִי שֶׁיִּקְרַב לְכָאן וַאֲדַבֵּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב וְגוֹ'. קָרַב אֵלֶיהָ, וּמַתְחִילָה לְדַבֵּר עִמּוֹ מֵאַחַר פָּרֹכֶת שֶׁפּוֹרֶשֶׂת לוֹ דְּבָרִים לְפִי דַרְכּוֹ, עַד שֶׁיִּתְבּוֹנֵן לְאַט לְאַט, וְזֶהוּ הַדְּרָשׁ.</p>\n<p>אַחַר כָּךְ תְּדַבֵּר עִמּוֹ מֵאַחַר פִּשְׁפֵּשׁ קָטָן דִּבְרֵי חִידָה, וְזוֹהִי הַגָּדָה. אַחַר שֶׁהִתְרַגֵּל אֵלֶיהָ, נִגְלֵית אֵלָיו פָּנִים בְּפָנִים וּמְדַבֶּרֶת עִמּוֹ כָּל הַסּוֹדוֹת הַנִּסְתָּרִים שֶׁלָּהּ, וְכָל הַדְּרָכִים הַנִּסְתָּרוֹת שֶׁהָיוּ שְׁמוּרִים בְּלִבָּהּ מִיָּמִים רִאשׁוֹנִים, וְאָז אוֹתוֹ אָדָם הוּא שָׁלֵם, בַּעַל תּוֹרָה וַדַּאי, בַּעַל הַבַּיִת, שֶׁהֲרֵי כָּל סוֹדוֹתֶיהָ גִּלְּתָה לוֹ, וְלֹא רִחֲקָה וְלֹא כִסְּתָה מִמֶּנּוּ כְּלוּם.</p>\n<p>אוֹמֶרֶת לוֹ, רָאִיתָ דְּבַר הָרֶמֶז שֶׁרָמַזְתִּי לְךְ בַּתְּחִלָּה? כָּךְ וְכָךְ הָיוּ הַסּוֹדוֹת, כָּךְ וְכָךְ הוּא. וְאָז רוֹאֶה (שהעליונים) שֶׁעַל הַדְּבָרִים הַלָּלוּ אֵין לְהוֹסִיף וְאֵין לִגְרֹעַ מֵהֶם, וְאָז פְּשַׁט הַכָּתוּב כְּמוֹ שֶׁהוּא, שֶׁלֹּא לְהוֹסִיף וְלֹא לִגְרֹעַ אֲפִלּוּ אוֹת אַחַת. וְעַל כָּךְ אֲנָשִׁים צְרִיכִים לְהִזָּהֵר וְלִרְדּף אַחֲרֵי הַתּוֹרָה לִהְיוֹת אוֹהֲבִים שֶׁלָּהּ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא וּרְאֵה, אִם אַחֶרֶת יִקַּח לוֹ. הַגִּלְגּוּלִים שֶׁמִּתְגַּלְגְּלִים בַּפָּסוּק הַזֶּה כַּמָּה גְדוֹלִים וְעֶלְיוֹנִים הֵם, שֶׁהֲרֵי כָּל הַנְּשָׁמוֹת נִכְנָסוֹת בְּגִלְגּוּל, וְלֹא יוֹדְעִים בְּנֵי אָדָם דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵיךְ עוֹמְדִים הַמֹּאזְנַיִם וְאֵיךְ נִדּוֹנִים בְּנֵי אָדָם בְּכָל יוֹם וּבְכָל זְמַן, וְאֵיךְ נְשָׁמוֹת נִכְנָסוֹת לַדִּין עַד שֶׁלֹּא בָאוֹת לָעוֹלָם הַזֶּה, וְאֵיךְ נִכְנָסוֹת לַדִּין אַחַר שֶׁיּוֹצְאוֹת מִן הָעוֹלָם הַזֶּה.</p>\n<p>כַּמָּה גִלְגּוּלִים וְכַמָּה מַעֲשִׂים נִסְתָּרִים עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כַּמָּה נְשָׁמוֹת מְעֻרְטָלוֹת, וְכַמָּה רוּחוֹת מְעֻרְטָלוֹת הוֹלְכוֹת בְּאוֹתוֹ הָעוֹלָם שֶׁלֹּא נִכְנָסוֹת לַפַּרְגּוֹד שֶׁל הַמֶּלֶךְ, וְכַמָּה עוֹלָמוֹת מִתְהַפֵּךְ בָּהֶם, וְהָעוֹלָם שֶׁמִּתְהַפֵּךְ בְּכַמָּה פְלָאִים נִסְתָּרִים, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים, וְאֵיךְ מִתְגַּלְגְּלוֹת הַנְּשָׁמוֹת כְּאֶבֶן בְּכַף הַקֶּלַע, כְּמוֹ שֶׁנֶּאֱמַר וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.</p>\n<p>(והואיל והתחלנו לגלות) עַכְשָׁו יֵשׁ לְגַלּוֹת, שֶׁהֲרֵי כָּל הַנְּשָׁמוֹת מֵהָאִילָן הַגָּדוֹל וְהַתַּקִּיף, שֶׁהוּא הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, יוֹצְאוֹת, וְכָל הָרוּחוֹת מֵעֵץ אַחֵר קָטָן יוֹצְאוֹת. הַנְּשָׁמָה מִלְמַעְלָה וְהָרוּחַ מִלְּמַטָּה, וּמִתְחַבְּרוֹת כְּאַחַת כְּמוֹ זָכָר וּנְקֵבָה. וְכַאֲשֶׁר מִתְחַבְּרוֹת כְּאַחַת, אָז מְאִירוֹת אוֹר עֶלְיוֹן, וּבְחִבּוּר שֶׁל שְׁנֵיהֶם נִקְרָא נֵר. נֵר ה' נִשְׁמַת אָדָם. מַהוּ נֵ\"ר? נְ'שָׁמָה ר'וּחַ. וְעַל הַחִבּוּר שֶׁל שְׁנֵיהֶם כְּאֶחָד נִקְרָא נֵר, שֶׁכָּתוּב (משליב) נֵר ה' נִשְׁמַת אָדָם.</p>\n<p>נְשָׁמָה וְרוּחַ - זָכָר וּנְקֵבָה לְהָאִיר כְּאֶחָד, וְזֶה בְּלִי זֶה לֹא מְאִירִים וְלֹא נִקְרָא נֵר. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, הַכֹּל נִקְרָא נֵר. וְאָז מִתְעַטֶּפֶת הַנְּשָׁמָה בְּרוּחַ לַעֲמֹד שָׁם לְמַעְלָה בַּהֵיכָל הַגָּנוּז, שֶׁכָּתוּב (ישעיה נז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. לֹא כָתוּב יִתְעַטֵּף, אֶלָּא יַעֲטוֹף, מָה הַטַּעַם? מִשּׁוּם שֶׁנְּשָׁמוֹת אֲנִי עָשִׂיתִי. שָׁם לְמַעְלָה בַּגָּן, בַּהֵיכָל הַגָּנוּז, מִתְעַטֶּפֶת וּמִתְלַבֶּשֶׁת הַנְּשָׁמָה בְּרוּחַ כְּמוֹ שֶׁרָאוּי.</p>\n<p>וְכֵיוָן שֶׁבְּאוֹתוֹ הֵיכָל לֹא הָיָה וְלֹא הִשְׁתַּמֵּשׁ אֶלָּא בְּרוּחַ וּנְשָׁמָה, הַנֶּפֶשׁ לֹא בָאָה לְשָׁם (משם), אֶלָּא מִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ שָׁם, וּכְשֶׁיּוֹרֶדֶת לְתוֹךְ גַּן עֵדֶן הַתַּחְתּוֹן, (בעולם הזה) מִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ אַחֶרֶת שֶׁאָמַרְנוּ, אוֹתָהּ שֶׁיָּצְאָה מִשָּׁם וְהָיְתָה מִשָּׁם, וּבְכֻלָּן הִיא שׁוֹרָה בָּעוֹלָם הַזֶּה וּמִתְלַבֶּשֶׁת בָּהֶם.</p>\n<p>אוֹתָהּ רוּחַ שֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה, שֶׁלֹּא הִתְרַבְּתָה (שלא נטהרה) וְלֹא הִתְפַּשְּׁטָה בָּעוֹלָם הַזֶּה, הוֹלֶכֶת בְּגִלְגּוּל וְלֹא מוֹצֵאת מְנוּחָה. בָּאָה בְּגִלְגּוּל בָּעוֹלָם כְּאֶבֶן בְּכַף הַקָּלַע, עַד שֶׁיִּמָּצֵא אוֹתוֹ גוֹאֵל שֶׁיִּגְאֲלֶנָּה, וּמֵבִיא אוֹתוֹ בְּאוֹתוֹ כְּלִי מַמָּשׁ שֶׁהוּא הָיָה מִשְׁתַּמֵּשׁ בּוֹ, וּמַדְבִּיק בּוֹ תָּמִיד רוּחוֹ וְנַפְשׁוֹ, וְהָיְתָה בַּת זוּגוֹ, רוּחַ בְּרוּחַ, וְאוֹתוֹ הַגּוֹאֵל בּוֹנֶה אוֹתוֹ כְּמִקֹּדֶם.</p>\n<p>וְאוֹתָהּ רוּחַ שֶׁהִשְׁאִיר וְנִדְבְּקָה בְּאוֹתוֹ הַכְּלִי, לֹא נֶאֶבְדָה. שֶׁהֲרֵי אֵין אֲפִלּוּ דָּבָר קָטָן בָּעוֹלָם שֶׁאֵין לוֹ אֲתַר וּמָקוֹם לְהִטָּמֵן וּלְהִתְכַּנֵּס לְשָׁם, וְלֹא נֶאֱבָד לְעוֹלָמִים. וּמִשּׁוּם כָּךְ, אוֹתָהּ הָרוּחַ שֶׁהִשְׁאִיר בְּאוֹתוֹ כְּלִי שָׁם, הוּא וַדַּאי רוֹדֵף אַחַר הָעִקָּר וְהַיְסוֹד שֶׁלּוֹ שֶׁיָּצָא מִמֶּנּוּ, וּמֵבִיא אוֹתוֹ וּבוֹנֶה אוֹתוֹ בִּמְקוֹמוֹ, בְּמָקוֹם שֶׁל אוֹתָהּ רוּחַ בַּת זוּגוֹ שֶׁיָּצְאָה עִמּוֹ, וְנִבְנֶה שָׁם כְּמִקֹּדֶם, וְזוֹהִי בְּרִיָּה חֲדָשָׁה עַכְשָׁו בָּעוֹלָם, רוּחַ חֲדָשָׁה וְגוּף חָדָשׁ.</p>\n<p>וְאִם תֹּאמַר, רוּחַ זוֹ הִיא מַה שֶּׁהָיָה - כָּךְ זֶה, אֲבָל לֹא נִבְנֵית אֶלָּא בִּשְׁבִיל אוֹתָהּ רוּחַ אַחֶרֶת שֶׁהִשְׁאִיר בְּאוֹתוֹ כְּלִי. כָּאן יֵשׁ סוֹדוֹת (סוד הסודות באותו כלי). בְּסִפְרוֹ שֶׁל חֲנוֹךְ, בִּנְיָן זֶה שֶׁנִּבְנֶה, לֹא נִבְנֶה אֶלָּא בְּאוֹתָהּ רוּחַ אַחֶרֶת שֶׁהִשְׁאִיר שָׁם, בְּאוֹתוֹ הַכְּלִי. וּכְשֶׁהִתְחִיל לְהִבָּנוֹת, זֶה מוֹשֵׁךְ אַחֲרָיו שֶׁל אוֹתָהּ רוּחַ שֶׁהוֹלֶכֶת עַרְטִילָאִית וּמוֹשֵׁךְ אוֹתָהּ אֵלָיו, וְשָׁם שְׁתֵּי רוּחוֹת שֶׁהֵן אַחַת. אַחַר כָּךְ זוֹהִי רוּחַ, וְזוֹהִי נְשָׁמָה, וּשְׁתֵּיהֶן אַחַת.</p>\n<p>אִם זָכָה לְהִטָּהֵר כָּרָאוּי, שְׁתֵּיהֶן הֵן אַחַת לְהִתְלַבֵּשׁ בָּהֶן נְשָׁמָה אַחֶרֶת עֶלְיוֹנָה. כְּמוֹ שֶׁיֵּשׁ לִשְׁאָר בְּנֵי הָעוֹלָם רוּחַ שֶׁזּוֹכוֹת בָּהֶן הַנְּשָׁמוֹת, אוֹתָן שֶׁקּוֹדְמוֹת וְאוֹחֲזוֹת בָּהֶן, וְרוּחַ אַחֶרֶת מִלְמַעְלָה, וְהַנְּשָׁמָה הַקְּדוֹשָׁה הִתְלַבְּשָׁה בָהֶן - אַף כָּךְ גַּם מִשֶּׁלּוֹ מַמָּשׁ יֵשׁ שְׁתֵּי רוּחוֹת כְּדֵי לְהַלְבִּישׁ בָּהֶן הַנְּשָׁמָה הָעֶלְיוֹנָה.</p>\n<p>יִהְיְהִ לָזֶה גּוּף אַחֵר שֶׁנִּבְנֶה עַכְשָׁו חָדָשׁ. אוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, מַה נַּעֲשֶׂה מִמֶּנּוּ? אוֹ שֶׁזֶּה בְּרֵיקָנוּת, אוֹ שֶׁזֶּה בְּרֵיקָנוּת. לְפִי תְבוּנַת אָדָם נִשְׁמָע, שֶׁהָרִאשׁוֹן הַזֶּה שֶׁלֹּא נִשְׁתַּלֵּם בַּתְּחִלָּה נֶאֱבָד, הוֹאִיל וְלֹא זָכָה. אִם כָּךְ, לְחִנָּם הִשְׁתַּדֵּל בְּמִצְווֹת הַתּוֹרָה, אוֹ אֲפִלּוּ בְּאַחַת מֵהֶן? וַהֲרֵי אָנוּ יוֹדְעִים שֶׁאֲפִלּוּ רֵיקָנִים שֶׁבְּיִשְׂרָאֵל, כֻּלָּם מְלֵאִים מִצְווֹת כָּרִמּוֹן. וְגוּף זֶה, אַף עַל גַּב שֶׁלֹּא הִשְׁתַּלֵּם לְהִתְרַבּוֹת וְלִזְכּוֹת וּלְהִשְׁתַּדֵּל בָּעוֹלָם, מִצְווֹת אֲחֵרוֹת שֶׁל הַתּוֹרָה הוּא שָׁמַר, שֶׁלֹּא נֶאֶבְדוּ מִמֶּנּוּ, וְכִי לְחִנָּם הֵם הָיוּ?</p>\n<p>חֲבֵרִים חֲבֵרִים, פִּקְחוּ עֵינֵיכֶם, שֶׁהֲרֵי אֲנִי יָדַעְתִּי שֶׁכָּךְ אַתֶּם סְבוּרִים וְיוֹדְעִים, (היעלה על הדעת) שֶׁכָּל אוֹתָם גּוּפִים נִצְטַיְּרוּ הֵם בְּרֵיקָנוּת, שֶׁאֵין לָהֶם קִיּוּם לְעוֹלָמִים. לֹא כָּךְ, וְחָס לָנוּ לְהִסְתַּכֵּל בַּדְּבָרִים הַלָּלוּ.</p>\n<p>פָּתַח הַזָּקֵן וְאָמַר, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. מִי הוּא בָּעוֹלָם שֶׁיָּכוֹל לְמַלֵּל הַגְּבוּרוֹת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם תָּמִיד? אוֹתוֹ גוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, לֹא נֶאֱבָד, וְיִהֶיה לוֹ קִיּוּם לֶעָתִיד לָבֹא, שֶׁהֲרֵי אֶת עָנְשׁוֹ סָבַל בְּכַמָּה מִינִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְקַפֵּחַ שְׂכַר שׁוּם בְּרִיּוֹת שֶׁבָּרָא, פְּרָט לְאוֹתָם שֶׁיָּצְאוּ מִתּוֹךְ הָאֱמוּנָה שֶׁלּוֹ וְלֹא הָיָה בָהֶם טוֹב לְעוֹלָמִים, וּפְרָט לְאֵלּוּ שֶׁלֹּא כָרְעוּ בְּמוֹדִים, שֶׁמֵּאֵלֶּה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרִיּוֹת אֲחֵרוֹת, כְּדֵי שֶׁלֹּא יִבָּנֶה בְּאוֹתוֹ הַגּוּף בִּדְמוּת שֶׁל אָדָם וְלֹא יָקוּם לְעוֹלָמִים. אֲבָל אֵלֶּה לֹא כָּךְ.</p>\n<p>מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? אִם אוֹתָהּ רוּחַ זוֹכָה לְהִתְתַּקֵּן בָּעוֹלָם הַזֶּה בְּאוֹתוֹ הַגּוּף הָאַחֵר, מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? אוֹתוֹ הַגּוֹאֵל שֶׁגּוֹאֵל אוֹתָהּ, אוֹתָהּ הָרוּחַ שֶׁלּוֹ שֶׁמַּכְנִיס לְשָׁם, וּמְשַׁתֵּף וּמְעָרֵב בְּאוֹתָהּ רוּחַ שֶׁהָיְתָה בְּאוֹתוֹ הַכְּלִי, וַדַּאי שֶׁלֹּא נֶאֱבֶדֶת. וּמַה נַּעֲשֶׂה? שֶׁהֲרֵי יֵשׁ שָׁם שָׁלֹשׁ רוּחוֹת (באותו גוף אחר בו יקום. ומה עשה הקדוש ברוך הוא, ' בא וראה, הגאלה ההיא שהיה גואל אותה, רוח שלו הרי נכנסת שם ונעזבת, ומשתתפת ומתערבת בכלי ההוא. ואותה הרוח הראשונה שהיתה באותו כלי ונדבקת בו, ודאי שגשארת שם ולא נאבדת, ומשוםזהאותההרוח שעזבבאותו הכליונדבקה שם, הוא רודף אחר השרש שלו והיסוד שלו שהיה יוצא ממגו ומביאו אליו, ובונה אותו במקום שהיתה בת זוגו. הרי שלש רוחות שם) - אַחַת שֶׁהָיְתָה בְּאוֹתוֹ הַכְּלִי וְנִשְׁאֲרָה שָׁם, וְאַחַת אוֹתָהּ שֶׁנִּמְשְׁכָה לְשָׁם וְהָיְתָה עַרְטִילָאִית, וְאַחַת אוֹתָהּ שֶׁהִכְנִיס לְשָׁם אוֹתוֹ הַגּוֹאֵל וְהִתְעָרֵב בָּהֶן. לִהְיוֹת שָׁלֹשׁ רוּחוֹת אִי אֶפְשָׁר, וּמָה נַעֲשֶׂה?</p>\n<p>אֶלָּא כָּךְ הֵן הַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. אוֹתָהּ רוּחַ שֶׁהִכְנִיס לְשָׁם אוֹתוֹ הַגּוֹאֵל, בּוֹ הִתְלַבְּשָׁה הַנְּשָׁמָה הַזּוֹ בְּמָקוֹם שֶׁל לְבוּשׁ הַגֵּרִים, (והוא) וְאוֹתָהּ רוּחַ עַרְטִילָאִית שֶׁשָּׁבָה שָׁם לְהִבָּנוֹת לִהְיוֹת לְבוּשׁ לַנְּשָׁמָה הָעֶלְיוֹנָה. וְאוֹתָהּ רוּחַ שֶׁהָיְתָה בַּתְּחִלָּה שֶׁנִּשְׁאֲרָה בְּאוֹתוֹ כְלִי, פָּרְחָה מִשָּׁם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לָהּ מָקוֹם בְּתוֹךְ סוֹדוֹת הַחַלּוֹנוֹת שֶׁבַּסֶּלַע שֶׁאַחַר כִּתְפֵי הַגָּן עֵדֶן, וְנִטְמֶנֶת שָׁם. וּמִתְעַלָּה לְאוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהָיָה בַּתְּחִלָּה, וּבְאוֹתָהּ רוּחַ יָקוּם אוֹתוֹ הַגּוף, וְזֶהוּ אֶחָד מֵאוֹתָם הַשְּׁנַיִם שֶׁאָמַרְנוּ (למעלה).</p>\n<p>אֲבָל אוֹתוֹ הַגּוּף טֶרֶם שֶׁיָּקוּם עָנְשׁוֹ גָּדוֹל, שֶׁהֲרֵי מִשּׁוּם שֶׁלֹּא זָכָה לְהִתְרַבּוֹת, הוֹרִידוּ אוֹתוֹ לְתוֹךְ הָאֲדָמָה, שֶׁסְּמוּכָה לְאַרְקָא, וְנִדּוֹן שָׁם. וְאַחַר כָּךְ מַעֲלִים אוֹתוֹ לַתֵּבֵל הַ את. עַכְשָׁו יוֹרֵד וְעַכְשָׁו עוֹלֶה, הִנֵּה עָלָה וְהִנֵּה יָרַד, אֵין לוֹ מְנוּחָה, פְּרָט לְשַׁבָּתוֹת וְיָמִים טוֹבִים וּבְרָאשֵׁי חֳדָשִׁים.</p>\n<p>וְאֵלֶּה יְשֵׁנִים בְּאַדְמַת עָפָר. אַדְמַת - מֵאֲדָמָה. עָפָר - מִתֵּבֵל. וְעַל אֵלּוּ כָּתוּב (דניאליב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. כָּל אֵלֶּה שֶׁלֹּא זָכוּ לְהִתְתַּקֵּן. אֲבָל אִם זָכְתָה אוֹתָהּ רוּחַ עַרְטִילָאִית שֶׁשָּׁבָה כְּמוֹ מִקֹּדֶם לְהִתְתַּקֵּן, אָז צַדִּיק הוּא, שֶׁהֲרֵי אוֹתָהּ רוּחַ שֶׁנֶּאֱמַר בָּהּ שֶׁנִּשְׁמְרָה בַּסֶּלַע, תְּתֻקַּן בְּאוֹתוֹ הַגּוּף הָרִאשׁוֹן, וְעַל אֵלֶּה כָּתוּב אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וְגוֹ'. כָּל אוֹתָם שֶׁלֹּא זָכוּ לְהִתַּקֵּן.</p>\n<p>וְאֵלּוּ הֵן הַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, וּכְלוּם לֹא נֶאֱבָד. אֲפִלּוּ הֶבֶל הַפֶּה יֵשׁ לוֹ אֲתַר וּמָקוֹם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מִמֶּנּוּ מַה שֶּׁעוֹשֶׂה, וַאֲפִלּוּ דִבּוּר שֶׁל אָדָם וַאֲפִלּוּ קוֹל אֵינוֹ בְרֵיקָנוּת, וַאֲתַר וּמָקוֹם יֵשׁ לְכֻלָּם.</p>\n<p>זְהִ שֶׁנִּבְנֶה עַכְשָׁו וְיָצָא לָעוֹלָם בְּרִיָּה חֲדָשָׁה, אֵין לוֹ בַּת זוּג, וְעַל זֶה לֹא מַכְרִיזִים, שֶׁהֲרֵי בַּת זוּגוֹ אָבְדָה מִמֶּנּוּ. בַּת הַזּוּג שֶׁהָיְתָה לוֹ נֵעֶשְׂתָה אִמּוֹ, וְאָחִיו לְאָבִיו.</p>\n<p>זָקֵןֹ זָקֵן, מֶה עָשִׂיתָ? טוֹבָה הָיְתָה לְךְ הַשְּׁתִיקָה. זָקֵן זָקֵן, הֲרֵי אָמַרְנוּ שֶׁנִּכְנַסְתָּ לַיָּם הַגָּדוֹל בְּלִי חֲבָלִים וּבְלִי דֶגֶל, מַה תַּעֲשֶׂה? אִם תֹּאמַר שֶׁתַּעֲלֶה לְמַעְלָה - לֹא תוּכַל. וְאִם תֹּאמַר שֶׁתֵּרֵד לְמַטָּה - הֲרֵי עָמְקוֹ שֶׁל הַתְּהוֹם גָּדוֹל. מַה תַּעֲשֶׂה? אִי זָקֵן, אִי זָקֵן, אֵין לְךְ לַחֲזֹר לְאָחוֹר. בַּזְּמַנִּים הַלָּלוּ לֹא הָיִיתָ, וְלֹא הִתְרַגַּלְתָּ לְהֵחָלֵשׁ בְּכֹחֲךְ, שֶׁהֲרֵי יָדַעְתָּ שֶׁאָדָם אַחֵר בְּכָל הַדּוֹר הַזֶּה לֹא נִכְנָס לָאֳנִיָּה בָּעֹמֶק הַזֶּה שֶׁאַתָּה שָׁם.</p>\n<p>בֶּן יוֹחַאי יוֹדֵעַ לִשְׁמֹר אֶת דַּרְכּוֹ, וְאִם הוּא נִכְנָס לַיָּם הֶעָמֹק, הוּא מַשְׁגִּיחַ בַּהַתְחָלָה אֵיךְ יַעֲבֹר בְּפַעַם אַחַת וְיָשׁוּט בַּיָּם טֶרֶם שֶׁיִּכָּנֵס. וְאַתָּה, זָקֵן, לֹא הִשְׁגַּחְתָּ בַּתְּחִלָּה. עַכְשָׁו, זָקֵן, הוֹאִיל וְאַתָּה שָׁם, אַל תֶּחֱלַשׁ בְּכֹחֲךְ, אַל תַּעֲזב אֶת כָּל דַּרְכְּךְ, לָשׁוּט לְיָמִין וְלִשְׂמֹאל, לָאֹרֶךְ וְלָרֹחַב, לָעֹמֶק וְלַגֹּבַהּ. אַל תִּפְחַד. זָקֵן זָקֵן, הִתְחַזֵּק בְּכֹחֲךְ. כַּמָּה גְבָרִים חֲזָקִים שָׁבַרְתָּ בְּכֹחָם וְכַמָּה קְרָבוֹת נָצַחְתָּ.</p>\n<p>בָּכָה, פָּתַח וְאָמַר, (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ. פָּסוּק זֶה פֵּרְשׁוּהוּ, וְכָךְ הוּא. אֲבָל צְאֶינָה וּרְאֶינָה, וְכִי מִי יָכוֹל לִרְאוֹת בַּמֶּלֶךְ שְׁלֹמֹה, שֶׁהוּא הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ? וַהֲרֵי הוּא נִסְתָּר מִכָּל חֵילוֹת הַמְּרוֹמִים שֶׁלְּמַעְלָה בְּאוֹתוֹ מָקוֹם, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ, וְאַתָּה אָמַרְתָּ צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה? וְעוֹד, שֶׁהֲרֵי כְּבוֹדוֹ, כָּל הַמַּלְאָכִים הָעֶלְיוֹנִים שׁוֹאֲלִים וְאוֹמְרִים אַיֵּה מְקוֹם כְּבוֹדוֹ?</p>\n<p>אֶלָּא, מַה שֶּׁאָמַר צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה, בָּעֲטָרָה כָּתוּב, וְלֹא כָתוּב וּבָעֲטָרָה. שֶׁכָּל מִי שֶׁרוֹאֶה אוֹתָהּ עֲטָרָה, רוֹאֶה אֶת הַנֹּעַם שֶׁל הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. שֶׁעִטְּרָה לּוֹ אִמּוֹ, הֲרֵי שָׁנִינוּ, קוֹרֵא לָהּ בַּת וְקוֹרֵא לָהּ אָחוֹת, קוֹרֵא לָהּ אֵם, וְהַכֹּל הוּא, וְהַכֹּל הָיָה. מִי שֶׁיִּסְתַּכֵּל וְיֵדַע אֶת זֶה, יֵדַע חָכְמָה נִכְבָּדָה.</p>\n<p>עַכְשָׁו מָה אֶעֱשֶׂה? אִם אֹמַר סוֹד נִסְתָּר זֶה - לֹא צָרִיךְ לְגַלּוֹת. אִם לֹא אֹמַר - יִשָּׁאֲרוּ הַצַּדִּיקִים הַלָּלוּ יְתוֹמִים מִן הַסּוֹד הַזֶּה. נָפַל אוֹתוֹ הַזָּקֵן עַל פָּנָיו וְאָמַר, (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת. כְּלִי שֶׁהָיָה לְמַטָּה, אֵיךְ יֵעָשֶׂה לְמַעְלָה? בַּעְלָהּ שֶׁהָיָה לְמַעְלָה, אֵיךְ יִתְהַפֵּךְ וְיִהְיֶה לְמַטָּה? בַּת זוּגוֹ נֶעֶשְׂתָה אִמּוֹ? תְּמִיהָה עַל תְּמִיהָה. אָחִיו הוֹפֵךְ לְאָבִיו? אִם אָבִיו שֶׁבָּרִאשׁוֹנָה יִגְאַל אוֹתוֹ - יָפֶה, אֲבָל אָחִיו שֶׁיִּהְיֶה אָבִיו? וְכִי זוֹ לֹא תְמִיהָה?! עוֹלָם הָפוּךְ הוּא! וַדַּאי שֶׁעֶלְיוֹנִים לְמַטָּה וְתַחְתּוֹנִים לְמַעְלָה.</p>\n<p>אֶלָּא, (דניאל ב) יִהְיֶה שֵׁם הָאֱלוֹהַּ מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם, שֶׁהַחָכְמָה וְהַגְּבוּרָה שֶׁלּוֹ הִיא, וְהוּא מְשַׁנֶּה עִדָּנִים וּזְמַנִּים וְגוֹ'. יוֹדֵעַ מַה בַּחֲשֵׁכָה, וְהָאוֹר עִמּוֹ שָׁרוּי. בֹּא וּרְאֵה, מִי שֶׁשָּׁרוּי בְּאוֹר לֹא יוּכַל לְהִסְתַּכֵּל וְלִרְאוֹת מַה שֶּׁבַּחֲשֵׁכָה. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ, יוֹדֵעַ מַה בַּחֲשֵׁכָה אַף עַל גַּב שֶׁהָאוֹר שָׁרוּי עִמּוֹ. מִתּוֹךְ הָאוֹר מִסְתַּכֵּל בַּחֹשֶׁךְ וְיוֹדֵעַ כָּל מַה שֶּׁשָּׁם.</p>\n<p>עֵכְשָׁו יֵשׁ לְהַקְדִּים בָּרִאשׁוֹנָה דָּבָר אֶחָד שֶׁאָמְרוּ הַקַּדְמוֹנִים בְּאוֹתָם מַרְאוֹת הַלַּיְלָה. שֶׁשָּׁנִינוּ, מִי שֶׁבָּא עַל אִמּוֹ בַּחֲלוֹם, יִצְפֶּה לְבִינָה, שֶׁכָּתוּב (משלי ב) כִּי אִם לַבִּינָה תִקְרָא. כָּאן יֵשׁ לְהִתְבּוֹנֵן, אִם מִשּׁוּם שֶׁהִיא אֵם - יָפֶה, וְהָיָה לוֹ לִכְתֹּב כָּךְ: שֶׁמִּי שֶׁרוֹאֶה אִמּוֹ בַּחֲלוֹם, יִזְכֶּה לְבִינָה. אֲבָל מִי שֶׁבָּא עַל אִמּוֹ לָמָּה?</p>\n<p>אֶלָּא סוֹד עֶלְיוֹן הוּא, מִשּׁוּם שֶׁהִתְהַפֵּךְ וְעָלָה מִלְּמַטָּה לְמַעְלָה. בֵּן הָיָה בַּתְּחִלָּה, כֵּיוָן שֶׁעָלָה לְמַעְלָה, מִתְהַפֵּךְ הָאִילָן, וְנַעֲשֶׂה הוּא מֵעוֹלָם עֶלְיוֹן, וְשׁוֹלֵט עָלֶיהָ וְזוֹכֶה לְבִינָה.</p>\n<p>בַּתְּחִלָּה כְּשֶׁעוֹלֶה אָדָם לִשְׁלֹשׁ עֶשְׂרֵה שָׁנָה, מַה כָּתוּב? (תהלים ב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. אָז הוּא לְמַטָּה מִמֶּנָּה. כֵּיוָן שֶׁעָלָה אֵלֶיהָ, הֲרֵי הוּא מִן הָעוֹלָם הָעֶלְיוֹן, שֶׁהֲרֵי הִתְעַלָּה לְדַרְגַּת יוֹסֵף, וְזֶה (ודאי) זוֹכֶה לְבִינָה.</p>\n<p>אַף כָּךְ הַכְּלִי הַזֶּה בַּתְּחִלָּה הוּא הָיָה בְּדַרְגַּת יוֹסֵף, בַּעַל הָאִילָן הַתַּחְתּוֹן, עוֹמֵד בִּרְצוֹנוֹ וְשׁוֹלֵט עָלָיו, שֶׁהֲרֵי כָּל נְקֵבָה בִּדְמוּת הַנְּקֵבָה הָעֵץ הַתַּחְתּוֹן עוֹמֶדֶת. כֵּיוָן שֶׁהוּא לֹא רָצָה לַעֲמֹד בְּאוֹתָהּ דַּרְגָּה שֶׁל יוֹסֵף וְלֹא הִתְקַיֵּם לְשַׁמֵּשׁ בָּהּ וּלְהִתְרַבּוֹת בָּעוֹלָם וְלַעֲשׂוֹת תּוֹלָדוֹת, אָז יוֹרֵד לְמַטָּה, וְהִיא נַעֲשֵׂית אִמּוֹ. וְאוֹתוֹ הַגּוֹאֵל יוֹרֵשׁ אֶת יְרֻשַּׁת יוֹסֵף, שֶׁהָיָה הוּא בָרִאשׁוֹנָה וְהוּא יָרַד לְמַטָּה.</p>\n<p>כֵּיוָן שֶׁיָּרַד לְמַטָּה, אָז הִתְקַיֵּם בּוֹ, ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. הִתְהַפֵּךְ הָאִילָן. מַה שֶּׁהָיָה תַחְתָּיו וְהוּא שָׁלַט עָלָיו, חָזַר וְשָׁלַט הָאִילָן הַהוּא עָלָיו, וְהוּא יָרַד לְמַטָּה. כֵּיוָן שֶׁהוּא יָרַד לְמַטָּה, אוֹתוֹ שֶׁיָּרַשׁ יְרֻשַּׁת מְקוֹם יוֹסֵף, אָבִיו נִקְרָא, אָבִיו יִהְיֶה וַדַּאי, וְהַכֹּל בָּא עַל תִּקּוּנוֹ וַדַּאי כָּרָאוּי.</p>\n<p>בַּתְּחִלָּה הָיָה מֵעוֹלַם הַזָּכָר, וַהֲרֵי נֶעֱקַר מִשָּׁם, וְעַכְשָׁו הוּא מֵעוֹלַם הַנְּקֵבָה. וּמַה שֶּׁהוּא הָיָה שׁוֹלֵט עָלֶיהָ - הִיא שׁוֹלֶטֶת עָלָיו, וְחוֹזֵר לִהְיוֹת בְּעוֹלַם הַנְּקֵבָה, וְעַל זֶה אֵין לוֹ בִּכְלָל בַּת זוּג, וְלֹא מַכְרִיזִים עָלָיו עַל הַנְּקֵבָה, שֶׁהֲרֵי הוּא חָזַר לִהְיוֹת מֵעוֹלַם הַנְּקֵבָה.</p>\n<p>וְאוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, אִלְמָלֵא יֵדְעוּ וְיִסְתַּכְּלוּ בְּנֵי הָעוֹלָם אֶת הַצַּעַר שֶׁיֵּשׁ לוֹ כְּשֶׁיֵּעָקֵר מִן עוֹלַם הַזָּכָר וְחוֹזֵר לְעוֹלַם הַנְּקֵבָה, יֵדְעוּ שֶׁהֲרֵי אֵין צַעַר בָּעוֹלָם כְּאוֹתוֹ הַצַּעַר. בַּת זוּג אֵין לוֹ, שֶׁהֲרֵי אֵינוֹ עוֹמֵד בְּמָקוֹם שֶׁל זָכָר. לֹא מַכְרִיזִים עָלָיו עַל הַנְּקֵבָה, שֶׁהֲרֵי הוּא מֵעוֹלַם הַנְּקֵבָה. וְאִם יֵשׁ לוֹ בַּת זוּג, זֶה בְּרַחֲמִים נִפְגָּשׁ עִם (באחת) נְקֵבָה, שֶׁעַד עַכְשָׁו אֵין לָהּ בֶּן זוּג. וְעַל זֶה שָׁנִינוּ, שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים, אַחֵר שֶׁשָּׁנִינוּ. וְהַכֹּל הוּא עַל תִּקּוּנוֹ.</p>\n<p>וְעַל זֶה כָּתוּב, (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ. וּבַת כֹּהֵן - הֲרֵי בֵּאַרְנוּ דָבָר זֶה. אַלְמָנָה - מֵאוֹתוֹ הַגּוּף הָרִאשׁוֹן. וּגְרוּשָׁה - שֶׁלֹּא נִכְנְסָה לְפַרְגּוֹד הַמֶּלֶךְ. שֶׁכָּל אוֹתָם שֶׁלֹּא עוֹמְדִים בְּעוֹלַם הַזָּכָר, אֵין לָהֶם בּוֹ חֵלֶק. הוּא הִשְׁתַּמֵּט וְעָקַר עַצְמוֹ מֵעוֹלַם הַזָּכָר, אָז אֵין לוֹ חֵלֶק בּוֹ, וְעַל כָּךְ הִיא גְרוּשָׁה. וְזֶרַע אֵין לָהּ - שֶׁאִם הָיָה לָהּ זֶרַע, לֹא נֶעֱקַר מִמֶּנּוּ וְלֹא הָיָה יוֹרֵד לְעוֹלַם הַנְּקֵבָה.</p>\n<p>וְשָׁבָה אֶל בֵּית אָבִיהָ, מַה זֶּה בֵּית אָבִיהָ? זֶה עוֹלַם הַנְּקֵבָה, שֶׁאוֹתוֹ הָעוֹלָם נִקְרָא בֵּית אָבִיהָ, וְאוֹתוֹ כְּלִי שֶׁהָיָה מֻתְקָן לְהִשְׁתַּמֵּשׁ בּוֹ, הִתְהַפֵּךְ וְהוּא יוֹרֵד לְמַטָּה, וְאוֹתוֹ כְּלִי עוֹלֶה לְמַעְלָה. כִּנְעוּרֶיהָ - כְּמוֹ אוֹתוֹ זְמַן שֶׁכָּתוּב אֲנִי הַיּוֹם יְלִדְתִּיךְ. יְלִדְתִּיךְ וַדַּאי, יָשׁוּב לִימֵי עֲלוּמָיו, כְּמוֹ שֶׁהָיָה (בתחלה) מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה.</p>\n<p>אִם זָכְתָה לְהִתַּקֵּן - הוֹאִיל וְשָׁבָה אֶל בֵּית אָבִיהָ, מִלֶּחֶם אָבִיהָ תֹּאכֵל, תִּתְעַנֵּג מֵאוֹתוֹ הָעֹנֶג שֶׁל עוֹלַם הַנְּקֵבָה שֶׁאוֹכְלִים מִלֶּחֶם אַבִּירִים שֶׁיּוֹרֵד מִלְמַעְלָה. אֲבָל לְהִסְתַּכֵּל וְלֵהָנוֹת בְּמַה שֶּׁנֶּהֱנִים שְׁאָר הַצַּדִּיקִים לֹא יָכוֹל, מִשּׁוּם שֶׁהָיָה זָר לְשָׁם. וְעַל זֶה הוּא לֹא אוֹכֵל קֹדֶשׁ, אֲבָל אוֹכֵל תְּרוּמָה, כִּי הוּא יוֹשֵׁב בְּעוֹלַם הַנְּקֵבָה.</p>\n<p>וּמִתּוֹךָ שֶׁהוּא מֵעוֹלַם הַנְּקֵבָה, לֹא אוֹכֵל אוֹתוֹ אֶלָּא בַּלַּיְלָה, שֶׁכָּתוּב (ויקרא כב) וּבָא הַשֶּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקְּדָשִׁים כִּי לַחְמוֹ הוּא. שֶׁהֲרֵי קֹדֶשׁ שֶׁהוּא מֵעוֹלַם הַזָּכָר לֹא נֶאֱכָל אֶלָּא בַּיּוֹם. מִשּׁוּם כָּךְ (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, רֵאשִׁית עֶלְיוֹנָה שֶׁל כָּל עוֹלַם הַזָּכָר הִיא קֹדֶשׁ, וּמַה שֶּׁעוֹלֶה בּוֹ, בַּקֹּדֶשׁ הָיָה יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה.</p>\n<p>כְּשֶׁרוּחוֹת פּוֹקְדוֹת, בְּאוֹתָם זְמַנִּים שֶׁפּוֹקְדִים אֶת בֵּית הַקְּבָרוֹת, אוֹתָם לֹא פוֹקְדִים, שֶׁהֲרֵי לֹא זוֹכוֹת לְעוֹלַם הַקֹּדֶשׁ, שֶׁכָּתוּב (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. וְאִם אוֹתָהּ רוּחַ לֹא זָכְתָה לְהִתַּקֵּן כָּרָאוּי, כֵּיוָן שֶׁחָזַר בְּגִלְגּוּל אֲפִלּוּ בְּאוֹתוֹ מָקוֹם, לֹא אוֹכֵל בִּתְרוּמָה, וְנִקְרָא זָר אֲפִלּוּ לָעוֹלָם הַתַּחְתּוֹן וְלֹא אוֹכֵל בָּהּ. עַד כָּאן בְּסוֹד זֶה.</p>\n<p>זָקֵן זָקֵן, כֵּיוָן שֶׁהִתְחַלְתָּ לָשׁוּט בַּיָּם הַגָּדוֹל, לֵךְ בִּרְצוֹנְךְ לְכָל צִדְדֵי הַיָּם. עַכְשָׁו יֵשׁ לְגַלּוֹת, שֶׁהֲרֵי אָמַרְנוּ, שֶׁכְּשֶׁבָּא הַגּוֹאֵל הַזֶּה וְנִכְנָס אֶל אוֹתוֹ הַכְּלִי שֶׁאָמַרְנוּ, מַכְנִיס לְשָׁם וּמַדְבִּיק שָׁם אֶת הָרוּחַ (של העולם) שֶׁלּוֹ בְּאוֹתוֹ כְּלִי וּכְלוּם לֹא נֶאֱבָד, אֲפִלּוּ הֶבֶל הַפֶּה - יָפֶה הוּא וְכָךְ הוּא. זָקֵן זָקֵן, אִם תֹּאמַר וּתְגַלֶּה, אֱמֹר בְּלִי פַחַד.</p>\n<p>שְׁאָר בְּנֵי הָאָדָם שֶׁל הָעוֹלָם שֶׁעוֹלִים מִמֶּנּוּ, וַהֲרֵי יָדַעְנוּ שֶׁרוּחוֹ הִשְׁאִיר בְּאוֹתָהּ אִשָּׁה שֶׁהָיְתָה לוֹ, וְהִכְנִיס לְשָׁם רוּחַ, מַה נַּעֲשֶׂה מֵאוֹתָהּ הָרוּחַ? וְאִם נִשֵּׂאת הָאִשָּׁה הַזּוֹ, אַף כָּךְ - מַה נַּעֲשֶׂה מֵאוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ הָרִאשׁוֹן, שֶׁהֲרֵי אִישׁ אַחֵר בָּא עָלֶיהָ?</p>\n<p>לְהִתְקַיִּםִ רוּחַ עִם רוּחַ אִי אֶפְשָׁר, שֶׁהֲרֵי זֶה שֶׁעַכְשָׁו בָּא עָלֶיהָ, הִכְנִיס בָּהּ רוּחַ, וְכֵן אוֹתוֹ הָרִאשׁוֹן שֶׁהִסְתַּלֵּק הִכְנִיס בָּהּ רוּחַ. אוֹתוֹ רִאשׁוֹן שֶׁהִסְתַּלֵּק הָיוּ לוֹ בָּנִים, וְזֶה שֶׁל עַכְשָׁו אֵינוֹ גוֹאֵל רוּחַ שֶׁהִשְׁאִיר אוֹתוֹ רִאשׁוֹן בְּאוֹתוֹ כְּלִי, וּבָא הָאַחֵר הַזֶּה וְהִכְנִיס בָּהּ רוּחַ, וַדַּאי שֶׁלֹּא יוּכְלוּ שְׁנֵיהֶם לְהִתְקַיֵּם בְּאוֹתוֹ גוּף הָאִשָּׁה כְּאֶחָד. וְאִם נֹאמַר שֶׁנֶּאֱבַד - אִי אֶפְשָׁר. מַה נַּעֲשָׂה מִמֶּנּוּ?</p>\n<p>אַף כָּךְ אִם הִיא לֹא נִשְׂאָה, אוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ מַה נַּעֲשֶׂה מִמֶּנָּה? אִם נֹאמַר שֶׁתֹּאבַד - לֹא כָּךְ. כָּל זֶה צָרִיךְ עַכְשָׁו לְגַלּוֹת. זָקֵן זָקֵן, רְאֵה מֶה עָשִׂיתָ וּבַמָּה הִכְנַסְתָּ אֶת עַצְמְךְ. קוּם זָקֵן הָרֵם דִּגְלְךְ! קוּם זָקֵן וְהַשְׁפֵּל עַצְמְךְ לִפְנֵי רִבּוֹנְךְ!</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (תהלים קלא) ה' לֹא גָבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה מִשּׁוּם שֶׁהָיָה מֶלֶךְ עֶלְיוֹן וְשׁוֹלֵט עַל כָּל הַמְּלָכִים הָעֶלְיוֹנִים וְהַשַּׁלִּיטִים שֶׁיֵּשׁ מִמִּזְרָח וְעַד מַעֲרָב, וְלֹא עָלָה עַל לִבּוֹ לִסְטוֹת מִן הַדֶּרֶךְ, וְתָמִיד שָׁפַל לִבּוֹ לִפְנֵי רִבּוֹנוֹ, וּכְשֶׁהָיָה עוֹסֵק בַּתּוֹרָה, הָיָה מִתְגַּבֵּר כָּאַרְיֵה, וְעֵינָיו תָּמִיד מֻנְמָכוֹת לָאָרֶץ מִפַּחַד רִבּוֹנוֹ, וּכְשֶׁהָיָה הוֹלֵךְ בֵּין הָעָם, לֹא הָיְתָה בּוֹ גַּסּוּת הָרוּחַ כְּלָל.</p>\n<p>וְעַל זֶה כָּתוּב (תהלים קלא) ה' לֹא גָבַהּ לִבִּי וְגוֹ'. לֹא גָבַהּ לִבִּי, אַף עַל גַּב שֶׁאֲנִי מֶלֶךְ שַׁלִּיט עַל כָּל שְׁאָר מַלְכֵי הָעוֹלָם. וְלֹא רָמוּ עֵינַי, בִּזְמַן שֶׁאֲנִי עוֹמֵד לְפָנֶיךְ וְעוֹסֵק בַּתּוֹרָה. וְלֹא הִלַּכְתִּי בִּגְדֹלוֹת וּבְנִפְלָאוֹת מִמֶּנִּי, בְּשָׁעָה שֶׁאֲנִי הוֹלֵךְ בֵּין הָעָם. וְאִם דָּוִד הַמֶּלֶךְ אָמַר כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. וַאֲנִי כַּמָּה אֲנִי שְׁפַל לֵב עִם עַיִן נְמוּכָה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וַחֲבָל לִי שֶׁבִּדְבָרִים קְדוֹשִׁים שֶׁל הַתּוֹרָה יָרוּם לִבִּי. בָּכָה וְדִמְעוֹתָיו נוֹפְלוֹת עַל זְקָנוֹ.</p>\n<p>אָמַר, זָקֵן עָיֵף בְּכֹחַ, כַּמָּה יָפוֹת הַדְּמָעוֹת עַל זְקָנְךְ, כְּמוֹ שֶׁהָיָה יָפֶה הַשֶּׁמֶן הַטּוֹב כְּשֶׁהָיָה יוֹרֵד עַל הַזָּקָן שֶׁל הַזָּקֵן הַטּוֹב אַהֲרֹן. אֱמֹר דְּבָרְךְ, זָקֵן, שֶׁהֲרֵי הַמֶּלֶךְ הַקָּדוֹשׁ כָּאן. שְׁאָר בְּנֵי אָדָם שֶׁל הָעוֹלָם שֶׁהִסְתַּלְּקוּ מִמֶּנּוּ, וְהִשְׁאִירוּ רוּחַ בְּאוֹתוֹ כְּלִי שֶׁהָיוּ מִשְׁתַּמְּשִׁים בּוֹ, וְנִשְּׂאָה, וּבָא אַחֵר וְהִכְנִיס לְאוֹתוֹ כְּלִי רוּחַ אַחֶרֶת, מַה נַּעֲשֶׂה מֵאוֹתוֹ רִאשׁוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר?</p>\n<p>בֹּא וּרְאֵה, כַּמָּה עֶלְיוֹנִים גְּבוּרוֹת הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁהוּא עוֹשֶׂה, וּמִי יָכוֹל לְהַגִּיד אוֹתָם. כְּשֶׁהַבַּעַל הַשֵּׁנִי הַזֶּה בָּא וּמַכְנִיס רוּחַ לְאוֹתוֹ כְּלִי, הָרוּחַ הָרִאשׁוֹנָה מְקַטְרֶגֶת בָּרוּחַ הזּוֹ שֶׁנִּכְנְסָה (נלחמת), וְלֹא מִתְיַשְּׁבוֹת כְּאֶחָד.</p>\n<p>וּמִשּׁוּם כָּךְ הָאִשָּׁה לֹא מְיֻשֶּׁבֶת כָּרָאוּי עִם בַּעְלָהּ הַשֵּׁנִי, מִשּׁוּם שֶׁהָרוּחַ הָרִאשׁוֹנָה מְכַשְׁכֶּשֶׁת בָּהּ, וְאָז הִיא זוֹכֶרֶת אוֹתוֹ תָּמִיד וּבוֹכָה עָלָיו אוֹ נֶאֱנַחַת עָלָיו, שֶׁהֲרֵי רוּחוֹ מְכַשְׁכֶּשֶׁת בְּמֵעֶיהָ כְּנָחָשׁ, וּמְקַטְרֶגֶת עִם הָרוּחַ הָאַחֶרֶת שֶׁנִּכְנְסָה בָּהּ מֵהַבַּעַל הַשֵּׁנִי. עַד זְמַן רַב מְקַטְרְגִים זֶה בָּזֶה.</p>\n<p>וְאִם מַעֲבִירָה זוֹ שֶׁנִּכְנְסָה לְאוֹתָהּ (התעוררות) שֶׁהָיְתָה רִאשׁוֹנָה (לאחר כך) - זוֹ הָרִאשׁוֹנָה יוֹצֵאת וְהוֹלֶכֶת לָהּ. וְלִפְעָמִים שֶׁדּוֹחָה הָרִאשׁוֹנָה הַזּוֹ אֶת אוֹתָהּ הַשְּׁנִיָּה וְנַעֲשֵׂית לָהּ מְקַטְרֵג, עַד שֶׁמּוֹצִיאָה אוֹתָהּ מִן הָעוֹלָם. וְעַל זֶה שָׁנִינוּ, שֶׁמִּשְּׁנַיִם וָמַעְלָה לֹא יִשָּׂא אָדָם אֶת הָאִשָּׁה הַזּוֹ, שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת הִתְחַזֵּק בָּהּ, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים שֶׁהֲרֵי הָרוּחַ, כֵּיוָן שֶׁנִתְחַזֵּק וְנִצַּח אֶת אוֹתָהּ הָרוּחַ הָאַחֶרֶת הַשְּׁנִיָּה, מִכָּאן וָהָלְאָה לֹא יִתְעָרֵב אִישׁ אַחֵר עִמָּהּ.</p>\n<p>חֲבֵרִים, הֲרֵי יָדַעְנוּ שֶׁבְּמָקוֹם זֶה יֵשׁ לָכֶם לְהַקְשׁוֹת וְלוֹמַר, אִם כָּךְ, הַשֵּׁנִי הַזֶּה לֹא מֵת בַּדִּין וְלֹא דָנוּ אוֹתוֹ מִלְמַעְלָה. בֹּא וּרְאֵה, הַכֹּל הוּא בְּדִין שֶׁיְּנַצַּח פְּלוֹנִי אֶת פְּלוֹנִי אוֹ שֶׁלֹּא יְקַטְרֵג עָלָיו פְּלוֹנִי לִפְלוֹנִי, וּמִי שֶׁנּוֹשֵׂא אַלְמָנָה כְּמוֹ שֶׁנִּכְנָס לַיָּם בְּרוּחוֹת עַזּוֹת בְּלִי חֲבָלִים, וְלֹא יוֹדֵעַ אִם יַעֲבֹר בְּשָׁלוֹם אוֹ יִטְבַּע לְתוֹךְ הַתְּהוֹמוֹת.</p>\n<p>וְאִם זֶה שֶׁהִכְנִיס אוֹתָהּ רוּחַ שְׁנִיָּה הִתְחַזֵּק וְנִצַּח אֶת אוֹתוֹ הָרִאשׁוֹן - אוֹתוֹ הָרִאשׁוֹן יוֹצֵא מִשָּׁם וְהוֹלֵךְ לוֹ. לְאֵיזֶה מָקוֹם הוֹלֵךְ לוֹ וּמַה נַּעֲשֶׂה אִתּוֹ? זָקֵן זָקֵן, מֶה עָשִׂיתָ? חָשַׁבְתָּ שֶׁתְּדַבֵּר מְעַט וְיָצָאתָ לָזֶה? הֲרֵי נִכְנַסְתָּ לְמָקוֹם שֶׁלֹּא נִכְנַס לְשָׁם אִישׁ אַחֵר, וּמִיּוֹם שֶׁדּוֹאֵג וַאֲחִיתֹפֶל עָשׂוּ קֻשְׁיוֹת אֵלּוּ, בְּאוֹתָם אַרְבַּע מֵאוֹת קֻשְׁיוֹת, שֶׁהָיוּ מַקְשִׁים עַל מִגְדָּל הַפּוֹרֵחַ בָּאֲוִיר וְלֹא הֵשִׁיב עֲלֵיהֶן אִישׁ, עַד שֶׁבָּא שְׁלֹמֹה הַמֶּלֶךְ וּבֵרַר אוֹתָם כָּל אֶחָד וְאֶחָד עַל תִּקּוּנוֹ. זָקֵן זָקֵן, הַסּוֹד הָעֶלְיוֹן שֶׁהָיָה טָמִיר בָּאתָ לְגַלּוֹת, מֶה עָשִׂיתָ?</p>\n<p>זָקֵן זָקֵן, בַּתְּחִלָּה הָיָה לְךְ לִשְׁמֹר דַּרְכְּךְ, וְתִסְתַּכֵּל בְּרֹאשְׁךְ. אֲבָל עַכְשָׁו אֵינָהּ שָׁעָה לְהִתְחַבֵּא. זָקֵן, חֲזֹר בְּכֹחֲךְ. אוֹתָהּ רוּחַ שֶׁיָּצְאָה, לְאָן הוֹלֶכֶת? בָּכָה וְאָמַר, חֲבֵרִים, כָּל הַבְּכִיּוֹת הַלָּלוּ שֶׁאֲנִי בּוֹכֶה אֵינָם בִּגְלַלְכֶם, אֶלָּא פּוֹחֵד אֲנִי לְרִבּוֹן הָעוֹלָם שֶׁאֲנִי מְגַלֶּה דְרָכִים נִסְתָּרוֹת בְּלִי רְשׁוּת. אֲבָל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לִכְבוֹדִי עָשִׂיתִי וְלֹא לִכְבוֹד אָבִי, אֲבָל רְצוֹנִי הוּא לַעֲבוֹדָתוֹ, וַאֲנִי רוֹאֶה הַכָּבוֹד שֶׁל אֶחָד מִכֶּם בְּאוֹתוֹ עוֹלָם, וְאַחֵר יָדַעְתִּי שֶׁכָּךְ הוּא, אֲבָל לֹא גָלוּי לְפָנַי, וְעַכְשָׁו רָאִיתִי.</p>\n<p>שָׁנִינוּ, דּוֹחִים אִישׁ מִפְּנֵי אִישׁ, בְּכַמָּה דְרָכִים נִסְתָּרוֹת נִדְחִים. אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁנִּדְחֲתָה מִלִּפְנֵי אוֹתָהּ הַשְּׁנִיָּה, לְאָן הוֹלֶכֶת? אוֹתָהּ רוּחַ יוֹצֵאת וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם, וְלֹא יָדוּעַ, וְהוֹלֶכֶת לְקִבְרוֹ שֶׁל אוֹתוֹ הָאִישׁ, וּמִשָּׁם מְשׁוֹטֶטֶת בָּעוֹלָם וְנִרְאֵית בַּחֲלוֹם לִבְנֵי אָדָם, וְרוֹאִים בַּחֲלוֹם אֶת דְּמוּת אוֹתוֹ הָאִישׁ, וּמוֹדִיעַ לָהֶם דְּבָרִים לְפִי דַרְכָּהּ שֶׁל אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁנִּמְשְׁכָה מִמֶּנּוּ, כְּמוֹ שֶׁהוּא בְּאוֹתוֹ עוֹלָם, כָּךְ מְשׁוֹטֶטֶת זוֹ וּמוֹדִיעָה בָּעוֹלָם הַזֶּה.</p>\n<p>וְכָךְ הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם, וּפוֹקֶדֶת תָּמִיד אֶת אוֹתוֹ הַקֶּבֶר עַד הַזְּמַן שֶׁהָרוּחוֹת פּוֹקְדוֹת לְקִבְרוֹת הַגּוּפִים. אָז הָרוּחַ הַזּוֹ מִתְחַבֶּרֶת בְּאוֹתָהּ רוּחַ שֶׁלּוֹ, וּמִתְלַבֶּשֶׁת בָּהּ, וְהוֹלֵךְ לוֹ. כְּשֶׁנִּכְנָס לִמְקוֹמוֹ, מִתְפַּשֵּׁט מִמֶּנּוּ, וְיֵשׁ לוֹ מָקוֹם (באותן רוחותבגן עדן) בְּאוֹתָם הֵיכָלוֹת שֶׁל גַּן עֵדֶן אוֹ בַּחוּץ לְפִי דַרְכֵי כָּל אֶחָד וְאֶחָד, וְשָׁם נִשְׁמָר.</p>\n<p>וּכְשֶׁהָרוּחוֹת פּוֹקְדוֹת אֶת הָעוֹלָם הַזֶּה, שֶׁהַמֵּתִים נִזְקָקִים אֶל הַחַיִּים, הֵם לֹא נִזְקָקִים אֶלָּא רַק בְּאוֹתָהּ מְשִׁיכַת הָרוּחַ, וּבָהּ מִתְלַבֶּשֶׁת רוּחַ אַחֶרֶת. וְאִם תֹּאמַר, אִם כָּךְ, אָז זוֹ תּוֹעֶלֶת לָרוּחַ, וְהָאִשָּׁה הַזּוֹ עוֹשָׂה תוֹעֶלֶת לַכֹּל - לֹא כָּךְ, שֶׁאִלְמָלֵא לֹא נִשְׂאָה לְאַחֵר וְאוֹתָהּ רוּחַ רִאשׁוֹנָה לֹא הָיְתָה נִדְחֵית מִלִּפְנֵי הָאִישׁ הָאַחֵר הַזֶּה, תּוֹעֶלֶת אַחֶרֶת הָיְתָה לוֹ בְּגָוֶן אַחֵר, וְלֹא יִהְיֶה יָגֵעַ בָּעוֹלָם כְּמוֹ שֶׁהוּא, וְלֹא יִזְדַּקֵּק לַחַיִּים שֶׁל הָעוֹלָם הַזֶּה כְּמוֹ שֶׁהָיָה מְשׁוֹטֵט כָּאן וְכָאן.</p>\n<p>אִם כָּךְ, הַזִּוּוּג הַשֵּׁנִי שֶׁל הָאִשָּׁה הַזּוֹ לֹא הָיָה מִלְמַעְלָה, וְאַתָּה אוֹמֵר שֶׁנִּדְחֶה אִישׁ מִפְּנֵי אִישׁ? וְאָמַרְנוּ שֶׁהַבַּעַל הַשֵּׁנִי שֶׁנָּשָׂא אֶת הָאִשָּׁה הַזּוֹ הִיא בַּת זוּגוֹ מַמָּשׁ, וְאוֹתוֹ הָרִאשׁוֹן לֹא הָיָה מַמָּשׁ בֶּן זוּגָהּ, וְהַשֵּׁנִי הָיָה שֶׁלָּהּ, וּכְשֶׁהִגִּיעַ זְמַנּוֹ נִדְחֶה זֶה מִפָּנָיו - וַדַּאי זֶה כָּךְ, שֶׁהֲרֵי לֹא נִדְחֵית אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁהָיְתָה בָּאִשָּׁה הַזּוֹ אֶלָּא בִּשְׁבִיל הַשֵּׁנִי הַזֶּה, שֶׁהוּא בֶּן זוּגָהּ. (שהבן היא בת זוגו) (זה השני).</p>\n<p>וְכָל אוֹתָם הַשְּׁנִיִּים שֶׁנִּדְחִים מִלִּפְנֵי הָרִאשׁוֹנִים - הָרִאשׁוֹנִים הָיוּ בְּנֵי זוּגָם וְלֹא אֵלֶּה, וְלָכֵן אֵין לָהֶם קִיּוּם עִמָּם, וְנִדְחֵית הָרוּחַ הַשְּׁנִיָּה מִלִּפְנֵי הָרוּחַ הָרִאשׁוֹנָה. וְלָכֵן מִי שֶׁנּוֹשֵׂא אַלְמָנָה, קוֹרְאִים עָלָיו (משלי ז) וְלֹא יָדַע כִּי בְנַפְשׁוֹ הוּא. (שם א) כִּי חִנָּם מְזרָה הָרָשֶׁת וְגוֹ'. וְלֹא יָדוּעַ אִם הִיא בַּת זוּגוֹ מַמָּשׁ וְאִם לֹא.</p>\n<p>אַלְמָנָה שֶׁלֹּא נִשֵּׂאת, אַף עַל גַּב שֶׁבָּא בֶּן זוּגָהּ וְהִיא לֹא רוֹצָה לְהִנָּשֵׂא - הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כוֹפֶה אוֹתָהּ מִן הַדִּין, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לְאוֹתוֹ הָאִישׁ אִשָּׁה אַחֶרֶת, וְלֹא נִכְנֶסֶת בְּדִין כָּזֶה (ואין עליה בית דין בזה) בְּאוֹתוֹ הָעוֹלָם, וְאַף עַל גַּב שֶׁאֵין לָהּ בֵּן, שֶׁהֲרֵי אִשָּׁה לֹא מְצֻוָּה עַל פְּרִיָּה וּרְבִיָּה, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>הָאִשָּׁה הַזּוֹ שֶׁלֹּא נִשְּׂאָה פַּעַם שְׁנִיָּה, אוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ, מַה נַּעֲשֶׂה מִמֶּנָּה? יוֹשֶׁבֶת שָׁם שְׁנֵים עָשָׂר חֳדָשִׁים, וּבְכָל לַיְלָה וְלַיְלָה יוֹצֵא וּפוֹקֵד אֶת הַנֶּפֶשׁ, וְחוֹזֵר לִמְקוֹמוֹ אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים, כְּשֶׁהִסְתַּלֵּק דִּינוֹ שֶׁל אוֹתוֹ הָאִישׁ. שֶׁהֲרֵי כָּל אוֹתָם שְׁנֵים עָשָׂר חֳדָשִׁים, זוֹ הָרוּחַ כְּפוּפָה בְּעַצְבוּת כָּל יוֹם. אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים יוֹצֵאת מִשָּׁם וְהוֹלֶכֶת וְעוֹמֶדֶת בְּשַׁעַר גַּן עֵדֶן וּפוֹקֶדֶת אֶת הָעוֹלָם הַזֶּה אֶל אוֹתוֹ הַכְּלִי שֶׁיּוֹצֵאת מִמֶּנּוּ. וּכְשֶׁהָאִשָּׁה הַזּוֹ מִסְתַּלֶּקֶת מִן הָעוֹלָם, אוֹתָהּ רוּחַ יוֹצֵאת וּמִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ שֶׁלָּהּ, וְזוֹכָה בָּהּ לְבַעְלָהּ, וּשְׁנֵיהֶם מְאִירִים כָּרָאוּי בְּחִבּוּר אֶחָד.</p>\n<p>כֵּיוָן שֶׁבָּאנוּ לְמָקוֹם זֶה, עַכְשָׁו יֵשׁ לְגַלּוֹת דְּרָכִים נִסְתָּרוֹת שֶׁל רִבּוֹן הָעוֹלָם וְלֹא יוֹדְעִים בָּהֶם בְּנֵי אָדָם, וְכֻלָּם הוֹלְכִים בְּדֶרֶךְ אֱמֶת, כְּמוֹ שֶׁנֶּאֱמַר (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּקִים יֵלְכוּ בָם וּפֹשְׁעִים יִכָּשְׁלוּ בָם. וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים כַּמָּה הֵם עֶלְיוֹנִים מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא וְכַמָּה הֵם מְשֻׁנִּים, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים, וְכֻלָּם בְּדֶרֶךְ אֱמֶת, שֶׁלֹּא סוֹטִים יָמִינָה וּשְׂמֹאלָה.</p>\n<p>אֵלֶּה שֶׁמִּתְגַּלְגְּלִים, שֶׁגֹּרְשׁוּ בְגֵרוּשִׁין מֵאוֹתוֹ הָעוֹלָם וְאֵין לָהֶם בַּת זוּג, בַּת הַזּוּג שֶׁהֵם מִזְדַּוְּגִים בָּעוֹלָם הַזֶּה, מֵאֵיפֹה הֵן אוֹתָן נָשִׁים שֶׁמִּזְדַּוְּגוֹת עִמָּם בָּעוֹלָם הַזֶּה, שֶׁהֲרֵי (גרש אותה ואין לו בת זוג כאותם גברים שלא גרשו ומזדוגים עם נשותיהם) לְכָל בְּנֵי הָאָדם יֵשׁ בַּת זוּג, חוּץ מִזֶּה?</p>\n<p>רְאוּ עַכְשָׁו כַּמָּה גְדוֹלִים וְעֶלְיוֹנִים גְּבוּרוֹתָיו. שָׁנִינוּ, מִי שֶׁמְּגָרֵשׁ אִשְׁתּוֹ הָרִאשׁוֹנָה, מִזְבֵּחַ מוֹרִיד עָלָיו דְּמָעוֹת. לָמָּה מִזְבֵּחַ? אֶלָּא הֲרֵי אָמַרְנוּ שֶׁכָּל נְשׁוֹת הָעוֹלָם עוֹמְדוֹת בִּדְמוּת הַמִּזְבֵּחַ הַזֶּה, וְעַל זֶה הֵן יוֹרְשׁוֹת שֶׁבַּע בְּרָכוֹת, שֶׁכֻּלָּן הֵן מִכְּנֶסֶת יִשְׂרָאֵל. וְאִם הוּא מְגָרֵשׁ אוֹתָהּ, חוֹזֶרֶת הָאֶבֶן (של המזבח העליון) לְגֵרָעוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּתְחַבְּרִים הַגֵּרוּשִׁין זֶה עִם זֶה.</p>\n<p>וְסוֹד זֶה, שֶׁכָּתוּב (דברים כד) וְכָתַב לָהּ סֵפֶר כְּרִיתֻת וְנָתַן בְּיָדָהּ וְגוֹ', וְיָצְאָה מִבֵּיתוֹ וְהָלְכָה וְהָיְתָה לְאִישׁ אַחֵר. מִמַּשְׁמָע שֶׁאָמַר וְהָלְכָה וְהָיְתָה לְאִישׁ, לֹא יָדַעְנוּ (שאותה שהולכת אצל בעלה שגרש אותה) (שזה אינו) (אותו שגרש אותה) ? מַה זֶּה אַחֵר? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר, שָׁנִינוּ אַחֵר, וְאַחֵר כָּתוּב, וְאַחֵר קוֹרְאִים אוֹתוֹ, שֶׁכָּתוּב (איוב ח) וּמֵעָפָר אַחֵר יִצְמָחוּ. וְהַגֵּרוּשִׁים מִתְחַבְּרִים כְּאֶחָד, גֵּרוּשִׁים שֶׁל אוֹתוֹ הָעוֹלָם וְגֵרוּשִׁים שֶׁל הָעוֹלָם הַזֶּה. וּמַה שֶּׁהָאִשָּׁה הַזּוֹ הָיְתָה בִּדְיוֹקָן עֶלְיוֹן, הֲרֵי הִשְׁתַּעְבְּדָה לִדִיוֹקָן תַּחְתּוֹן, קוֹרְאִים לוֹ אַחֵר.</p>\n<p>וְקֹוֹרְאִים לוֹ אַחֲרוֹן. מִנַּיִן לָנוּ אַחֲרוֹן? שֶׁכָּתוּב (שםיט) וְאַחֲרוֹן עַל עָפָר יָקוּם. וְכָאן כָּתוּב וּשְׂנֵאָהּ הָאִישׁ הָאַחֲרוֹן. אוֹ, כִּי יָמוּת הָאִישׁ הָאַחֲרוֹן. אַחֲרוֹן? שֵׁנִי הָיָה צָרִיךְ לִהְיוֹת! וְאִם תֹּאמַר שֶׁלֹּא תִזְדַּוֵּג אֲפִלּוּ לַעֲשָׂרָה זֶה אַחַר זֶה - לֹא כָּךְ. וְכִי לַבַּעַל הַזֶּה תִּזְדַּוֵּג וְלֹא לְאַחֵר. מַה זֶּה אַחֲרוֹן?</p>\n<p>אֶלָּא זֶהוּ הָאַחֵר הַזֶּה שֶׁאָמַרְנוּ, וְהוּא אַחֵר, וְהוּא אַחֲרוֹן. עַכְשָׁו הָאֶבֶן מִתְגַּלְגֶּלֶת בְּכַף הַקֶּלַע. לָמָּה אַחֵר נִקְרָא כָּךְ? שֶׁהֲרֵי כָּל הַבִּנְיָן נָפַל וְחָזַר לְעָפָר, הוּא הָיָה מַה שֶּׁהָיָה וְלֹא אַחֵר. לָמָּה קוֹרְאִים לוֹ אַחֵר? אַף כָּךְ לָמָּה נִקְרָא אַחֲרוֹן, וְכִי הוּא אַחֲרוֹן? וַהֲרֵי אִם יִתְיַשֵּׁר - יָפֶה, וְאִם לֹא - יַחֲזֹר וְיִתְגַּלְגֵּל וְיִנָּטַע כְּמִקֹּדֶם. לָמָּה נִקְרָא אַחֲרוֹן?</p>\n<p>אֲבָל בּא וּרְאֵה, כָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. מַה זֶּה טוֹב? שָׁנִינוּ, זֶה מַלְאַךְ הַטּוֹב. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת. וְלַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין תִּקּוּנוֹ.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (שם ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. נָהָר זֶה לֹא שׁוֹכֵךְ לְעוֹלָמִים מִלִּרְבּוֹת וּמִלִּגְדֹּל וְלַעֲשׂוֹת פֵּרוֹת. וְאֵל אַחֵר הִסְתָּרֵס, וְאֵין לוֹ תְּשׁוּקָה לְעוֹלָמִים, וְלֹא מַרְבֶּה וְלֹא עוֹשֶׂה פֵרוֹת. שֶׁאִלְמָלֵא עָשָׂה פֵרוֹת, יְבַלְבֵּל אֶת כָּל הָעוֹלָם.</p>\n<p>וּמִשּׁוּם כָּךְ אָדָם שֶׁגּוֹרֵם לְאוֹתוֹ הַצַּד לִגְדֹּל בָּעוֹלָם נִקְרָא רַע, וְלֹא רוֹאֶה פְּנֵי שְׁכִינָה לְעוֹלָמִים, שֶׁכָּתוּב (תהלים ה) לֹא יְגֻרְךְ רָע. הָאִישׁ הַזֶּה שֶׁמִּתְגַּלְגֵּל בְּגִלְגּוּל, אִם עָבַר וְנִדְבַּק בְּאוֹתוֹ אֵל אַחֵר שֶׁלֹּא עוֹשֶׂה פֵרוֹת וְלֹא מִתְרַבֶּה בָּעוֹלָם, מִשּׁוּם כָּךְ נִקְרָא אַחֵר, וְהַשֵּׁם גּוֹרֵם לוֹ. הוּא הוּא, וְאַחֵר נִקְרָא, אַחֵר וַדַּאי.</p>\n<p>אַחֲרוֹן - מֵרִאשׁוֹן וְאֵילָךְ אַחֲרוֹן קוֹרְאִים לוֹ, וְאַחֲרוֹן נִקְרָא. שֵׁנִי הוּא, וּמִיָּד נִקְרָא אַחֲרוֹן, וְכָךְ קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אַחֲרוֹן, מִשּׁוּם שֶׁנִּתְקָן לִהְיוֹת אַחֲרוֹן וְלֹא יָשׁוּב כְּמִקֹּדֶם. הַשְּׁלִישִׁי אַף כָּךְ. וְכֵן בְּכָל הַפְּעָמִים מֵהָרִאשׁוֹן וְאֵילָךְ, כָּךְ נִקְרָא אַחֲרוֹן, וְכֵן צָרִיךְ לִקְרֹא אַחֲרוֹן, שֶׁאִלְמָלֵא נִקְרָא מִיָּד שֵׁנִי, הֲרֵי יֵשׁ פִּתְחוֹן פֶּה לַחֲזֹר כְּמִקֹּדֶם, וְאוֹתוֹ בִּנְיָן נֶהֱרַס.</p>\n<p>מִנַּיִן לָנוּ? מִבַּיִת שֵׁנִי שֶׁנִּקְרָא אַחֲרוֹן, שֶׁכָּתוּב (חגי ב) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן. שֶׁהֲרֵי מֵרִאשׁוֹן וְאֵילָךְ נִקְרָא אַחֲרוֹן, שֶׁהֲרֵי לֹא יִהְיֶה פִּתְחוֹן פֶּה שֶׁאוֹתוֹ בִּנְיָן יִפֹּל וְיַחֲזֹר כְּמִקֹּדֶם.</p>\n<p>אַף זֶה כָּךְ, אַחֲרוֹן קוֹרְאִים לוֹ. וְלָכֵן כָּתוּב לֹא יוּכַל בַּעְלָהּ הָרִאשׁוֹן אֲשֶׁר שִׁלְּחָהּ לָשׁוּב לְקַחְתָּהּ. לֹא יוּכַל? לֹא יִקָּחֶנָּה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לֹא יוּכַל? אֶלָּא כֵּיוָן שֶׁהָאִשָּׁה הַזּוֹ נִדְבְּקָה בְּאַחֵר וְיָרְדָה לְהִשְׁתַּעְבֵּד בְּדַרְגָּה תַחְתּוֹנָה, לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיָּשׁוּב מִדַּרְגָּתוֹ לָתֵת פְּרִי וּלְהִדָּבֵק בְּאוֹתָהּ דַּרְגָּה שֶׁאֵינָהּ שֶׁלּוֹ.</p>\n<p>וּבֹא רְאֵה, אִם הָאִשָּׁה הַזּוֹ לֹא נִשֵּׂאת, אֲפִלּוּ תִּזְנֶה עִם כָּל הָאֲנָשִׁים שֶׁבָּעוֹלָם - אִם רוֹצֶה בַעְלָהּ, יָשׁוּב אֵלֶיהָ. אֲבָל אִם נִדְבְּקָה בְּנִשּׂוּאִין לְאַחֵר, (ואחר) זֶה (זה) לֹא יוּכַל לָשׁוּב לְדַרְגָּתוֹ הָרִאשׁוֹנָה שֶׁהָיָה בַּתְּחִלָּה אֵלֶיהָ. לֹא יוּכַל וַדַּאי לְהָשִׁיב אוֹתָהּ הַדַּרְגָּה לְעוֹלָמִים.</p>\n<p>אַחֲרֵי אֲשֶׁר הֻטַּמָּאָה. שָׁנִינוּ, שֶׁהֻטַּמָּאָה בְּלִבּוֹ. אִם כָּךְ, אֲפִלּוּ אִם תִּתְרַחֵק וְתִזְנֶה בְּלִי נִשּׂוּאִין? אֶלָּא כֵּיוָן שֶׁנִּדְבְּקָה לְאַחֵר, הֲרֵי קִבְּלָה עָלֶיהָ אֶת הַחֵלֶק שֶׁל אוֹתוֹ הַצַּד, וּבַעְלָהּ הָרִאשׁוֹן שֶׁהוּא מִצַּד אַחֵר טוֹב שֶׁל טוֹב, לֹא יִהְיֶה לוֹ בָּהּ חֵלֶק לְעוֹלָמִים, וְלֹא יַרְבֶּה כְּלָל אֶת אוֹתוֹ מָקוֹם. הֲרֵי אִם שִׁלְּחָהּ הָאִישׁ הָאַחֲרוֹן אוֹ כִי יָמוּת הָאִישׁ הָאַחֲרוֹן - לָרִאשׁוֹן אֲסוּרָה, אֲבָל לִשְׁאָר בְּנֵי אָדָם מֻתֶּרֶת. אוּלַי תִּמְצָא מָקוֹם כְּמוֹ מִקֹּדֶם, וְאַחֲרוֹן יָקוּם וְיִזְדַּוֵּג עִמָּהּ.</p>\n<p>מִי שֶׁיֵּשׁ לוֹ בָּנִים מֵאִשְׁתּוֹ הָרִאשׁוֹנָה וּמַכְנִיס אֶת זוֹ לְתוֹךְ בֵּיתוֹ, אוֹתוֹ הַיּוֹם הוּא נִדְבָּק בְּחֶרֶב קָשָׁה שֶׁמִּתְהַפֶּכֶת בִּשְׁבִיל שְׁנֵי צְדָדִים. אֶחָד - שֶׁהֲרֵי שְׁנַיִם הִיא דָּחֲתָה הַחוּצָה, וְעַכְשָׁו הוּא הַשְּׁלִישִׁי. וְעוֹד - כְּלִי שֶׁהִשְׁתַּעְבֵּד (שהשתתף) בּוֹ אַחֵר, אֵיךְ הוּא יָבֹא לָתֵת בָּהּ רוּחוֹ שֶׁלּוֹ וְיִשְׁתַּתֵּף עִמָּהּ וְיִדְבַּק בָּהּ? לֹא שֶׁהִיא אֲסוּרָה, אֲבָל וַדַּאי שִׁתּוּף רַע הוּא לְעַצְמוֹ (כמו שבארנו).</p>\n<p>רַבִּי לְוִיטַס אִישׁ כְּפַר אוֹנוֹ הָיָה צוֹחֵק וּמִתְלוֹצֵץ עַל הָאִשָּׁה הַזּוֹ, כְּשֶׁרָאָה מִי מִזְדַּוֵּג עִמָּהּ, וְהָיָה אוֹמֵר, (משלי לא) וַתִּשְׂחַק לְיוֹם אַחֲרוֹן כָּתוּב. מִי שֶׁנִּדְבֶּקֶת בּוֹ בְּאִישׁ אַחֲרוֹן, אַחַר כָּךְ הִיא צְחוֹק.</p>\n<p>עֵכְשָׁו יֵשׁ לַחֲזֹר וּלְעַיֵּן עַל מָקוֹם (נ\"א אילן) אֶחָד גָּדוֹל וְעֶלְיוֹן שֶׁהָיָה בָּעוֹלָם, וְגֶזַע וְשֹׁרֶשׁ שֶׁל אֱמֶת, וְהוּא עוֹבֵד אֲבִי יִשַׁי אֲבִי דָוִד, שֶׁהֲרֵי נֶאֱמַר שֶׁהָיָה אַחֲרוֹן, אֵיךְ יָצָא שֹׁרֶשׁ אֱמֶת מֵהַמָּקוֹם הַזֶּה?</p>\n<p>אֶלָּא עוֹבֵד נִתְקָן בְּתִקּוּן עֶלְיוֹן, וְחָזַר הַשֹּׁרֶשׁ שֶׁל הָאִילָן שֶׁהִתְהַפֵּךְ עַל תִּקּוּנוֹ, וְהִתְעַלָּה בּוֹ וְהִתְתַּקֵּן כָּרָאוּי, וְעַל זֶה נִקְרָא עוֹבֵד, מַה שֶּׁלֹּא זָכוּ כָּךְ שְׁאָר בְּנֵי הָעוֹלָם.</p>\n<p>הוּא בָּא, עָבַד וְעָדַר אֶת עִקַּר וְשֹׁרֶשׁ הָאִילָן, וְיָצָא מֵהַפָּנִים הַמָּרִים, וְחָזַר וְנִתְקָן בְּנוֹף שֶׁל אִילָן אַחֵר עֶלְיוֹן. בָּא יִשַׁי בְּנוֹ וְחִזֵּק אוֹתוֹ וְתִקֵּן אוֹתוֹ, וְנֶאֱחַז בְּעַנְפֵי הָאִילָן הָעֶלְיוֹן הָאַחֵר, וְחִבֵּר אִילָן בְּאִילָן, וְהִסְתַּבְּכוּ זֶה בָּזֶה. כֵּיוָן שֶׁבָּא דָוִד, מָצָא אִילָנוֹת מְסֻבָּכִים וּמְאֻחָדִים זֶה בָּזֶה. אָז יָרַשׁ הַשִּׁלְטוֹן בָּאָרֶץ, וְעוֹבֵד גָּרַם אֶת זֶה.</p>\n<p>בָּכָה אוֹתוֹ זָקֵן וְאָמַר, אִי זָקֵן זָקֵן, וְלֹא אָמַרְנוּ לְךְ שֶׁנִּכְנַסְתָּ לַיָּם הַגָּדוֹל?! עַכְשָׁו אַתָּה הוּא בְּתוֹךְ הַתְּהוֹמוֹת הַגְּדוֹלִים. הִתְתַּקֵּן לַעֲלוֹת. זָקֵן זָקֵן, אַתָּה גָּרַמְתָּ לָזֶה, שֶׁאִלְמָלֵא הָיִיתָ שׁוֹתֵק בַּתְּחִלָּה, הָיָה נָאֶה לְךְ, אֲבָל עַכְשָׁו לֹא יָכֹלְתָּ וְאֵין מִי שֶׁיֹּאחֵז בְּיָדְךְ, אֶלָּא אַתָּה בִּלְבַדְּךְ. קוּם זָקֵן וַעֲלֵה בְמַעֲלָה.</p>\n<p>עוֹבֵד זֶה הִתְתַּקֵּן וְיָצָא מִתּוֹךְ שָׂדֶה רַע שֶׁל בּוֹרוֹת רָעִים. בָּא יִשַׁי בְּנוֹ וְהִתְקִין וְעָדַר אֶת הָאִילָן, וְעִם כָּל זֶה, (ועובד) זֶה סוֹד הַסּוֹדוֹת, וְלֹא יָדַעְתִּי אִם אֹמַר וְאִם לֹא אֹמַר. אֱמֹר דְּבָרֶיךְ, זָקֵן, וַדַּאי אֱמֹר, בָּזֶה יְדוּעִים כָּל שְׁאָר בְּנֵי הַגִּלְגּוּל. (עובד התקין אילן, ועם כל זה שהתקין אילן) עוֹבֵד עִם כָּל זֶה הִתְקִין אִילָן. כְּשֶׁבָּא דָוִד הַמֶּלֶךְ, נִשְׁאַר בָּאִילָן הַתַּחְתּוֹן שֶׁל הַנְּקֵבָה, וְהִצְטָרֵךְ לְקַבֵּל חַיִּים מֵאַחֵר. וּמָה אִם זֶה שֶׁהִתְתַּקֵּן וְהִתְקִין הַכֹּל כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם שֶׁבָּאִים בְּגִלְגּוּל, שֶׁלֹּא יְכוֹלִים לְהִתְתַּקֵּן כָּךְ, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>בְּכָל הַצְּדָדִים מִתְהַפֵּךְ בְּגִלְגּוּל. כָּךְ הָיָה פֶּרֶץ. כָּךְ הָיָה בּעַז. כָּךְ הָיָה עוֹבֵד. (ועםכלזההאילןנתקן) וּבַכֹּל יוֹצֵא אִילָן מִצַּד הָרָע, וְאַחַר כָּךְ נִדְבָּק בַּצַּד הַטּוֹב. בַּתְּחִלָּה, וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע. (אונן אף כך) מַחְלוֹן אַף כָּךְ וְלֹא כָּל כָּךְ. אֲבָל בְּאֵלֶּה הִתְעַכֵּל הָרָע, וְיָצָא אַחַר כָּךְ טוֹב, (יצא) אוֹתוֹ שֶׁכָּתוּב בּוֹ (שמואל א טז) וְטוֹב רֹאִי. וַה' עִמּוֹ. עַכְשָׁו עוֹמֵד אִילָן תַּחְתּוֹן עַל תִּקּוּנוֹ, וּמֶלֶךְ אֱלֹהִים עַל גּוֹיִם.</p>\n<p>בְּרֵאשִׁית הַכֹּל, מֵעִקַּר וִיסוֹד עֶלְיוֹן הִשְׁתָּרְשׁוּ דְרָגוֹת, רְאוּבֵן שִׁמְעוֹן לֵוִי יְהוּדָה. מַה כָּתוּב בּוֹ? (בראשית כט) הַפַּעַם אוֹדֶה אֶת ה'. וְכָתוּב וַתַּעֲמֹד מִלֶּדֶת. הַיְנוּ (ישעיה נד) רָנִּי עֲקָרָה לֹא יָלָדָה. מִשּׁוּם שֶׁכְּשֶׁנּוֹלַד יְהוּדָה, יָצְאָה נְקֵבָה דְּבוּקָה בְזָכָר, וְלֹא הָיְתָה עַל תִּקּוּנֶיהָ פָּנִים בְּפָנִים וְלֹא הֻכְשְׁרָה לָלֶדֶת. כֵּיוָן שֶׁנִּסֵּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְקִין אוֹתָהּ, (פנים בפנים) אָז הֻכְשְׁרָה לְהִתְעַבֵּר וְלָלֶדֶת.</p>\n<p>וּבְסִפְרוֹ שֶׁל חֲנוֹךְ, וַתַּעֲמֹד מִלֶּדֶת לֹא נֶאֱמַר עַל לֵאָה, אֶלָּא נֶאֱמַר עַל רָחֵל, אוֹתָהּ שֶׁמְּבַכָּה עַל בָּנֶיהָ, אוֹתָהּ שֶׁנִּשְׁרְשָׁה בִּיהוּדָה - יְה\"וּ דָ\"ה. וַתַּעֲמֹד מִלֶּדֶת, שֶׁהֲרֵי לֹא נִתְקְנָה.</p>\n<p>בַּתְּחִלָּה דְּיוֹקַן הָעֶלְיוֹן הָיָה הַכֹּל רְאוּבֵן - אוֹ\"ר בֵּ\"ן. (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, יָמִין אוֹר. (ב\"ן) שִׁמְעוֹן שְׂמֹאל אוֹר, בְּאוֹתוֹ סִיג שֶׁהַזָּהָב עִמּוֹ - שָׁם עָון. לֵוִי - חִבּוּר שֶׁל הַכֹּל לְהִתְחַבֵּר מִשְּׁנֵי צְדָדִים. יְהוּדָה - נְקֵבָה עִם זָכָר נִדְבֶּקֶת. יְה\"וּ - זֶה זָכָר. דָ\"ה - זוֹ נְקֵבָה שֶׁהָיְתָה עִמּוֹ.</p>\n<p>דָ\"ה, לָמָּה דָ\"ה? אֶלָּא ד' בְּהִדָּבְקוּת שֶׁל רַע עִמָּהּ הִיא דָלֶ\"ת, הִיא עֲנִיָּה, וּצְרִיכָה לָשׁוּב בְּגִלְגּוּל לְבַעֵר אֶת אוֹתוֹ הָרָע וּלְהִתְבַּלּוֹת בֶּעָפָר, וְאַחַר לִצְמֹחַ בַּצַּד הַטּוֹב וְלָצֵאת מֵעֹנִי לְעֹשֶׁר, וְאָז ה'. וְעַל זֶה יְה\"וּ דָ\"ה.</p>\n<p>צֵא זָקֵן מִתּוֹךְ הַתְּהוֹמוֹת, אַל תִּפְחַד, כַּמָּה סְפִינוֹת מְזֻמָּנוֹת לְךְ בְּשָׁעָה שֶׁתָּשׁוּט בַּיָּם כְּדֵי לָנוּחַ בָּהֶן. בָּכָה כְּמוֹ מִקֹּדֶם וְאָמַר, רִבּוֹן הָעוֹלָם, אוּלַי יֹאמְרוּ הַמַּחֲנוֹת הָעֶלְיוֹנִים שֶׁאֲנִי זָקֵן וּבוֹכֶה כְּתִינוֹק. גָּלוּי לְפָנֶיךְ שֶׁעַל כְּבוֹדְךְ אֲנִי עוֹשֶׂה, וְלֹא עָשִׂיתִי לִכְבוֹדִי, שֶׁהֲרֵי בַּתְּחִלָּה הָיָה לִי לְהִשָּׁמֵר שֶׁלֹּא אֶכָּנֵס לַיָּם הַגָּדוֹל, וְעַכְשָׁו כֵּיוָן שֶׁאֲנִי בּוֹ, יֵשׁ לִי לְשׁוֹטֵט בְּכָל הַצְּדָדִים וְלָצֵאת מִמֶּנּוּ.</p>\n<p>יְהוּדָה אַתָּה יוֹדוּךְ אַחֶיךְ, (כולם מודים על השם הזה) הַיְנוּ מַה שֶּׁאָנוּ אוֹמְרִים בָּרוּךְ אַתָּה, הוּא בָּרוּךְ וְהִיא אַתָּה. לְכָל בָּנָיו לֹא אָמַר יַעֲקֹב אַתָּה, אֶלָּא לְמָקוֹם שֶׁהִצְטָרֵךְ. זֶהוּ אַתָּה.</p>\n<p>הַשֵּׁם הַזֶּה (ודאי אתה) יוֹדוּךְ אַחֶיךְ. כֻּלָּם מוֹדִים לְךְ עַל הַשֵּׁם הַזֶּה. וַדַּאי אַתָּה יוֹדוּךְ אַחֶיךְ, עַל הַשֵּׁם הַזֶּה הִסְתַּלֵּק וְנִכְפָּה הַצַּד הָאַחֵר, מִשּׁוּם שֶׁכְּשֶׁנִּקְרָא וְנִזְכָּר, הֲרֵי יוֹצֵא אִתּוֹ הַצַּד הָאַחֵר. כֵּיוָן שֶׁאוֹמְרִים אַתָּה, שִׁלְטוֹן וּגְדֻלָּה יֵשׁ לָהּ, וְהַצַּד הָאַחֵר נִכְפֶּה וְלֹא נִרְאֶה שָׁם. וַדַּאי שֶׁבַּשֵּׁם הַזֶּה נִרְשָׁם וְנִבְחָר מֵהַצַּד הָאַחֵר. וְזוֹ הָעֲלִיָּה וְהַמֶּמְשָׁלָה שֶׁלָּהּ, וְשֶׁבֶר וְרַע לַצַּד הָאַחֵר. כֵּיוָן שֶׁיּוֹדוּךְ אַחֶיךְ עַל הַשֵּׁם הַזֶּה, אַתָּה, אָז יָדְךְ בְּעֹרֶף אֹיְבֶיךְ, מִיָּד נִכְנָעִים אֵלֶיךְ, וְהַשֵּׁם הַזֶּה גּוֹרֵם.</p>\n<p>יָדַעִִתִּי, חֲבֵרִים, יָדַעְתִּי, שֶׁאַתָּה הֲרֵי הַשֵּׁם הַזֶּה, אַתֶּם אוֹמְרִים לְמָקוֹם עֶלְיוֹן אַחֵר, שֶׁכָּתוּב (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם, בַּיָּמִין הָעֶלְיוֹן. יָפֶה הוּא, שֶׁהֲרֵי כֵּיוָן שֶׁרַבִּי שִׁמְעוֹן מוֹדִים לוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְזָכָה לַכֹּל. כָּל מַה שֶּׁהוּא אוֹמֵר, כָּךְ זֶה וְיָפֶה.</p>\n<p>אֲבָל כְּשֶׁתִּהְיוּ מַגִּיעִים אֵלָיו, אִמְרוּ לוֹ וְהַזְכִּירוּ לוֹ אֶת יוֹם הַשֶּׁלֶג כְּשֶׁזָּרַעְנוּ פּוֹלִים לַחֲמִשִּׁים וּשְׁנַיִם גְּוָנִים, שֶׁהֲרֵי אַתָּה כֹהֵן. כָּאן נִקְשָׁר כּוֹס שֶׁל בְּרָכָה בַּיָּמִין בְּלִי פֵרוּד כְּלָל, וּמִשּׁוּם כָּךְ, אַתָּה כֹהֵן לְעוֹלָם. כָּאן נִקְשָׁר כּוֹס בַּיָּמִין כָּרָאוּי.</p>\n<p>וְעַל זֶה אָמַר הַכָּתוּב, יְהוּדָה אַתָּה, לָאַתָּה הַזֶּה יוֹדוּךְ אַחֶיךְ, וְלֹא כָתוּב יְהוּדָה יוֹדוּךְ אַחֶיךְ וְלֹא יוֹתֵר, אֶלָּא עַל שֵׁם שֶׁל אַתָּ\"ה. אַתָּה - מָקוֹם זֶה הִצְטָרֵךְ לַשֵּׁם הַזֶּה, וְלֹא אַחֵר.</p>\n<p>יְהוּדָה - הָאָב הָרִאשׁוֹן וְהָאָב הַשֵּׁנִי, וְלֹא הָיָה בּוֹ חִלּוּף לְעוֹלָמִים. וּמִשּׁוּם כָּךְ פֶּרֶץ הִתְגַּבֵּר בּוֹ בִּגְבוּרָתוֹ מַה שֶּׁלֹּא הָיָה כָּךְ לְכָל בְּנֵי הָעוֹלָם. וְעַל כָּךְ בִּנְיָנוֹ שֶׁל דָּוִד מַתְחִיל אֶת הַחֶשְׁבּוֹן מִפֶּרֶץ, וְלֹא מִבֹּעַז, שֶׁהָיָה בּוֹ שִׁנּוּי. חֲבֵרִים, אִם תַּשְׁגִּיחוּ, לֹא אָמַרְתִּי דְבָרִים בְּסֵתֶר, וְאַף עַל גַּב שֶׁהֵם נִסְתָּרִים.</p>\n<p>וְעַל כָּךְ יְהוּדָה הִרְוִיחַ אֶת הַשֵּׁם הַזֶּה שֶׁנִּקְרָא אַתָּ\"ה. עָמַד עַל בֻּרְיוֹ פַּעַם רִאשׁוֹנָה וּפַעַם שְׁנִיָּה וְלֹא הִשְׁתַּנָּה לְעוֹלָם. וּבְנֵי יְהוּדָה וְזַרְעוֹ מוֹדִים וְאוֹמְרִים כִּי אַתָּה אָבִינוּ, מַה שֶּׁאֵין כֵּן לִשְׁאָר בְּנֵי הַגִּלְגּוּל לְעוֹלָמִים. שְׁאָר בְּנֵי הַגִּלְגּוּל, שְׁנֵי אָבוֹת, שְׁתֵּי אִמָּהוֹת, יֵשׁ לָהֶם גָּוֶן לַבִּנְיָן. וְסוֹדוֹת הַלָּלוּ בְּעִמְקֵי הַיָּם, הֵם בְּלֵב הַתְּהוֹמוֹת, מִי יָכוֹל לְהוֹצִיא אוֹתָם? קוּם זָקֵן, הִתְגַּבֵּר וְהִתְחַזֵּק בְּחָזְקְךְ וְהוֹצֵא מַרְגָּלִיּוֹת מִתּוֹךְ הַתְּהוֹמוֹת!</p>\n<p>בֹּעַז נִרְאֶה שֶׁהָיָה בּוֹ שִׁנּוּי כְּשֶׁהוֹלִיד אֶת עוֹבֵד, שֶׁהֲרֵי עוֹבֵד (מעשה) הוּא בְּשִׁנּוּי. לֹא כָּךְ. אִבְצַן הוּא בּעַז, הוּא הָאָב הָרִאשׁוֹן שֶׁלֹּא עָשָׂה שִׁנּוּי. וְאִם תֹּאמַר שֶׁהוּא הָיָה, וַדַּאי כְּשֶׁהִתְעוֹרֵר לַמַּעֲשֶׂה הַזֶּה הָיָה בּוֹ, מִי שֶׁהוּא גִּבּוֹר כַּאֲרִי וּכְלָבִיא הָיָה בּוֹ, כְּדֵי שֶׁלֹּא יִהְיֶה שִׁנּוּי בְּדָוִד, וְחָזַר הַדָּבָר לָעִקָּר הָרִאשׁוֹן כְּדֵי שֶׁהַכֹּל יִהְיֶה מֵאָב אֶחָד, וְשַׁלְשֶׁלֶת אַחַת. וְהַכֹּל אֶחָד, וְלֹא הָיָה שִׁנּוּי בַּגִּלְגּוּל שֶׁל זֶרַע דָּוִד. וְעַל זֶה אַתָּה, מֵרֹאשׁ וְעַד סוֹף, בְּלִי שִׁנּוּי כְּלָל.</p>\n<p>עֵכְשָׁו יָצָאתָ זָקֵן מֵעֹמֶק שֶׁל לֵב הַיָּם. יְהוּדָה אַתָּה, וַדַּאי מֵרֹאשׁ וְעַד סוֹף, וְלֹא רָאוּי לְכָל שְׁאָר הַבָּנִים שֶׁיִּקָּרְאוּ אַתָּה, אֶלָּא לוֹ לְבַדּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל דָּוִד שֶׁכָּךְ נִבְחַר וְהִתְעַלָּה מִשְּׁאָר הָעִקָּר שֶׁל אָדָם בָּאָרֶץ.</p>\n<p>יוֹדוּךָ אַחֶיךְ, יוֹדוּךְ כָּל בְּנֵי הָעוֹלָם הָיָה צָרִיךְ לִהְיוֹת! מָה הַטַּעַם אַחֶיךְ? אֶלָּא שֶׁדֶּרֶךְ כָּל בְּנֵי הָעוֹלָם לֹא מִתְיַבְּמִים לְגִלְגּוּל אֶלָּא מֵהַצַּד שֶׁל הָאַחִים, וְהָאָח מְזֻמָּן לְיִבּוּם, (ואתה בעצמך הזדמנת ליבום), וְכָאן כָּל אַחֶיךְ יוֹדוּךְ, שֶׁלֹּא יִשְׁתַּלְשֵׁל מֵהֶם וְלֹא מֵאֶחָד מֵהֶם שַׁלְשֶׁלֶת הַמְּלוּכָה, אֶלָּא אַתָּה לְבַדְּךְ. אַתָּה מֵרֹאשׁ וְעַד סוֹף אַתָּה עָשִׂיתָ, וּמִמְּךְ יָצָא כָּל הַשַּׁלְשֶׁלֶת וְגֶזַע (דמות וגוף) שֶׁל הָאַרְיֵה.</p>\n<p>בָּנֶיךָ בְּנֵי אַרְיֵה, שֶׁלֹּא עָבְרוּ לְשִׁנּוּי שֶׁל אַחֶיךְ, לֹא הִתְחַלְּפוּ לְטָלֶה וְלֹא לְשׁוֹר וְלֹא לִגְדִי וְלֹא לְשׁוּם דְּיוֹקָן אַחֵר, אֶלָּא אַרְיֵה הִתְחִיל לִבְנוֹת, וְאַרְיֵה סִיֵּם אֶת הַבִּנְיָן. כָּל הַשַּׁלְשֶׁלֶת שֶׁלְּךְ הֵם בְּנֵי אַרְיֵה, שֶׁאִלְמָלֵא בָּא גִלְגּוּל מִצַּד אַחֶיךְ, יִתְחַלְּפוּ כָּל הַדְּיוֹקְנָאוֹת וְיִתְעָרְבוּ אֵלֶּה בְאֵלֶּה. וְלָכֵן יוֹדוּךְ אַחֶיךְ, שֶׁלֹּא הָיָה אֶחָד מֵהֶם בְּגִלְגּוּל הַשַּׁלְשֶׁלֶת שֶׁל בָּנֶיךְ. יָדְךְ הָרֵם, שֶׁלֹּא הָיָה בְּךְ עִרְבּוּבְיָה אַחֶרֶת מֵהֶם.</p>\n<p>וְהַיְנוּ מִטֶּרֶף בְּנִי עָלִיתָ, שֶׁלֹּא הָיָה טֶרֶף לְאַחֵר עַל שֻׁלְחָנְךְ. כָּרַע - בְּמִיתַת עֵר. רָבַץ - בְּמִיתַת אוֹנָן. אַחַר כָּךְ הִתְגַּבֵּר כַּאֲרִי לְהָקִים אֶת פֶּרֶץ, וּכְלָבִיא לְהָקִים אֶת זֶרַח. מִי יְקִימֶנּוּ? שֶׁכָּתוּב (בראשית לח) וְלֹא יָסַף עוֹד לְדַעְתָּהּ, וְתַרְגּוּם: וְלָא פָסַק. מִי יְקִימֶנּוּ, מִי הוּא שֶׁאָמַר אֲסוּרָה אִשָּׁה זוֹ. מִי הוּא שֶׁאָמַר, הוֹאִיל וְהִשְׁלִימָה אֶת צְרָכֶיהָ, לֹא הִצְטָרְכָה לְךְ יוֹתֵר, יְבָמָה זוֹ, כֵּיוָן שֶׁהִשְׁלִימָה דְרָכֶיהָ, לֹא הִצְטָרְכָה לְךְ יוֹתֵר, וְנִרְאֵית לִפְרשׁ מִמֶּנָּה. אֲבָל מִי יְקִימֶנּוּ, וַדַּאי שֶׁמִּשָּׁם וָהָלְאָה הִיא שֶׁלּוֹ, שֶׁהֲרֵי הוֹצִיאָה מִי שֶׁמְּכַשְׁכֵּשׁ בְּמֵעֶיהָ.</p>\n<p>סוֹד נִסְתָּר כָּאן, אֲחֵי הָאָדָם לָמָּה? וְעוֹד, יְהוּדָה שֶׁהָיָה אָבִיו לָמָּה? אֶלָּא אוֹתוֹ שֶׁמְּכַשְׁכֵּשׁ בְּמֵעֶיהָ רוֹאֶה שֶׁמִּי שֶׁשּׁוֹמֵר אוֹתוֹ, מְקַטְרֵג עָלָיו קִטְרוּגִים בְּכָל הַצְּדָדִים וְרוֹצֶה לָצֵאת. כֵּיוָן שֶׁיָּצָא, מַזְמִין אַחֵר אוֹתָהּ רוּחַ אַחֶרֶת, וּבָאִים לְהִכָּנֵס כְּמוֹ מִקֹּדֶם, עַד שֶׁנִּבְנֶה כְּמוֹ מִקֹּדֶם בְּכֹחַ הַקִּטְרוּג הַקָּשֶׁה שֶׁמְּקַטְרֵג בְּאָחִיו. מִשָּׁם וָהָלְאָה מֻתֶּרֶת לוֹ הָאִשָּׁה הַזּוֹ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל יְהוּדָה. בַּהַתְחָלָה הָיָה גּוּר. אַחַר כָּךְ אַרְיֵה, שֶׁמִּתְגַּבֵּר וּמִתְפַּשֵּׁט בְּכֹחוֹ (ואחר כך) כְּאַרְיֵה. וְסִיֵּם בְּלָבִיא. כָּל שְׁאָר בְּנֵי הָעוֹלָם לֹא כָּךְ, וְעַל זֶה יְהוּדָה, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>רְאוּבֵן שִׁמְעוֹן לֵוִי - הֲרֵי שְׁלֹשָׁה, כְּמוֹ שֶׁאָמַרְנוּ. יְהוּדָה הִתְחַבֵּר עִמָּם, וְהַכֹּל כָּרָאוּי. יִשָּׂשכָר וּזְבוּלוּן שְׁתֵּי יְרֵכַיִם. מָקוֹם שֶׁיּוֹנְקִים נְבִיאֵי הָאֱמֶת. יִשָּׂשכָר יָרֵךְ יָמִין, כָּתוּב וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִינָה לָעִתִּים (זבולון ירך שמאל), וְכָתוּב (דברים לג) שְׂמַח זְבוּלֻן בְּצֵאתֶךְ. וּבְשִׁעוּר גָּדוֹל כָּתוּב (בראשית מט) זְבוּלֻן לְחוֹף יַמִּים יִשְׁכֹּן וְהוּא לְחוֹף אֳנִיֹּת. מָה הַטַּעַם? מִשּׁוּם שֶׁוְּיַרְכָתוֹ עַל צִידן. שִׁעוּר (הירך שלו) עַד צִידוֹן.</p>\n<p>בִּנְיָמִין נִשְׁאָר לְמַעְלָה בֵּין הַיְרֵכַיִם, שֶׁהֲרֵי יוֹסֵף הָיָה דְיוֹקְנוֹ בָּאָרֶץ, וּלְהִשְׁתַּמֵּשׁ בָּעוֹלָם הַזֶּה, וְעִמּוֹ הִשְׁתַּמֵּשׁ מֹשֶׁה, שֶׁכָּתוּב (שמות יג) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ. בִּנְיָמִין הִסְתַּלֵּק לְמַעְלָה, בִּנְיָמִין צַדִּיקוֹ שֶׁל עוֹלָם.</p>\n<p>מְבָרְכִים לְמַטָּה - דָּן וְנַפְתָּלִי גָּד וְאָשֵׁר. בְּיֶרֶךְ שְׂמֹאל - דָּן עַד פֶּרֶק הָרֶגֶל, פֶּרֶק הָרֶגֶל נַפְתָּלִי, וּמִשּׁוּם כָּךְ נַפְתָּלִי אַיָּלָה שְׁלֻחָה, קַל בְּרַגְלָיו. בְּיֶרֶךְ יָמִין גָּד, וְהוּא יָגֻד עָקֵב, עַד פֶּרֶק הֶעָקֵב. אָשֵׁר פֶּרֶק שֶׁל עָקֵב יָמִין, וְטֹבֵל בַּשֶּׁמֶן רַגְלוֹ, וְכָתוּב בַּרְזֶל וּנְחֹשֶׁת מִנְעָלֶיךְ. כָּל אֵלֶּה הֵם דְּיוֹקְנָאוֹת עֶלְיוֹנִים, דְּיוֹקָן שֶׁלְּמַעְלָה. וּמִשּׁוּם שֶׁהָיוּ בְּרִיּוֹת מַמָּשׁ בָּעוֹלָם הַזֶּה, נִתְקְנָה בָהֶם הַשְּׁכִינָה בִּשְׁנֵים עָשָׂר הַפְּרָקִים הַלָּלוּ שְׁתֵּים עֶשְׂרֵה הִתְפַּשְּׁטֻיּוֹת שֶׁנִּתְפַּשְּׁטוּ מַמָּשׁ מִיִּשְׂרָאֵל, שֶׁכָּתוּב כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר. הִתְפַּשְּׁטֻיּוֹת שֶׁל יִשְׂרָאֵל, אֵלֶּה נִקְרָאִים. לְהִתְפַּשְּׁטוּת שֵׁם שֶׁל מִ\"י לִהְיוֹת בִּנְיָן כָּרָאוּי, לִהְיוֹת יִשְׂרָאֵל בִּכְלָל שֶׁל שֵׁם אֱלֹהִים. אֵלֶּ\"ה הוּא יִשְׂרָאֵל בִּכְלָל. מִ\"י חִבֵּר (ברא) אֵלֶּה עִמּוֹ, וְהָיָה בִּנְיָן שָׁלֵם עַל תִּקּוּנוֹ, שֵׁם אֶחָד מַמָּשׁ.</p>\n<p>זֶהוּ שֶׁאָמַר לוֹ לְיַעֲקֹב אוֹתוֹ הַמְמֻנֶּה שֶׁל עֵשָׂו, שֶׁכָּתוּב (בראשית לב) כִּי שָׂרִיתָ עִם אֱלֹהִים, (עם אנשים ותוכל) לְמַעְלָה, בְּתִקּוּן רִאשׁוֹן בְּבִנְיָן רִאשׁוֹן. כָּל אֵלֶּה, וַדַּאי בִּנְיָן רִאשׁוֹן הוּא.</p>\n<p>וְלָכֵן אֵין כִּלָּיוֹן לְיִשְׂרָאֵל לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. וְחַס וְשָׁלוֹם, אִלְמָלֵא יִכְלוּ, הַשֵּׁם הַזֶּה לֹא הָיָה. זֶהוּ שֶׁכָּתוּב (יהושע ז) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. שֵׁם הַגָּדוֹל זֶה הַבִּנְיָן הָרִאשׁוֹן, שֵׁם הָרִאשׁוֹן אֱלֹהִים. וְעַכְשָׁו שֶׁיִּשְׂרָאֵל בַּגָּלוּת, (יתחבר) כִּבְיָכוֹל נָפַל כָּל הַבִּנְיָן, וְלֶעָתִיד לָבֹא כְּשֶׁיִּגְאַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בָּנָיו מֵהַגָּלוּת, מִ\"י וְאֵלֶּ\"ה שֶׁהָיוּ בְפֵרוּד בַּגָּלוּת יִתְחַבְּרוּ כְאֶחָד, וְשֵׁם הָאֱלֹהִים יִהְיֶה שָׁלֵם עַל תִּקּוּנוֹ וְהָעוֹלָם יִתְבַּסֵּם. זֶהוּ שֶׁכָּתוּב (ישעיה ס) מִי אֵלֶּה כָּעָב תְּעוּפֶינָה וְכַיּוֹנִים אֶל אֲרֻבּתֵיהֶם.</p>\n<p>וּמִשּׁוּם שֶׁהוּא שֵׁם אֶחָד, לֹא כָתוּב מִי וְאֵלֶּה, אֶלָּא מִי אֵלֶּה, שֵׁם אֶחָד לְלֹא פֵרוּד, וְהוּא אֱלֹהִים. שֶׁעַכְשָׁו בַּגָּלוּת הִתְעַלָּה מִי לְמַעְלָה, כִּבְיָכוֹל הָאֵם מֵעַל הַבָּנִים, וְהַבָּנִים נָפְלוּ, וְהַשֵּׁם שֶׁהָיָה שָׁלֵם, שֶׁהוּא הַשֵּׁם הָעֶלְיוֹן הַגָּדוֹל הָרִאשׁוֹן, נָפַל.</p>\n<p>וְעל זֶה אָנוּ מִתְפַּלְלִים וּמְקַדְּשִׁים בְּבָתֵּי כְּנֵסִיּוֹת עַל הַשֵּׁם הַזֶּה שֶׁיִּבָּנֶה כְּמוֹ שֶׁהָיָה, וְאוֹמְרִים יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא. אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ. מִי זֶה שְׁמוֹ הַגָּדוֹל? אוֹתוֹ הָרִאשׁוֹן שֶׁל הַכֹּל, מִשּׁוּם שֶׁאֵין לוֹ בִּנְיָן אֶלָּא עִמָּנוּ. מִ\"י לֹא יִבָּנֶה לְעוֹלָם אֶלָּא בְּאֵלֶּה. וְעַל זֶה בְּאוֹתוֹ זְמַן, מִי אֵלֶּה כָּעָב תְּעוּפֶינָה, וְיִרְאוּ כָּל הָעוֹלָם שֶׁהֲרֵי הַשֵּׁם הָעֶלְיוֹן נִתְקָן עַל תִּקּוּנוֹ.</p>\n<p>וְאִם שְׁמוֹ הַגָּדוֹל הַזֶּה נִתְקָן וְנִבְנֶה עַל תִּקּוּנוֹ, הֲרֵי יִשְׂרָאֵל שׁוֹלְטִים עַל הַכֹּל, וְכָל שְׁאָר הַשֵּׁמוֹת יַחְזְרוּ עַל תִּקּוּנָם, וְיִשְׂרָאֵל שׁוֹלְטִים עַל הַכֹּל, שֶׁהֲרֵי כֻּלָּם תְּלוּיִים בִּשְׁמוֹ הַגָּדוֹל, רִאשׁוֹן לְכָל הַבִּנְיָנִים.</p>\n<p>סוֹד זֶה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָמוֹת. רִאשׁוֹן לְכָל הַבִּנְיָנִים, שֵׁם זֶה נִבְנָה, שֶׁכָּתוּב (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. בָּרָא שְׁמוֹ עַל תִּקּוּנוֹ. וּכְשֶׁבָּרָא אֵלֶּה, בָּרָא (שמו) אוֹתוֹ בְּכָל הַחֲיָלוֹת שֶׁנִּרְאִים לוֹ לִהְיוֹת שְׁמוֹ עַל תִּקּוּנוֹ כָּרָאוּי, שֶׁכָּתוּב הַמּוֹצִיא בְמִסְפָּר צְבָאָם.</p>\n<p>מַה זֶּה בְּמִסְפָּר? אֶלָּא בֵּן אֶחָד שֶׁמֵּאִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהוּא עֵץ גָּדוֹל וְחָזָק. רֹאשׁוֹ מַגִּיעַ לְגֹבַהּ הַשָּׁמַיִם, וְסוֹפוֹ מִתְפַּשְּׁטִים שָׁרָשָׁיו, וּמֻשְׁרָשִׁים בֶּעָפָר הַקָּדוֹשׁ, וּמִסְפָּר שְׁמוֹ. וְתָלוּי בַּשָּׁמַיִם הָעֶלְיוֹנִים, וַחֲמִשָּׁה רְקִיעִים תְּלוּיִים מִמֶּנּוּ עַד הַמִּסְפָּר הַזֶּה, וְכֻלָּם נוֹטְלִים שֵׁם זֶה בִּגְלָלוֹ, שֶׁכָּתוּב (תהלים יט) הַשָּׁמַיִם מְסַפְּרִים, בִּגְלַל מִסְפָּר זֶה. כָּל (בשביל השם הזה מספר) הַשָּׁמַיִם מַרְוִיחִים אֶת הַשֵּׁם הַזֶּה בִּגְלָלוֹ. וְעַל זֶה הַמּוֹצִיא בְמִסְפָּר צְבָאָם, שֶׁאִלְמָלֵא מִסְפָּר זֶה לֹא יִמָּצְאוּ חֲיָלוֹת וְתוֹלָדוֹת לְעוֹלָמִים.</p>\n<p>וְעַל זֶה כָּתוּב (במדבר כג) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. שְׁנַיִם הֵם שֶׁמָּנוּ צֹאן וְנִכְנְסוּ בְחֶשְׁבּוֹן עַל יְדֵיהֶם, בִּגְלַל שֶׁלֹּא שָׁלְטָה בָהֶם עַיִן הָרָע. מִי מָנָה עֲפַר יַעֲקֹב - הֲרֵי אֶחָד שֶׁעָשָׂה חֶשְׁבּוֹן. וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל - הֲרֵי מוֹנֶה אַחֵר.</p>\n<p>וְעַל שְׁנֵי אֵלֶּה לֹא שָׁלְטָה בָהֶם עַיִן הָרָע, שֶׁהֲרֵי מִי מָנָה לַעֲפַר יַעֲקֹב - אֵלֶּה אוֹתָן אֲבָנִים (דרגות) קְדוֹשׁוֹת, אֲבָנִים מְפֻלָּמוֹת שֶׁמֵּהֶן יוֹצְאִים מַיִם לְעוֹלָם. וְעַל זֶה כָּתוּב (בראשית כח) וְהָיָה זַרְעֲךְ כַּעֲפַר הָאָרֶץ. מָה אוֹתוֹ עָפָר הָעוֹלָם מִתְבָּרֵךְ בִּשְׁבִילוֹ, אַף כָּךְ (בראשית כב) וְהִתְבָּרֲכוּ בְזַרְעֲךְ כֹּל גּוֹיֵי הָאָרֶץ. כַּעֲפַר הָאָרֶץ מַמָּשׁ. וּמִסְפָּר, שֶׁהוּא מוֹנֶה שֵׁנִי, מָנָה אֶת רֹבַע כָּל אוֹתָן נְקֵבוֹת, מַרְגָּלִיּוֹת עֶלְיוֹנוֹת, שֶׁל הַמִּטָּה שֶׁשּׁוֹכֵב עָלֶיהָ יִשְׂרָאֵל.</p>\n<p>וּמִשָּׁם וָהָלְאָה הוּא מוֹנֶה לַכֹּל, מִשּׁוּם שֶׁהוּא טוֹב עַיִן. זֶהוּ שֶׁכָּתוּב מוֹנֶה מִסְפָּר לַכּוֹכָבִים. מִי הוּא שֶׁמּוֹנֶה אֶת הַכּוֹכָבִים? מִסְפָּר. מוֹנֶה מִסְפָּר לַכּוֹכָבִים. וְעַל יָדוֹ עוֹבְרִים כֻּלָּם בְּחֶשְׁבּוֹן. וְלֶעָתִיד לָבא, (ירמיה לג) עוֹד תַּעֲברְנָה הַצּאן עַל יְמֵי מוֹנֶה. וְלֹא יוֹדְעִים מִי הוּא. אֶלָּא מִשּׁוּם שֶׁבְּאוֹתוֹ זְמַן יִהְיֶה הַכֹּל בְּיִחוּד בְּלֹא פֵרוּד, הַכֹּל יִהְיֶה (והכל יהיה) מוֹנֶה אֶחָד.</p>\n<p>קוּם זָקֵן, הִתְעוֹרֵר וְהִתְגַּבֵּר בְּכֹחֲךְ וְשׁוּט בַּיָּם. פָּתַח וְאָמַר, (במדבר כג) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר לְהַחֲיוֹת מֵתִים - אֵלּוּ שֶׁחָזְרוּ בְגִלְגּוּל שְׁנֵי גוּפִים בְּרוּחַ אַחַת, שְׁנֵי אָבוֹת, שְׁתֵּי אִמָּהוֹת, כַּמָּה גִלְגּוּלִים מִתְגַּלְגְּלִים עַל יְדֵי זֶה, אַף עַל גַּב שֶׁנִּתְבָּאֵר, וְכָךְ הוּא. אֲבָל מִי מָנָה עֲפַר יַעֲקֹב, וְהוּא יְתַקֵּן הַכֹּל, וְלֹא יאבַד כְּלוּם, וְהַכֹּל יָקוּם.</p>\n<p>וַהֲרֵי נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. אַדְמַת עָפָר אֵלֶּה, כְּמוֹ שֶׁנֶּאֱמַר בְּסִפְרוֹ שֶׁל חֲנוֹךְ, כְּשֶׁהַחֲבֵרִים הִסְתַּכְּלוּ בְּאוֹתָן אוֹתִיּוֹת (שטסות) בָּאֲוִיר בּוֹ, וְהֵם אע\"ד פמת\"ר, הַיְנוּ אַדְמַ\"ת עָפָ\"ר.</p>\n<p>הַיְנוּ (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ. אַדְמַת עָפָר הֵן אוֹתִיּוֹת, וְקוֹל מִתְעוֹרֵר וּמוֹדִיעַ וְכָךְ אוֹמֵר בַּבִּנְיָן הַשֵּׁנִי. עָפָר - עָפָר רִאשׁוֹן. אַדְמַת - שֵׁנִי. שֶׁהִתְתַּקֵּן הָעִקָּר הָרִאשׁוֹן פְּסֹלֶת אֵלָיו.</p>\n<p>אַדְמַת עָפָר - כֻּלָּם - יָקִיצוּ, אֵלֶּה שֶׁהִתְתַּקְּנוּ לְחַיֵּי עוֹלָם. (יקיצו, כמו שגאמר בספרו של חנוך. חברים הסתכלו באלו האותיות אדמ\"ת עפ\"ר (והן אע\"ד פמת\"ר) אותן אותיות טסות באויר, וקול מתעורר ומודיע (וּמכריז) הקיצו ורגנו שכני עפר, וזהו בנין שני שגתקן. וכך אמר בספרו של חנוך, ' בנין שני עפר שגתקן. ראשון אדמת. ואותו ראשון פסלת לגבי שני שגתקן. ואלו ישני אדמת עפר כלם יקיצו אלה שגתקנו לחיי עולם) מִי זֶה עוֹלָם? זֶהוּ עוֹלָם שֶׁלְּמַטָּה, שֶׁהֲרֵי לֹא זָכוּ לִהְיוֹת בָּעוֹלָם שֶׁלְּמַעְלָה. וְאֵלֶּה שֶׁלֹּא זָכוּ - לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. מַה זֶּה לַחֲרָפוֹת? מִשּׁוּם שֶׁצַּד הָאַחֵר יַעֲבֹר מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁאִיר אֶת אֵלֶּה שֶׁהָיוּ מִנְּבִיעַת אוֹתוֹ הַצַּד לְהַתְמִיהַּ בָּהֶם אֶת כָּל בְּנֵי הָעוֹלָם.</p>\n<p>מִי גָרַם כָּל זֶה? אוֹתוֹ שֶׁלֹּא רָצָה לְהִתְרַבּוֹת בָּעוֹלָם וְלֹא רָצָה לְקַיֵּם (בדרגה של אותו נהר שהוא) בְּרִית הַקֹּדֶשׁ, וְלָכֵן גָּרַם כָּל מַה שֶּׁגָּרַם וְכָל הַגִּלְגּוּלִים הַלָּלוּ שֶׁאָמַרְנוּ עָלֶיהָ עַד כָּאן. (וזהו) עַד כָּאן זָקֵן. שָׁתַק רֶגַע אֶחָד, וְהַחֲבֵרִים הָיוּ תְּמֵהִים, וְלֹא הָיוּ יוֹדְעִים אִם הָיָה יוֹם אִם הָיָה לַיְלָה, אִם עוֹמְדִים שָׁם אִם לֹא עוֹמְדִים.</p>\n<p>פָּתַח אוֹתוֹ זָקֵן וְאָמַר, כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית וְגוֹ'. פָּסוּק זֶה מוֹכִיחַ עַל כָּל מַה שֶּׁנִּתְבָּאֵר. בּא וּרְאֵה, כָּל זָכָר עוֹמֵד בִּדְיוֹקָן בְּעוֹלַם הַזָּכָר, וְכָל נְקֵבָה עוֹמֶדֶת בִּדְיוֹקָן בְּעוֹלַם הַנְּקֵבָה. בְּעוֹד שֶׁהוּא עֶבֶד שֶׁנִּדְבָּק בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָן שֵׁשׁ שָׁנִים קַדְמוֹנִיּוֹת, וְאִם עָקַר עַצְמוֹ מֵעֲבוֹדָתוֹ, יַעֲקֹר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן שֵׁשׁ שָׁנִים שֶׁל עוֹלַם הַזָּכָר, וְיִמָסֵר לְאָדָם שֶׁהוּא מִשִּׁשָּׁה צְדָדִים, יַעֲבֹד לוֹ שֵׁשׁ שָׁנִים, וְיֵעָקֵר מִשֵּׁשׁ שָׁנִים (קדמוניות) שֶׁלְּמַעְלָה.</p>\n<p>אַחַר כָּךְ יוֹרֵד מִשָּׁם וְנִמְסָר לְעוֹלַם הַנְּקֵבָה. הוּא לֹא רָצָה לַעֲמֹד (בעולם) בַּזָּכָר - יוֹרֵד וְעוֹמֵד בַּנְּקֵבָה. בָּאָה הַנְּקֵבָה, שֶׁהִיא שְׁבִיעִית, וְנוֹטֶלֶת אוֹתוֹ. הֲרֵי מִכָּאן וָהָלְאָה הוּא מֵעוֹלַם הַנְּקֵבָה.</p>\n<p>לֹא רָצָה לַעֲמֹד בָּהּ וּבַגְּאֻלָּה שֶׁלָּהּ - יוֹרֵד לְמַטָּה וְנִדְבָּק לְמַטָּה וְנֶאֱחָז בַּצַּד הָאַחֵר. מִכָּאן וָהָלְאָה נֶעֱקָר מֵעוֹלַם הַזָּכָר וּמֵעוֹלַם הַנְּקֵבָה. הֲרֵי נֶאֱחָז בְּאוֹתָם עֲבָדִים שֶׁהֵם מִצַּד הָאַחֵר.</p>\n<p>עַכְשָׁו, כֵּיוָן שֶׁכָּךְ הוּא, הִצְטָרֵךְ פְּגָם וְלַעֲשׂוֹת בּוֹ רֹשֶׁם שֶׁל פְּגָם, שֶׁהֲרֵי כָּל פְּגָם הוּא שֶׁל צַד הָאַחֵר, וּמִיּוֹבֵל וָהָלְאָה חוֹזֵר לְגִלְגּוּל, וְשָׁב לָעוֹלָם כְּמִקֹּדֶם, (אם זוכה ומתקן עצמו, נדבק) וְנִדְבָּק בְּאוֹתוֹ עוֹלַם הַנְּקֵבָה וְלֹא יוֹתֵר. זָכָה - עוֹשֶׂה תוֹלָדוֹת בְּעוֹלַם הַנְּקֵבָה, וְכֻלָּם סוֹד הַכָּתוּב (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ מוּבָאוֹת לָךְ. וְאַשְׁרָיו כְּשֶׁמִּתְתַּקֵּן וְזוֹכֶה לְכָךְ.</p>\n<p>וְאִם לֹא זָכָה אֲפִלּוּ בְּגִלְגּוּל הַיּוֹבֵל, הֲרֵי הוּא כְּלֹא הָיָה, שֶׁחָזַר וְלֹא הִשְׁלִים יָמָיו לְהִנָּשֵׂא בָּעוֹלָם וְלַעֲשׂוֹת תּוֹלָדוֹת. מַה כָּתוּב? אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא. אִם יְחִידִי יִכָּנֵס לְאוֹתוֹ הָעוֹלָם בְּלִי תוֹלָדוֹת וְלֹא רָצָה לְהִשְׁתַּדֵּל בְּכָךְ, וְיָצָא מֵהָעוֹלָם הַזֶּה יְחִידִי בְּלִי זֶרַע - הוֹלֵךְ כְּמוֹ אֶבֶן בְּכַף הַקֶּלַע עַד אוֹתוֹ מָקוֹם שֶׁל הַסֶּלַע הֶחָזָק, וְנִכְנָס לְשָׁם, וּמִיָּד נוֹשֶׁבֶת רוּחַ שֶׁל אוֹתוֹ יָחִיד שֶׁנֶּעֱזַב מִנְּקֵבָתוֹ, וְהוֹלֵךְ יְחִידִי כְּנָחָשׁ שֶׁלֹּא מִתְחַבֵּר עִם אַחֵר בַּדֶּרֶךְ, וְנוֹשֵׁב בּוֹ.</p>\n<p>וּמִיָּד יוֹצֵא מִתּוֹךְ אוֹתוֹ מָקוֹם שֶׁל הַסֶּלַע הֶחָזָק הוּא לְבַדּוֹ, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם עַד שֶׁמּוֹצֵא גוֹאֵל לַהֲשִׁיבוֹ. וְהַיְנוּ אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא, זֶה שֶׁלֹּא רָצָה לָשֵׂאת שֶׁיִּהְיוּ לוֹ תוֹלָדוֹת.</p>\n<p>אֲבָל אִם בַּעַל אִשָּׁה הוּא, שֶׁנָּשָׂא וְהִשְׁתַּדֵּל בְּאִשְׁתּוֹ וְלֹא יָכֹל - הַהוּא לֹא מְגֹרָשׁ כְּאוֹתוֹ אַחֵר, לֹא יִכָּנֵס יְחִידִי וְלֹא יֵצֵא יְחִידִי. אֶלָּא אִם בַּעַל אִשָּׁה הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְקַפֵּחַ שְׂכַר כָּל בְּרִיּוֹתָיו, אַף עַל גַּב שֶׁלֹּא זָכוּ לְבָנִים, מַה כָּתוּב? וְיָצְאָה אִשְׁתּוֹ עִמּוֹ. וּשְׁנֵיהֶם בָּאִים בְּגִלְגּוּל וְזוֹכִים לְהִתְחַבֵּר כְּאֶחָד כְּמִקֹּדֶם. וְזֶה לֹא נָשָׂא אִשָּׁה שֶׁל גֵּרוּשִׁין, אֶלָּא אוֹתָהּ שֶׁהִשְׁתַּדֵּל בָּהּ בַּהַתְחָלָה וְלֹא זָכוּ - כָּעֵת יִזְכּוּ כְּאֶחָד אִם יְתַקְנוּ מַעֲשֵׂיהֶם, וְעַל זֶה וְיָצְאָה אִשְׁתּוֹ עִמּוֹ.</p>\n<p>אִם אֲדנָיו יִתֶּן לוֹ אִשָּׁה וְגוֹ'. (עתה) חוֹזֵר הַכָּתוּב לִדְבָרִים אֲחֵרִים (לדבר הראשון), לְאוֹתוֹ שֶׁיָּצָא יְחִידִי בְּלִי נְקֵבָה כְּלָל, וְיִגְאַל אוֹתוֹ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא שְׁבִיעִית, וְאוֹתָהּ שְׁבִיעִית נִקְרֵאת אֲדנָיו, הוּא אֲדוֹן כָּל הָאָרֶץ. אִם אֲדנָיו - זֶה חָס עָלָיו וּמֵשִׁיב אוֹתוֹ לָעוֹלָם הַזֶּה יְחִידִי כְּמוֹ שֶׁהָיָה, וְנוֹתֵן לוֹ אִשָּׁה, אוֹתָהּ שֶׁמִּזְבֵּחַ הוֹרִיד עָלֶיהָ דְּמָעוֹת, וּמִתְחַבְּרִים כְּאֶחָד. וְיָלְדָה לּוֹ בָנִים אוֹ בָנוֹת הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדנֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר.</p>\n<p>שֶׁהֲרֵי אִם שָׁב וְהִתְקִין אוֹתוֹ מָקוֹם שֶׁפָּגַם בְּחַיָּיו, מִתְקַבֵּל לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, נוֹטֵל אוֹתוֹ וּמְתַקְּנוֹ עַל תִּקּוּנוֹ אַחַר כָּךְ. וְזֶה נִקְרָא בַּעַל תְּשׁוּבָה, שֶׁהֲרֵי יָרַשׁ אֶת מוֹשָׁבוֹ שֶׁל אוֹתוֹ הַמָּקוֹם שֶׁל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וּמְתַקֵּן אֶת עַצְמוֹ מִמַּה שֶּׁהָיָה בַּתְּחִלָּה. (אותו מקום שגפגם ומתקן אותו על תקונו בחייו, מתקבל לפני המלך הקדוש ולוקח אותו אחר כך, וזה נקרא בעל תשובה, שהרי תקן עצמו ממה שהיה בתחלה) כֵּיוָן שֶׁנִּתְקַן וְשָׁב בִּתְשׁוּבָה, הֲרֵי עָלָה עַל תִּקּוּנוֹ. שֶׁאֵין דָּבָר בָּעוֹלָם וְאֵין מַפְתֵּחַ בָּעוֹלָם שֶׁלֹּא שׁוֹבֵר אוֹתוֹ שֶׁשָּׁב בִּתְשׁוּבָה.</p>\n<p>מַה זֶּה יֵצֵא בְגַפּוֹ? הֲרֵי נִתְבָּאֵר. אֲבָל עוֹד סוֹד יֵשׁ בּוֹ, יֵצֵא בְּגַפּוֹ - כְּמוֹ שֶׁנֶּאֱמַר (משלי ט) עַל גַּפֵּי מְרֹמֵי קָרֶת. מַה לְּשָׁם עִלּוּי וְהִתְעַלּוּת, אַף כָּאן עִלּוּי וְהִתְעַלּוּת. מָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹלִים, אֲפִלּוּ צַדִּיקִים גְּמוּרִים לֹא יְכוֹלִים לַעֲמֹד שָׁם. וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁשָּׁב בִּתְשׁוּבָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתוֹ וַדַּאי מִיָּד.</p>\n<p>שָׁנִינוּ, אֵין דָּבָר בָּעוֹלָם שֶׁעוֹמֵד לִפְנֵי הַתְּשׁוּבָה, וְאֶת הַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל וַדַּאי. וְאִם שָׁב בִּתְשׁוּבָה, הֲרֵי מְזֻמָּן כְּנֶגְדּוֹ אֹרַח חַיִּים. וְאַף עַל גַּב שֶׁפָּגַם מַה שֶּׁפָּגַם - הַכֹּל נִתְקָן וְהַכֹּל חוֹזֵר עַל תִּקּוּנוֹ, שֶׁהֲרֵי אֲפִלּוּ בְּמַה שֶּׁיֵּשׁ בּוֹ שְׁבוּעָה, (לפני הקדוש ברוך הוא נקרא בו כי ה' צבאות יעץ ומי יפר. זהו סוד סתום. ועוד, כאשר הקדושברוך הוא נשבע שבועה, לא נשבע אלא אם לא יעשה תשובה, שהרי אין דבר שעומד בפני התשובה, ועל הכל מכפר הקדוש ברוך הוא כאשר עושים תשובה שלמה) הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל, שֶׁכָּתוּב חַי אֲנִי נְאֻם ה' כִּי אִם יִהְיֶה כָּנְיָהוּ וְגוֹ'. וְכָתוּב כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי וְגוֹ'. וְאַחַר שֶׁשָּׁב בִּתְשׁוּבָה כָּתוּב, וּבְנֵי יְכָנְיָה אַסִּר בְּנוֹ וְגוֹ'. מִכָּאן שֶׁתְּשׁוּבָה מְשַׁבֶּרֶת כַּמָּה גְזֵרת וְדִינִים וְכַמָּה שַׁלְשְׁלָאוֹת בַּרְזֶל, וְאֵין מִי שֶׁעוֹמֵד לִפְנֵי הַתְּשׁוּבָה.</p>\n<p>וְעַל זֶה כָּתוּב, (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי. אֲשֶׁר פָּשְׁעוּ בִּי לֹא כָתוּב, אֶלָּא הַפֹּשְׁעִים בִּי. שֶׁלֹּא רוֹצִים לָשׁוּב וּלְהִתְנַחֵם עַל מַה שֶּׁעָשׂוּ. אֲבָל כֵּיוָן שֶׁהִתְנַחֲמוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתָם.</p>\n<p>לָכֵן הָאָדָם הַזֶּה, אַף עַל גַּב שֶׁפָּשַׁע בּוֹ וּפָגַם בְּמָקוֹם שֶׁלֹּא צָרִיךְ וְשָׁב לְפָנָיו - מְקַבֵּל אוֹתוֹ וְחָס עָלָיו, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מָלֵא רַחֲמִים, וּמִתְמַלֵּא רַחֲמִים עַל כָּל מַעֲשָׂיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו. אֲפִלּוּ עַל בְּהֵמוֹת וְעוֹפוֹת מַגִּיעִים רַחֲמָיו. אִם עֲלֵיהֶם מַגִּיעִים רַחֲמָיו, כָּל שֶׁכֵּן עַל בְּנֵי אָדָם שֶׁיּוֹדְעִים וּמַכִּירִים לְשַׁבֵּחַ רִבּוֹנָם שֶׁרַחֲמָיו מַגִּיעִים עֲלֵיהֶם וְשׁוֹרִים עֲלֵיהֶם. וְעַל זֶה אָמַר דָּוִד, (שם קיט) רַחֲמֶיךְ רַבִּים ה' כְּמִשְׁפָּטֶיךְ חַיֵּנִי.</p>\n<p>אִם עַל רְשָׁעִים מַגִּיעִים רַחֲמָיו, כָּל שֶׁכֵּן עַל צַדִּיקִים. אֶלָּא מִי צָרִיךְ רְפוּאָה? אוֹתָם בַּעֲלֵי כְאֵבִים. וּמִי הֵם בַּעֲלֵי כְאֵבִים? אֵלֶּה אוֹתָם רְשָׁעִים, הֵם צְרִיכִים רְפוּאָה וְרַחֲמִים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא (מרחם) עֲלֵיהֶם שֶׁלֹּא יִהְיוּ עֲזוּבִים מִמֶּנּוּ, וְהוּא - שֶׁלֹּא מִסְתַּלּק מֵהֶם, וְיָשׁוּבוּ כְנֶגְדּוֹ. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב, הוּא מְקָרֵב בַּיָּמִין. וּכְשֶׁדּוֹחֶה, דּוֹחֶה בַּשְּׂמֹאל. וּבְשָׁעָה שֶׁדּוֹחֶה, הַיָּמִין מְקָרֶבֶת. מִצַּד הַזֶּה דּוֹחֶה וּמֵהַצַּד הַזֶּה מְקָרֵב, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹזֵב אֶת רַחֲמָיו מֵהֶם.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (ישעיה נז) וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶךְ לִבּוֹ. וְכָתוּב אַחֲרָיו, דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְאַנְחֵהוּ וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַיֵּלֶךְ שׁוֹבָב, אַף עַל גַּב שֶׁהָרְשָׁעִים עוֹשִׂים כָּל מַה שֶּׁעוֹשִׂים בְּזָדוֹן, שֶׁהוֹלְכִים בְּדֶרֶךְ לִבָּם, וַאֲחֵרִים עוֹשִׂים בָּהֶם הַתְרָאָה וְלֹא רוֹצִים לְצַיֵּת לָהֶם - בְּשָׁעָה שֶׁשָּׁבִים בִּתְשׁוּבָה וְנוֹטְלִים דֶּרֶךְ טוֹבָה שֶׁל תְּשׁוּבָה, הֲרֵי הָרְפוּאָה מְזֻמֶּנֶת כְּנֶגְדָּם.</p>\n<p>עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, אִם עַל הַחַיִּים אוֹמֵר הַכָּתוּב, אוֹ שֶׁעַל הַמֵּתִים אוֹמֵר הַכָּתוּב, שֶׁהֲרֵי רֹאשׁ הַפָּסוּק אֵינוֹ סוֹף, וְהַסּוֹף אֵינוֹ רֹאשׁ - רֹאשׁ הַכָּתוּב מַרְאֶה עַל הַחַיִּים, וְסוֹפוֹ מַרְאֶה עַל הַמֵּתִים. אֶלָּא שֶׁהַפָּסוּק (ראש הפסוק) אוֹמֵר, בְּעוֹד שֶׁהָאָדָם הוּא בְּחַיָּיו, וְכָךְ הוּא - וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶךְ לִבּוֹ, מִשּׁוּם שֶׁיֵּשׁ בּוֹ יֵצֶר הָרָע חָזָק וּמַחֲזִיק בּוֹ, וְלָכֵן הוֹלֵךְ שׁוֹבָב וְלֹא רוֹצֶה לָשׁוּב בִּתְשׁוּבָה.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא רוֹאֶה אֶת דְּרָכָיו שֶׁהוֹלְכִים בְּרַע בְּלִי תוֹעֶלֶת, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי צָרִיךְ לְהַחֲזִיק בְּיָדוֹ. זֶהוּ שֶׁכָּתוּב דְּרָכָיו רָאִיתִי (וארפאהו), שֶׁהוֹלְכִים בַּחֲשֵׁכָה, אֲנִי רוֹצֶה תֵת לוֹ רְפוּאָה. זֶהוּ שֶׁכָּתוּב וְאֶרְפָּאֵהוּ. הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס לְלִבּוֹ דֶּרֶךְ הַתְּשׁוּבָה שֶׁלּוֹ וּרְפוּאָה לְנִשְׁמָתוֹ. וְאַנְחֵהוּ, מַה זֶּה וְאַנְחֵהוּ? כְּמוֹ שֶׁנֶּאֱמַר (שמותלב) לֵךְ נְחֵה אֶת הָעָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג אוֹתוֹ בְּדֶרֶךְ יָשָׁר כְּמִי שֶׁמַּחֲזִיק בְּיָדוֹ שֶׁל אַחֵר וּמוֹצִיא אוֹתוֹ מִתּוֹךְ הַחֲשֵׁכָה.</p>\n<p>וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו, הֲרֵי נִרְאֶה שֶׁהוּא מֵת! (אלא) כֵּן הוּא וַדַּאי מֵת וְעוֹמֵד בַּחַיִּים. שֶׁהוֹאִיל (אלא שהיא הוא ועומדים בחיים, והואיל) וְהוּא רָשָׁע, נִקְרָא מֵת. מַה זֶּה וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה טוֹב עִם בְּנֵי אָדָם, שֶׁכֵּיוָן שֶׁנִּכְנָס מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, מַפְקִיד עִמּוֹ שְׁנֵי מַלְאָכִים שׁוֹמְרִים שֶׁשּׁוֹמְרִים אוֹתוֹ, אֶחָד מִימִינוֹ וְאֶחָד מִשְּׂמֹאלוֹ.</p>\n<p>כְּשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ יָשָׁר, הֵם שְׂמֵחִים בּוֹ וּמַחֲזִיקִים אוֹתוֹ בְּשִׂמְחָה, מַכְרִיזִים לְפָנָיו וְאוֹמְרִים: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ. וּכְשֶׁהוֹלֵךְ בְּדֶרֶךְ עָקֹם, הֵם מִתְאַבְּלִים עָלָיו וְעוֹבְרִים מִמֶּנּוּ. כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲזִיק בּוֹ וּמַנְהִיג אוֹתוֹ בְּדֶרֶךְ יְשָׁרָה, אָז כָּתוּב וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַאֲשַׁלֵּם נִחֻמִים לוֹ בַּתְּחִלָּה, שֶׁהוּא הִתְנַחֵם עַל מַה שֶּׁעָשָׂה בַּתְּחִלָּה וְעַל מַה שֶּׁעוֹשֶׂה עַכְשָׁו וְשָׁב בִּתְשׁוּבָה. וְאַחַר כָּךְ וְלַאֲבֵלָיו, אוֹתָם מַלְאָכִים שֶׁהָיוּ מִתְאַבְּלִים עָלָיו כְּשֶׁעָבְרוּ מִמֶּנּוּ, וְעַכְשָׁו שֶׁחָזְרוּ עִמּוֹ, הֲרֵי וַדַּאי נִחוּמִים לְכָל הַצְּדָדִים.</p>\n<p>וְעַכְשָׁו הוּא וַדַּאי חַי. חַי בְּכָל הַצְּדָדִים, אָחוּז בְּעֵץ הַחַיִּים. וְכֵיוָן שֶׁאָחוּז בְּעֵץ הַחַיִּים, אָז נִקְרָא בַּעַל תְּשׁוּבָה, שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת אַף כָּךְ תְּשׁוּבָה, וְהוּא נִקְרָא בַּעַל תְּשׁוּבָה. וְהָרִאשׁוֹנִים אָמְרוּ, בַּעַל תְּשׁוּבָה מַמָּשׁ. וְעַל זֶה אֲפִלּוּ צַדִּיקִים גְּמוּרִים אֵינָם יְכוֹלִים לַעֲמֹד בְּמָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹמְדִים.</p>\n<p>דָּוִד הַמֶּלֶךְ אָמַר, (תהלים נא) לְךְ לְבַדְּךְ חָטָאתִי וְהָרַע בְּעֵינֶיךְ עָשִׂיתִי וְגוֹ'. לְךְ לְבַדְּךְ, מַה זֶּה לְךְ לְבַדְּךְ? אֶלָּא מִשּׁוּם שֶׁיֵּשׁ חֲטָאִים שֶׁחוֹטֵא אָדָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְלִבְנֵי אָדָם, וְיֵשׁ חֲטָאִים שֶׁחָטָא לִבְנֵי אָדָם וְלֹא לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְיֵשׁ חֲטָאִים שֶׁחוֹטֵא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ וְלֹא לִבְנֵי אָדָם (אחרים). דָּוִד הַמֶּלֶךְ חָטָא לַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא לִבְנֵי אָדָם.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי חָטָא אוֹתוֹ הַחֵטְא שֶׁל בַּת שֶׁבַע, וְשָׁנִינוּ, מִי שֶׁבָּא עַל אִשָּׁה עֶרְוָה בִּרְצוֹנָה אָסַר אוֹתָהּ עַל בַּעְלָהּ, וְחָטָא לַחֲבֵרוֹ, וְחָטָא לַקָּדוֹשׁ-בָּרוּךְ-הוּא - לֹא כָּךְ הוּא. שֶׁהַהוּא שֶׁאַתָּה אוֹמֵר בְּהֶתֵּר הָיָה, וְדָוִד לָקַח אֶת שֶׁלּוֹ, וְגֵט הָיָה לָהּ מִבַּעְלָהּ טֶרֶם שֶׁיָּצָא לַקְּרָב, שֶׁכָּךְ הָיָה מִנְהָג שֶׁל כָּל יִשְׂרָאֵל שֶׁנּוֹתְנִים גֵּט זְמַן לְאִשְׁתּוֹ כָּל שֶׁיּוֹצֵא לַחַיִל, וְכָךְ עָשָׂה אוּרִיָּה לְבַת שֶׁבַע, וְאַחַר שֶׁעָבַר זְמַן וְהָיְתָה פְּטוּרָה לַכֹּל, לָקַח אוֹתָהּ דָּוִד, וּבְהֶתֵּר עָשָׂה כָּל מַה שֶּׁעָשָׂה.</p>\n<p>שֶׁאִלְמָלֵא לֹא כָּךְ וְזֶה הָיָה בְּאִסּוּר, לֹא הָיָה מַשְׁאִיר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָדוֹ. וְהַיְנוּ שֶׁכָּתוּב לְעֵדוּת, (שמואל ב יב) וַיְנַחֵם דָּוִד אֵת בַּת שֶׁבַע אִשְׁתּוֹ. עֵדוּת שֶׁאִשְׁתּוֹ הִיא, וַדַּאי אִשְׁתּוֹ, וּבַת זוּגוֹ הָיְתָה שֶׁהִזְדַּמְּנָה אֵלָיו מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם. (וסוד הדבר מלכות של מעלה שהוא נעשה רגל רביעית למרכבה העליונה, ונקראבתשבע, עלאבןאחתשבעהעינים) הֲרֵי עֵדוּת שֶׁלֹּא חָטָא דָוִד אֶת חֵטְא בַּת שֶׁבַע כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>וּמָה הַחֵטְא שֶׁחָטָא? (אלא) לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ וְלֹא לְאַחֵר. שֶׁהָרַג אֶת אוּרִיָּה בְּחֶרֶב בְּנֵי עַמּוֹן וְלֹא הָרַג אוֹתוֹ בְּשָׁעָה שֶׁאָמַר לוֹ וַאדנִי יוֹאָב, שֶׁהֲרֵי דָּוִד הָיָה רִבּוֹן עָלָיו (ועל יואב), וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב (שם כג) אֵלֶּה שְׁמוֹת הַגִּבֹּרִים אֲשֶׁר לְדָוִד, וְלֹא אֲשֶׁר לְיוֹאָב. וְלֹא הָרַג אוֹתוֹ בְּאוֹתָהּ שָׁעָה, וְהָרַג אוֹתוֹ בְּחֶרֶב בְּנֵי עַמּוֹן.</p>\n<p>וְהַכָּתוּב אוֹמֵר וְלֹא נִמְצָא אִתּוֹ דָּבָר, רַק בִּדְבַר אוּרִיָּה הַחִתִּי. רַק לְמַעֵט הוּא בָּא. בִּדְבַר אוּרִיָּה, וְלֹא בְּאוּרִיָּה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, וְאוֹתוֹ הָרַגְתָּ בְּחֶרֶב בְּנֵי עַמּוֹן. וְכָל חֶרֶב בְּנֵי עַמּוֹן הָיָה חָקוּק בּוֹ נָחָשׁ עָקֹם, דְּיוֹקָן שֶׁל דַּרְקוֹן, וְהוּא עֲבוֹדָה זָרָה שֶׁלָּהֶם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, נָתַתָּ כֹּחַ לְאוֹתוֹ שִׁקּוּץ. (שכיון שחרב בני עמון התגברה אותה שעה על אוריה, כמה חזק התחזק אותו נחש עקם) מִשּׁוּם שֶׁבְּשָׁעָה שֶׁהָרְגוּ בְּנֵי עַמּוֹן אֶת אוּרִיָּה, וְעִמּוֹ רַבִּים מִבְּנֵי יִשְׂרָאֵל, וְהִתְגַּבְּרָה בְּאוֹתָהּ שָׁעָה חֶרֶב בְּנֵי עַמּוֹן, כַּמָּה חֹזֶק הִתְחַזְּקָה אוֹתָהּ עֲבוֹדָה זָרָה שִׁקּוּץ.</p>\n<p>וְאִם תֹּאמַר שֶׁאוּרִיָּה לֹא הָיָה צַדִּיק, כֵּיוָן שֶׁכָּתוּב עָלָיו אוּרִיָּה הַחִתִּי - לֹא כָּךְ! צַדִּיק הוּא הָיָה, אֶלָּא שֶׁשֵּׁם מְקוֹמוֹ הָיָה חִתִּי, כְּמוֹ שֶׁנֶּאֱמַר וְיִפְתָּח הַגִּלְעָדִי, עַל שֵׁם מְקוֹמוֹ נִקְרָא כָּךְ.</p>\n<p>וְעַל זֶה בִּדְבַר אוּרִיָּה הַחִתִּי, שֶׁשִּׁקּוּץ בְּנֵי עַמּוֹן הִתְגַּבֵּר עַל מַחֲנֵה אֱלֹהִים, שֶׁמַּחֲנוֹת דָּוִד הָיוּ מַמָּשׁ דְּיוֹקָן שֶׁלְּמַעְלָה, וּבְאוֹתָהּ שָׁעָה שֶׁפָּגַם דָּוִד מַחֲנֶה זֶה, פָּגַם לְמַעְלָה מַחֲנֶה אַחֵר. וְעַל זֶה אָמַר דָּוִד, לְךְ לְבַדְּךְ חָטָאתִי. לְבַדְּךְ וְלֹא לְאַחֵר. שֶׁהוּא הָיָה אוֹתוֹ הַחֵטְא שֶׁחָטָא אֵלָיו. וְזֶהוּ בִּדְבַר אוּרִיָּה, וְזֶהוּ בְּחֶרֶב בְּנֵי עַמּוֹן.</p>\n<p>כָּתוּב, כִּי ה' עֵינָיו מְשּטְטוֹת בְּכָל הָאָרֶץ, אֵלּוּ הַנְּקֵבוֹת. וְכָתוּב, (זכריה ד) עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים, אֵלּוּ הַזְּכָרִים. וַהֲרֵי הֵם יְדוּעִים. דָּוִד אָמַר (תהלים נא) וְהָרַע בְּעֵינֶיךְ עָשִׂיתִי. בְּעֵינֶיךְ? לִפְנֵי עֵינֶיךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מַה זֶּה בְּעֵינֶיךְ? אָמַר דָּוִד, בְּאוֹתוֹ מָקוֹם שֶׁחָטָאתִי, בְּעֵינֶיךְ הָיָה. שֶׁהָיִיתִי יוֹדֵעַ שֶׁהֲרֵי עֵינֶיךְ הָיוּ זְמִינִים וְעוֹמְדִים לְפָנַי וְלֹא הֶחְשַׁבְתִּי אוֹתָם, הֲרֵי הַחֵטְא שֶׁחָטָאתִי וְעָשִׂיתִי, בְּאֵיזֶה מָקוֹם הָיָה? בְּעֵינֶיךְ.</p>\n<p>לְמַעַן תִּצְדַּק בְּדָבְרֶךְ תִּזְכֶּה בְשָׁפְטֶךְ, וְלֹא יִהְיֶה לִי פִּתְחוֹן פֶּה לוֹמַר לְפָנֶיךְ. בֹּא וּרְאֵה, כָּל אֻמָּן כְּשֶׁמְּדַבֵּר, הוּא מְדַבֵּר בְּאֻמָּנוּתוֹ. דָּוִד הָיָה בַּדְּחַן הַמֶּלֶךְ, וְאַף עַל גַּב שֶׁהָיָה בְצַעַר, כֵּיוָן שֶׁהָיָה לִפְנֵי הַמֶּלֶךְ, שָׁב לְבַדְּחָנוּתוֹ כְּמוֹ שֶׁהָיָה כְּדֵי לְבַדֵּחַ אֶת הַמֶּלֶךְ.</p>\n<p>אָמַר, רִבּוֹן הָעוֹלָם, אֲנִי אָמַרְתִּי (שם כז) בְּחָנֵנִי ה' וְנַסֵּנִי, וְאַתָּה אָמַרְתָּ שֶׁלֹּא אוּכַל לַעֲמֹד בְּנִסְיוֹנְךְ. הֲרֵי חָטָאתִי לְמַעַן תִּצְדַּק בְּדָבְרֶךְ וְיִהְיֶה דְבָרְךְ אֱמֶת, שֶׁאִלְמָלֵא לֹא חָטָאתִי, יִהְיֶה דְבָרִי אֱמֶת, וְיִהְיֶה דְבָרְךְ בְּרֵיקָנוּת. עַכְשָׁו שֶׁחָטָאתִי, כְּדֵי שֶׁיִּהְיֶה דְבָרְךְ אֱמֶת, נָתַתִּי מָקוֹם לְצַדֵּק דְּבָרֶיךְ, לָכֵן עָשִׂיתִי, לְמַעַן תִּצְדַּק בְּדָבְרֶךְ תִּזְכֶּה בְשָׁפְטֶךְ. חָזַר דָּוִד לְאֻמָּנוּתוֹ וְאָמַר תּוֹךְ צַעֲרוֹ דִּבְרֵי בַּדְּחָנוּת לַמֶּלֶךְ.</p>\n<p>שָׁנִינוּ, דָּוִד לֹא הָיָה רָאוּי לְאוֹתוֹ הַמַּעֲשֶׂה, שֶׁהֲרֵי הוּא אָמַר, (שם קט) וְלִבִּי חָלַל בְּקִרְבִּי (נקוד חלל, שכבר היה חלל בקרבי) כָּךְ הוּא. אֲבָל דָּוִד אָמַר, בַּלֵּב יֵשׁ שְׁנֵי הֵיכָלוֹת, בְּאֶחָד דָּם וּבְאֶחָד רוּחַ. אוֹתוֹ אֶחָד שֶׁמָּלֵא בְדָם, בּוֹ יֵשׁ דִּיּוּר לַיֵּצֶר הָרָע, וְלִבִּי לֹא כָּךְ, שֶׁהֲרֵי הוּא רֵיקָן, וְלֹא נָתַתִּי דִיּוּר לְדָם רַע לִשְׁכֹּן בּוֹ יֵצֶר הָרָע, וְלִבִּי הוּא וַדַּאי חָלָל בְּלִי דִיּוּר (דם) רַע, וְכֵיוָן שֶׁכָּךְ זֶה, לֹא רָאוּי דָּוִד לְאוֹתוֹ חֵטְא שֶׁחָטָא, אֶלָּא כְּדֵי לָתֵת פִּתְחוֹן פֶּה לָרְשָׁעִים, שֶׁיֹּאמְרוּ, דָּוִד הַמֶּלֶךְ חָטָא וְשָׁב בִּתְשׁוּבָה וּמָחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל שֶׁכֵּן לִשְׁאָר בְּנֵי אָדָם. וְעַל זֶה אָמַר (תהלים נא) אֲלַמְּדָה פֹשְׁעִים דְּרָכֶיךְ וְחַטָּאִים אֵלֶיךְ יָשׁוּבוּ.</p>\n<p>וְכָתוּב, (שמואל ב טו) וְדָוִד עֹלֶה בְמַעֲלֵה הַזֵּיתִים עֹלֶה וּבוֹכֶה וְרֹאשׁ לוֹ חָפוּי וְהוּא הֹלֵךְ יָחֵף. רֹאשׁ לוֹ חָפוּי וְיָחֵף לָמָּה? אֶלָּא הָיָה נָזוּף, עָשָׂה עַצְמוֹ נָזוּף לְקַבֵּל עֹנֶשׁ, וְהֵם הָיוּ רְחוֹקִים מִמֶּנּוּ אַרְבַּע אַמּוֹת. אַשְׁרֵי הָעֶבֶד שֶׁכָּךְ עוֹבֵד לְרַבּוֹ וּמוּדָע לְחֶטְאוֹ לָשׁוּבּ מִמֶּנּוּ בִּתְשׁוּבָה שְׁלֵמָה.</p>\n<p>בֹּא וּרְאֵה, יוֹתֵר הָיָה מַה שֶּׁעָשָׂה לוֹ שִׁמְעִי בֶּן גֵּרָא מִכָּל הַצָּרוֹת שֶׁעָבְרוּ עָלָיו עַד אוֹתוֹ הַיּוֹם, וְלֹא הֵשִׁיב דָּוִד כְּנֶגְדּוֹ דָבָר, שֶׁכָּךְ הָיָה רָאוּי לוֹ, וּבָזֶה הִתְכַּפְּרוּ חֲטָאָיו.</p>\n<p>עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, שִׁמְעִי הָיָה תַּלְמִיד חָכָם, וְחָכְמָה רַבָּה הָיְתָה בּוֹ, לָמָּה יָצָא לְדָוִד וְעָשָׂה לוֹ כָּל מַה שֶּׁעָשָׂה? אֶלָּא מִמָּקוֹם אַחֵר הָיָה הַדָּבָר, וְהִכְנִיס לוֹ בְּלִבּוֹ דָּבָר זֶה, וְכָל זֶה לְתוֹעַלְתּוֹ שֶׁל דָּוִד, שֶׁהֲרֵי מַה שֶּׁעָשָׂה לוֹ שִׁמְעִי, גָּרַם לוֹ לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה וְשָׁבַר לִבּוֹ בְּשֶׁבֶר רַב, וְשָׁפַךְ הַרְבֵּה דְמָעוֹת מִתּוֹךְ לִבּוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה אָמַר, כִּי ה' אָמַר לוֹ קַלֵּל. יָדַע שֶׁהֲרֵי מִמָּקוֹם עֶלְיוֹן יָרַד הַדָּבָר.</p>\n<p>שְׁנֵי צִוּוּיִים צִוָּה דָוִד אֶת שְׁלֹמֹה בְּנוֹ - אֶחָד שֶׁל יוֹאָב, וְאֶחָד שֶׁל שִׁמְעִי, עִם שְׁאָר הַצִּוּוּיִים שֶׁצִּוָּה אוֹתוֹ. שֶׁל יוֹאָב - שֶׁכָּתוּב (מלכים א ב) וְגַם אַתָּה יָדַעְתָּ אֵת עָשָׂה לִי יוֹאָב בֶּן צְרוּיָה. דָּבָר נִסְתָּר הָיָה, שֶׁהֲרֵי אֲפִלּוּ שְׁלֹמֹה לֹא הָיָה לוֹ לָדַעַת. אֶלָּא מִשּׁוּם שֶׁאֲחֵרִים יָדְעוּ (אותו), זֶה הִתְגַּלָּה לִשְׁלֹמֹה. וְעַל זֶה אָמַר, וְאַתָּה יָדַעְתָּ וְגוֹ', מַה שֶּׁלֹּא רָאוּי לְךְ לָדַעַת.</p>\n<p>שֶׁל שִׁמְעִי - שֶׁכָּתוּב וְהִנֵּה עִמְּךְ שִׁמְעִי בֶן גֵּרָא. מַה זֶּה וְהִנֵּה עִמְּךְ? מְזֻמָּן הוּא עִמְּךְ תָּמִיד, רַבּוֹ הָיָה, וּמִשּׁוּם כָּךְ לֹא אָמַר לוֹ עַל יוֹאָב וְהִנֵּה עִמְּךְ יוֹאָב. אֲבָל שִׁמְעִי זֶה שֶׁנִּמְצָא תָמִיד עִמּוֹ, אָמַר וְהִנֵּה עִמְּךְ.</p>\n<p>וַיִּשְׁלַח הַמֶּלֶךְ וַיִּקְרָא לְשִׁמְעִי וַיֹּאמֶר בְּנֵה לְךְ בַיִת בִּירוּשָׁ לם. אֵיפֹה הִיא חָכְמָתוֹ שֶׁל שְׁלֹמֹה בָּזֶה? אֶלָּא הַכֹּל עָשָׂה בְחָכְמָה, וּלְכָל הַצְּדָדִים הוּא הִתְבּוֹנֵן. שֶׁהֲרֵי שִׁמְעִי הָיָה חָכָם, וְאָמַר שְׁלֹמֹה, אֲנִי רוֹצֶה שֶׁתִּגְדַּל תּוֹרָה עַל יְדֵי שִׁמְעִי וְלֹא יֵצֵא הַחוּצָה.</p>\n<p>עוֹד דָּבָר אַחֵר הִשְׁגִּיחַ שְׁלֹמֹה בְּחָכְמָה, שֶׁכָּתוּב (שמואל ב טז) יֹצֵא יָצוֹא וּמְקַלֵּל. מַה זֶּה יצֵא יָצוֹא פַּעֲמַיִם? מַסְפִּיק וַיֵּצֵא וַיְקַלֵּל (לו). אֶלָּא יְצִיאָה אַחַת - שֶׁיָּצָא מִבֵּית מִדְרָשׁוֹ לְדָוִד, וִיצִיאָה אַחַת - שֶׁיָּצָא מִירוּשָׁלַיִם אֶל עַבְדּוֹ שֶׁמֵּת עָלָיו. יְצִיאָה אַחַת לַמֶּלֶךְ, וִיצִיאָה שְׁנִיָּה לָעֲבָדִים. וְכָל זֶה רָאָה שְׁלֹמֹה וְהִשְׁגִּיחַ בְּרוּחַ הַקֹּדֶשׁ אוֹתָהּ הַיְצִיאָה הַשְּׁנִיָּה, וְעַל זֶה אָמַר וְהָיָה בְּיוֹם צֵאתְךְ. יָדַע שֶׁבִּיצִיאָה יָמוּת.</p>\n<p>וְעִפַּר בֶּעָפָר מַהוּ? אָמַר שְׁלֹמֹה, אֶל אָבִי זֶה הָיָה בֶּעָפָר, אֶל שִׁמְעִי זֶה יִהְיֶה בְּמַיִם, שֶׁכָּתוּב וְהָיָה בְּיוֹם צֵאתְךְ וְעָבַרְתָּ אֶת נַחַל קִדְרוֹן. שָׁם עָפָר וְכָאן מַיִם. שְׁנֵיהֶם דָּן שְׁלֹמֹה, לִהְיוֹת עָפָר וּמַיִם כְּמוֹ סוֹטָה, לְמִי שֶׁהִסְטִין דַּרְכּוֹ לְאָבִיו.</p>\n<p>כָּתוּב וְהוּא קִלְלַנִי קְלָלָה נִמְרֶצֶת. וְכָתוּב וָאֶשָּׁבַע לוֹ בַה' לֵאמֹר אִם אֲמִיתְךְ בֶּחָרֶב. וְכִי שִׁמְעִי הָיָה טִפֵּשׁ? שֶׁאִלּוּ כָּךְ הִשְׁבִּיעַ אוֹתוֹ, שֶׁלֹּא יֹאמַר בַּחֶרֶב לֹא, אֲבָל בַּחֲנִית אוֹ בְּחֵץ כֵּן.</p>\n<p>אֶלָּא שְׁנֵי דְבָרִים יֵשׁ כָּאן. אֶחָד אָמַר הַתִּינוֹק, בְּנוֹ שֶׁל הַדָּג הַגָּדוֹל, אוֹתוֹ שֶׁקַּשְׂקַשָּׂיו עוֹלִים לְרוּם הָעֲנָנִים. שְׁבוּעָתוֹ שֶׁל דָּוִד הַמֶּלֶךְ, כְּשֶׁהָיָה רוֹצֶה לְהִשָּׁבַע, הָיָה מוֹצִיא אֶת חַרְבּוֹ שֶׁשָּׁם הָיָה חָקוּק שֵׁם חָקוּק וְשָׁם נִשְׁבַּע. וְכָךְ עָשָׂה לְשִׁמְעִי, שֶׁכָּתוּב וָאֶשָּׁבַע לוֹ בַה' לֵאמֹר אִם אֲמִיתְךְ בֶּחָרֶב. בַּמָּה הָיְתָה הַשְּׁבוּעָה הַזּוֹ? בֶּחָרֶב. (בחרב הזו שהשם הקדוש חקק בה שבועה) בַּחֶרֶב נִשְׁבַּע. וְדָבָר אַחֵר דָּן שְׁלֹמֹה. אָמַר, בִּקְלָלָה בָּא אֶל אָבִי, בִּדְבָרִים - הֲרֵי דְּבָרִים אֵלָיו. וּבַשֵּׁם הַמְפֹרָשׁ הָרַג אוֹתוֹ וְלֹא בֶּחָרֶב. וְלָכֵן שְׁלֹמֹה עָשָׂה כָּךְ.</p>\n<p>עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, שֶׁכֵּיוָן שֶׁדָּוִד הִשְׁבִּיעַ אוֹתוֹ, לָמָּה הָרַג אוֹתוֹ, שֶׁנִּרְאֶה שֶׁשְּׁבוּעָה זוֹ הָיְתָה בַּעֲלִילָה, שֶׁהֲרֵי הַלֵּב וְהַפֶּה לֹא הָיוּ כְאֶחָד? אֶלָּא וַדַּאי דָּוִד לֹא הָרַג אוֹתוֹ, וַהֲרֵי יָדוּעַ, כָּל אֵיבְרֵי הַגּוּף מְקַבְּלִים הַכֹּל, וְהַלֵּב לֹא מְקַבֵּל אֲפִלּוּ כְּחוּט שֶׁל נִימָה שֶׁל שַׂעֲרָה. דָּוִד הַמֶּלֶךְ הָיָה הַלֵּב, וְקִבֵּל מַה שֶּׁלֹּא רָאוּי לוֹ לְקַבֵּל, וּמִשּׁוּם כָּךְ, וְיָדַעְתָּ אֵת אֲשֶׁר תַּעֲשֶׂה לּוֹ כָּתוּב. וְעוֹד, שֶׁהֲרֵי הָאִילָן גּוֹרֵם לִהְיוֹת נוֹטֵר וְנוֹקֵם כְּנָחָשׁ.</p>\n<p>כָּתוּב (תהלים נא) כִּי לֹא תַחְפֹּץ זֶבַח וְאֶתֵּנֶה עוֹלָה לֹא תִרְצֶה. זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. כִּי לֹא תַחְפֹּץ זֶבַח, וְכִי לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּקְרִיבוּ לְפָנָיו קָרְבָּן, וַהֲרֵי הוּא תִּקֵּן לָרְשָׁעִים קָרְבָּן שֶׁיַּקְרִיבוּ וְיִתְכַּפֵּר לָהֶם חֶטְאָם? אֶלָּא שֶׁדָּוִד אָמַר אֶת זֶה לַשֵּׁם אֱלֹהִים, וְקָרְבָּן לֹא מַקְרִיבִים לַשֵּׁם אֱלֹהִים, אֶלָּא לְשֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. שֶׁהֲרֵי לַדִּין הַקָּשֶׁה, מִדַּת הַדִּין, לֹא מַקְרִיבִים קָרְבָּן, שֶׁכָּתוּב (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. לַה', וְלֹא לְשֵׁם אֱלֹהִים. וְכִי תַקְרִיב קָרְבַּן מִנְחָה לַה'. זֶבַח תּוֹדָה לַה'. זֶבַח שְׁלָמִים לַה'.</p>\n<p>וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁדָּוִד הַמֶּלֶךְ אָמַר לֵאלֹהִים, הִצְטָרֵךְ לִכְתֹּב כִּי לֹא תַחְפֹּץ זֶבַח וְאֶתֵּנָה עוֹלָה לֹא תִרְצֶה. שֶׁהֲרֵי לַשֵּׁם הַזֶּה לֹא מַקְרִיבִים, אֶלָּא רוּחַ נִשְׁבָּרָה, שֶׁכָּתוּב זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. קָרְבָּן שֶׁל אֱלֹהִים הוּא עֶצֶב וְשִׁבְרוֹן לֵב. וּמִשּׁוּם כָּךְ, מִי שֶׁחָלַם חֲלוֹם רַע, צָרִיךְ לְהַרְאוֹת עַצְבוּת, שֶׁהֲרֵי בְּמִדַּת אֱלֹהִים (דין) עוֹמֵד, וְזֶבַח שֶׁל מִדַּת הַדִּין צָרִיךְ עַצְבוּת וְרוּחַ נִשְׁבָּרָה, וְאוֹתָהּ עַצְבוּת מְרַפֵּאת אֶת הַחֲלוֹם הָרָע, וְלֹא שׁוֹלֵט עָלָיו הַדִּין. שֶׁהֲרֵי הַזֶּבַח שֶׁרָאוּי לְמִדַּת הַדִּין, הִקְרִיב לְפָנֶיהָ.</p>\n<p>לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. מַה זֶּה לֹא תִבְזֶה? מִכְּלָל שֶׁיֵּשׁ לֵב שֶׁהוּא בּוֹזֶה? כֵּן. זֶהוּ לֵב שֶׁהוּא גֵאֶה, לֵב בְּגַסּוּת הָרוּחַ, הַיְנוּ לֵב בּוֹזֶה, אֲבָל לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה.</p>\n<p>הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. מַה זֶּה הֵיטִיבָה? נִרְאֶה שֶׁהֲרֵי טוֹב יֵשׁ בָּהּ, וְעַכְשָׁו הֵיטִיבָה עַל אוֹתוֹ הַטּוֹב?! וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי מִן הַיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּדֵּל בְּבִנְיַן בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה עַד עַכְשָׁו, אוֹתָהּ הֲטָבָה שֶׁל רָצוֹן לֹא שָׁרְתָה עַל אוֹתוֹ הַבִּנְיָן, וְעַל כֵּן לֹא נִתְקַן. שֶׁהֲרֵי בְּשָׁעָה שֶׁהָרָצוֹן הָעֶלְיוֹן יִתְעוֹרֵר, הוּא יֵיטִיב וְיַדְלִיק אֶת הַמְּנוֹרוֹת שֶׁל אוֹתוֹ הַבִּנְיָן וְאוֹתוֹ הַמַּעֲשֶׂה, שֶׁאֲפִלּוּ הַמַּלְאָכִים שֶׁל מַעְלָה לֹא יוּכְלוּ (לא) לְהִסְתַּכֵּל בְּאוֹתוֹ בֵּית מִקְדָּשׁ וְלֹא בְּאוֹתוֹ בִּנְיָן, וְאָז בֵּית הַמִּקְדָּשׁ וְכָל הַמַּעֲשֶׂה נִתְקָן.</p>\n<p>תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. וְכִי מִיּוֹם שֶׁהִשְׁתַּדֵּל בְּבִנְיַן בֵּית הַמִּקְדָּשׁ עַד עַכְשָׁו לֹא בָנָה אוֹתָם? (או) אִם חוֹמוֹת יְרוּשָׁלַיִם עַד עַכְשָׁו לֹא בָנָה - בֵּית הַמִּקְדָּשׁ עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא שֶׁכָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָם כְּמַעֲשֵׂי בֶּן אָדָם. כְּשֶׁבְּנֵי אָדָם בָּנוּ בֵּית הַמִּקְדָּשׁ לְמַטָּה, בַּהַתְחָלָה עָשׂוּ אֶת חוֹמוֹת הָעִיר, וּלְבַסּוֹף עָשׂוּ אֶת בֵּית הַמִּקְדָּשׁ. חוֹמוֹת הָעִיר בַּהַתְחָלָה כְּדֵי לְהָגֵן עֲלֵיהֶם, וְאַחַר כָּךְ בִּנְיַן הַבַּיִת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ, אֶלָּא בּוֹנֶה בַּתְּחִלָּה אֶת בֵּית הַמִּקְדָּשׁ, וּבַסּוֹף כְּשֶׁיּוֹרִיד אוֹתוֹ מִן הַשָּׁמַיִם וְיוֹשִׁיב אוֹתוֹ עַל מְקוֹמוֹ, אָז יִבְנֶה אֶת חוֹמוֹת יְרוּשָׁלַיִם, שֶׁהֵן חוֹמוֹת הָעִיר. וְעַל זֶה אָמַר דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם, (תהלים נא) הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן - בַּהַתְחָלָה, וְאַחַר כָּךְ תִּבְנֶה חוֹמוֹת יְרוּשָׁלם.</p>\n<p>כָּאן יֵשׁ סוֹד. כָּל הַמַּעֲשִׂים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּהַתְחָלָה מַקְדִּים אוֹתוֹ שֶׁלְּבַחוּץ, וְאַחַר הַמֹּחַ שֶׁלִּפְנִים, וְכָאן לֹא כָּךְ. בֹּא וּרְאֵה, כָּל אוֹתָם הַמַּעֲשִׂים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַקְדִּים אוֹתוֹ שֶׁל בַּחוּץ, הַמֹּחַ הִקְדִּים בְּמַחֲשָׁבָה, וּבְמַעֲשֶׂה אוֹתוֹ שֶׁל בַּחוּץ, שֶׁהֲרֵי כָּל קְלִפָּה הִיא מִצַּד הָאַחֵר, וְהַמֹּחַ מִן הַמֹּחַ, וְתָמִיד הַצַּד הָאַחֵר מַקְדִּים וְגָדֵל וּמִתְרַבֶּה וְשׁוֹמֵר הַפְּרִי. כֵּיוָן שֶׁמִּתְרַבֶּה, זוֹרְקִים אוֹתוֹ הַחוּצָה, וְיָכִין רָשָׁע וְצַדִּיק יִלְבַּשׁ, וְזוֹרְקִים אֶת אוֹתָהּ קְלִפָּה, וּמְבָרְכִים אֶת הַצַּדִּיק בָּעוֹלָם.</p>\n<p>אֲבָל כָּאן, בְּבִנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁהַצַּד הָרָע יַעֲבֹר מֵהָעוֹלָם - לֹא צָרִיךְ, שֶׁהֲרֵי הַמֹּחַ וְהַקְּלִפָּה שֶׁלּוֹ הָיָה. הִקְדִּים הַמֹּחַ, שֶׁכָּתוּב הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן - בַּהַתְחָלָה, וְאַחַר כָּךְ תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. אוֹתָהּ חוֹמָה הַחִיצוֹנִית, שֶׁהִיא קְלִפָּה, שֶׁלּוֹ הִיא מַמָּשׁ, שֶׁכָּתוּב (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב. אֲנִי וְלֹא הַצַּד הָרָע.</p>\n<p>יִשְׂרָאֵל הֵם הַמֹּחַ הָעֶלְיוֹן שֶׁל הָעוֹלָם. יִשְׂרָאֵל עָלוּ בַמַּחֲשָׁבָה בַּתְּחִלָּה. הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם קְלִפָּה, הִקְדִּימוּ, שֶׁכָּתוּב (בראשית לו) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקְדִּים אֶת הַמֹּחַ בְּלִי קְלִפָּה, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. הַמֹּחַ קוֹדֵם לַקְּלִפָּה. וְאַף עַל גַּב שֶׁהַמֹּחַ יַעֲמֹד בְּלִי קְלִפָּה, מִי הוּא שֶׁיּוֹשִׁיט יָד לֶאֱכֹל מִמֶּנּוּ? מִשּׁוּם שֶׁכָּל אֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבא אֲלֵיהֶם נְאֻם ה'.</p>\n<p>בְּאוֹתוֹ זְמַן, (תהלים נא) אָז תַּחְפֹּץ זִבְחֵי צֶדֶק. הֱיוֹת שֶׁהֲרֵי אָז יִתְחַבֵּר הַכֹּל בְּחִבּוּר אֶחָד, וְיִהְיֶה הַשֵּׁם שָׁלֵם בְּכָל תִּקּוּנוֹ, וְאָז הַקָּרְבָּן יִהְיֶה שָׁלֵם לַה' אֱלֹהִים. שֶׁעַכְשָׁו אֱלֹהִים לֹא מִתְחַבֵּר לַקָּרְבָּן, שֶׁאִלְמָלֵא הִתְחַבֵּר בּוֹ, כַּמָּה אֱלֹהִים יַעֲלוּ אָזְנַיִם לְהִתְחַבֵּר לְשָׁם. אֲבָל בְּאוֹתוֹ זְמַן, (שם פו) כִּי גָדוֹל אַתָּה וְעוֹשֵׂה נִפְלָאוֹת אַתָּה אֱלֹהִים לְבַדֶּךְ. וְאֵין אֱלֹהִים אַחֵר.</p>\n<p>וּבְאתוֹ זְמַן כָּתוּב, (דברים לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי. (ראועתה) רְאוּ כִּי אֲנִי אֲנִי הוּא גָּדוֹל, מַה זֶּה עַתָּה? אֶלָּא שֶׁלֹּא הָיָה קֹדֶם לָכֵן, וּבְאוֹתוֹ זְמַן זֶה יִהְיֶה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, עַתָּה רְאוּ מַה שֶּׁלֹּא יְכָלְתֶּם לִרְאוֹת מִקֹּדֶם לָכֵן.</p>\n<p>כִּי אֲנִי אֲנִי, לָמָּה פַּעֲמַיִם? אֶלָּא כְּדֵי לְדַיֵּק, שֶׁהֲרֵי אֵין שָׁם אֱלֹהִים, אֶלָּא הוּא. שֶׁהֲרֵי כַּמָּה פְעָמִים שֶׁנֶּאֱמַר אֲנִי פַּעַם אַחַת וְלֹא יוֹתֵר, וְהָיָה שָׁם הַצַּד הָאַחֵר. אֲבָל עַכְשָׁו אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, שֶׁהֲרֵי כָּל הַצַּד הָאַחֵר הָעֳבַר, וְדַוְקָא אֲנִי אֲנִי.</p>\n<p>אֲנִי אָמִית וַאֲחַיֶּה. עַד עַכְשָׁו הַמֹּחַ הָיָה מִן הַצַּד הָאַחֵר. מִכָּאן וָהָלְאָה, אֲנִי אָמִית וַאֲחַיֶּה. מִכָּאן שֶׁבְּאוֹתוֹ הַזְּמַן, כָּל אוֹתָם שֶׁלֹּא טָעֲמוּ טַעַם הַמָּוֶת - מִמֶּנּוּ יִהְיֶה לָהֶם מָוֶת, וְיָקִים אוֹתָם (מיד). לָמָּה? כְּדֵי שֶׁלֹּא תִשָּׁאֵר מֵאוֹתָהּ הַזֻּהֲמָה בָּעוֹלָם כְּלָל, וְיִהְיֶה עוֹלָם חָדָשׁ בְּמַעֲשֵׂי יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְאִם אָמֹר יֹאמַר וְגוֹ' לֹא אֵצֵא חָפְשִׁי, כְּמוֹ שֶׁנִּתְבָּאֵר, אָז פּוֹגֵם אוֹתוֹ בִּפְגָם. אִם בְּגַפּוֹ יָבא, מַה זֶּה בְּגַפּוֹ שָׁנִינוּ, כְּתַרְגּוּמוֹ - לְבַדּוֹ. יָפֶה הוּא. אֲבָל הֲרֵי שָׁנִינוּ, כָּל הָעוֹלָם לֹא עוֹמֵד אֶלָּא עַל סְנַפִּיר אֶחָד שֶׁל לִוְיָתָן.</p>\n<p>וְסוֹד זֶה, בְּשָׁעָה שֶׁעוֹמְדִים זָכָר וּנְקֵבָה, שֶׁזָּכָר וּנְקֵבָה בָּרָא אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל מַה שֶּׁהוֹלְכִים, הָעוֹלָם מִזְדַּעֲזֵעַ, וְאִלְמָלֵא שֶׁסֵּרַס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַזָּכָר וְצִנֵּן אֶת הַנְּקֵבָה, הָיוּ מַחֲרִיבִים אֶת הָעוֹלָם, וְעַל כָּךְ לֹא עוֹשִׂים תּוֹלָדוֹת. (ומישלאעושהתולדות בגפו) אִם בְּגַפּוֹ יָבֹא, תַּחַת אוֹתוֹ סְנַפִּיר שֶׁלֹּא עוֹשֶׂה תוֹלָדוֹת נִכְנָס. וְהוֹאִיל וְכֵן בְּגַפּוֹ יֵצֵא, לְשָׁם נִדְחֶה, וְלֹא נִכְנָס לַפַּרְגּוֹד כְּלָל, וְנִדְחֶה וְנִטְרָד מֵאוֹתוֹ הָעוֹלָם. בְּגַפּוֹ יֵצֵא, בְּגַפּוֹ יֵצֵא וַדַּאי.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (ויקרא כ) עֲרִירִים יָמֻתוּ. עֲרִירִים (כתוב) - כְּלָל שֶׁל זָכָר וּנְקֵבָה. בְּסוֹד שֶׁל זָכָר נִכְנָס, וּבְסוֹד שֶׁל נְקֵבָה יֵצֵא. נִכְנָס בָּזֶה וְיוֹצֵא בָּזֶה. וְזֶהוּ מָקוֹם שֶׁנִּדְבָּק בּוֹ בְּאוֹתוֹ הָעוֹלָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה שֶׁיִּכָּנֵס לְפָנָיו מִי שֶׁמְּסָרֵס עַצְמוֹ בָּעוֹלָם הַזֶּה.</p>\n<p>בֹּא וּרְאֵה מִן הַקָּרְבָּן, שֶׁלֹּא הָיוּ מַקְרִיבִים לְפָנָיו מְסֹרָס, וְהוֹצִיאוּ אוֹתוֹ שֶׁלֹּא יִקְרַב לְפָנָיו, וְצִוָּה וְאָמַר, (ויקרא כב) וּבְאַרְצְכֶם לֹא תַעֲשׂוּ. וְכֵן לְדוֹרֵי דוֹרוֹת אָסַר לְסָרֵס אֶת הַבְּרִיּוֹת שֶׁבְּרָאָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, שֶׁהֲרֵי כָּל סֵרוּס הוּא שֶׁל הַצַּד הָאַחֵר.</p>\n<p>וְאִם הוּא הִשְׁתַּדֵּל וְנָשָׂא אִשָּׁה וְלֹא עָשָׂה תוֹלָדוֹת וְלֹא רָצָה, וְאַף עַל גַּב שֶׁיֵּשׁ לוֹ אִשָּׁה, אוֹ שֶׁהִיא לֹא רָצְתָה, וְנִכְנָס לְאוֹתוֹ עוֹלָם בְּלִי תוֹלָדוֹת - מַה כָּתוּב? אִם בַּעַל אִשָּׁה הוּא, וְלֹא הִשְׁגִּיחוּ לְפֹעַל יְדֵי רִבּוֹנָם, וְיָצְאָה אִשְׁתּוֹ עִמּוֹ. הוּא יִכָּנֵס בְּגַפּוֹ שֶׁל זָכָר, וְהִיא בִּנְקֵבָה. בְּגַפּוֹ יָבא בְּגַפּוֹ יֵצֵא, כְּמוֹ שֶׁנִּתְבָּאֵר, הַכֹּל עַל תִּקּוּנוֹ.</p>\n<p>אִם אֲדנָיו יִתֶּן לוֹ אִשָּׁה, כְּמוֹ שֶׁנִּתְבָּאֵר. אִם אֲדנָיו - זֶה אֲדוֹן כָּל הָאָרֶץ. יִתֶּן לוֹ אִשָּׁה - מִכָּאן שֶׁלֹּא בִּרְשׁוּת הָאָדָם עוֹמֵד לָשֵׂאת אִשָּׁה, אֶלָּא (הכל (משלי טז) פלס ומאזני משפט לה') הַכֹּל בְּמֹאזְנַיִם לַעֲלוֹת. יִתֶּן לוֹ אִשָּׁה, שֶׁהֲרֵי זֶה לֹא בִּרְשׁוּתוֹ הוּא, וּמִי הִיא? הַהִיא שֶׁאֵינָהּ שֶׁלּוֹ וְלֹא הִזְדַּמְּנָה אֵלָיו, וּמִי הִיא? אוֹתָהּ שֶׁהָיְתָה מְזֻמֶּנֶת לְאַחֵר, וְהִקְדִּים זֶה בְּרַחֲמִים וְנָטַל אוֹתָהּ, זוֹ נִתְּנָה לוֹ, שֶׁלֹּא רְאוּיָה לוֹ.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה מֵרָחוֹק וְרוֹאֶה אֶת אוֹתָהּ אִשָּׁה שֶׁעֲתִידָה לְהוֹצִיא תוֹלָדוֹת בָּעוֹלָם, מַקְדִּים זֶה בְּרַחֲמִים וְנִתֶּנֶת לוֹ, וְעוֹשֶׂה פֵרוֹת, וְזוֹרֵעַ זֶרַע בְּאִשָּׁה (בגן) שֶׁאֵינָהּ שֶׁלּוֹ, מִשּׁוּם כָּךְ הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאֲדנֶיהָ, וְהוּא יֵצֵא בְגַפּוֹ. אֵי עָנִי מִסְכֵּן, כַּמָּה הִשְׁתַּדֵּל בְּרֵיקָנוּת, הִתְיַגַּע וְנִשְׁתַּדֵּל לַעֲשׂוֹת פֵּרוֹת בְּגַן שֶׁאֵינוֹ שֶׁלּוֹ, וְיָצָא בְרֵיקָנוּת.</p>\n<p>זָקֵן זָקֵן, בַּזְּמַנִּים (בענינים) הַלָּלוּ לֹא הָיִית בְּרַגְלֶיךְ דּוֹחֶה אֶת הַשַּׁעַר, כְּמִי שֶׁשּׁוֹכֵב בָּאָרֶץ בְּלִי כֹּחַ, שֶׁהֲרֵי נֶחֱלַשׁ, וּמֵחֻלְשָׁה רַבָּה, שֶׁלֹּא יָכוֹל דּוֹחֶה בְרַגְלָיו. הִתְחַזֵּק זָקֵן וְאַל תְּפַחֵד. הֶעָנִי הַמִּסְכֵּן הַזֶּה שֶׁהִשְׁתַּדֵּל לָרִיק, אֱמֹר לָמָּה? אִם מִשּׁוּם שֶׁזָּרַע בְּגַן אַחֵר שֶׁאֵינוֹ שֶׁלּוֹ - יָפֶה. אִם כָּךְ (אבלכאן) הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ אוֹתוֹ הַגָּן לִזְרֹעַ בּוֹ, שֶׁהֲרֵי לֹא הוּא שֶׁלָּקַח אוֹתָהּ.</p>\n<p>אֶלָּא בֹּא וּרְאֵה, כָּל הַדְּבָרִים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם הֵם בְּדִין, וְלֹא הָיָה דָבָר לָרִיק. זֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ אִשָּׁה וְעָשָׂה בָּהּ פֵּרוֹת וְגִדּוּלִים, אֵין זֶה כִּשְׁאָר בְּנֵי הַגִּלְגּוּל, וְלֹא דוֹמֶה מִי שֶׁמִּשְׁתַּדֵּל בָּעוֹלָם הַזֶּה לְהַגְדִּיל אֶת הָאִילָן (ולא יכול), לְמִי שֶׁלֹּא רוֹצֶה לְהַגְדִּיל וּלְהִשְׁתַּדֵּל, וְעוֹקֵר וּמַפִּיל אֶת הֶעָלִים שֶׁל הָאִילָן וּמַקְטִין הַפְּרִי שֶׁלּוֹ.</p>\n<p>זֶה שֶׁאֲדוֹנָיו נָתַן לוֹ אִשָּׁה כְּדֵי לַעֲשׂוֹת פֵּרוֹת, הֲרֵי הִשְׁתַּדֵּל בַּהַתְחָלָה כְּדֵי לְהַגְדִּיל אֶת הָאִילָן וְלֹא יָכֹל. זְכֻיּוֹת כָּל כָּךְ אֵין לוֹ, (של בנים גם כן אין לו) שֶׁאִם הָיָה צַדִּיק כָּרָאוּי, לֹא הָיָה שָׁב בְּגִלְגּוּל (כאבן בכף הקלע), שֶׁהֲרֵי כָּתוּב (ישעיה נו) וְנָתַתִּי לָכֶם בְּבֵיתִי וּבְחֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת. וְעַכְשָׁו שֶׁלֹּא זָכָה, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה שֶׁהֲרֵי הִשְׁתַּדֵּל וְלֹא יָכֹל. זֶה אֲדוֹנָיו יִתֶּן לוֹ אִשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר. וְכֵיוָן שֶׁחָס עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לוֹ בְּרַחֲמִים, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹבֶה מִשֶּׁלּוֹ בַּתְּחִלָּה, וְנוֹטֵל מַה שֶּׁגָּרַע אוֹתוֹ הַמַּעְיָן. וּמִשּׁוּם כָּךְ, הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדנֶיהָ, וְאַחַר כָּךְ יָשׁוּב וְיִשְׁתַּדֵּל עַל עַצְמוֹ לְהַשְׁלִים גִּרְעוֹנוֹ. עַד כָּאן סוֹד הַכָּתוּב.</p>\n<p>זָקֵן זָקֵן, אַתָּה אָמַרְתָּ עַל זֶה שֶׁלָּרִיק הִשְׁתַּדֵּל, וְלֹא הִשְׁגַּחְתָּ עָלֶיךְ שֶׁלָּרִיק אַתָּה הוֹלֵךְ בְּמַה שֶּׁאָמַרְתָּ, שֶׁהֲרֵי הַכָּתוּב רוֹדֵף אַחֲרֶיךְ, שֶׁסּוֹתֵר אֶת כָּל הַבִּנְיָן שֶׁבָּנִיתָ עַד עַכְשָׁו, וְאַתָּה חוֹשֵׁב שֶׁאַתָּה מֵשִׁיט אֶת הַיָּם לִרְצוֹנְךְ. וּמַהוּ? שֶׁכָּתוּב וְאִם אָמֹר יֹאמַר הָעֶבֶד אָהַבְתִּי אֶת אֲדנִי אֶת אִשְׁתִּי וְגוֹ'.</p>\n<p>אִי זָקֵן זָקֵן, עֲיֵף כֹּחַ, מַה תַּעֲשֶׂה? חָשַׁבְתָּ שֶׁלֹּא יִהְיֶה מִי שֶׁיִּרְדֹּף אַחֲרֶיךְ, הֲרֵי הַכָּתוּב הַזֶּה רוֹדֵף אַחֲרֶיךְ וְיוֹצֵא מֵאַחַר הַכֹּתֶל כְּאַיָּלָה בַּשָּׂדֶה, מְדַלֵּג דִּלּוּגִים אַחֲרֶיךְ, שְׁלֹשָׁה עָשָׂר דִּלּוּגִים דִּלֵּג אַחֲרֶיךְ וְהִשִּׂיג אוֹתְךְ. מַה תַּעֲשֶׂה, זָקֵן? עַכְשָׁו יֵשׁ לְךְ לְהִתְגַּבֵּר בְּכֹחֲךְ, שֶׁהֲרֵי גִּבּוֹר חָזָק הָיִיתָ עַד הַיּוֹם. זָקֵן זָקֵן, תִּהְיֶה זוֹכֵר אֶת יוֹם הַשֶּׁלֶג כְּשֶׁזָּרַעְנוּ פּוֹלִים, וְהָיוּ כַּמָּה גְבָרִים בְּנֵי חַיִל כְּנֶגְדְּךְ, וְאַתָּה לְבַדְּךְ נִצַּחְתָּ שְׁלֹשָׁה עָשָׂר גְּבָרִים חֲזָקִים בְּנֵי חַיִל, שֶׁכָּל אֶחָד מֵהֶם הוֹרֵג אַרְיֵה טֶרֶם שֶׁיֹּאכַל.</p>\n<p>אִם אֶת אוֹתָם שְׁלֹשָׁה עָשָׂר גְּבָרִים נִצַּחְתָּ - אֵלֶּה שְׁלֹשָׁה עָשָׂר שֶׁאֵין בָּהֶם כֹּחַ, אֶלָּא דְבָרִים, עַל אַחַת כַּמָּה וְכַמָּה. כָּתוּב אָמֹר יֹאמַר. אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא דַּרְכּוֹ לַעֲשׂוֹת דִּין לַכֹּל. כְּשֶׁמַּגִּיעַ זְמַנָּהּ שֶׁל הָאִשָּׁה הַזּוֹ לִמְצֹא אֶת בֶּן זוּגָהּ, מָה עוֹשֶׂה? הוֹרֵג אֶת זֶה, וְנוֹטֵל אוֹתָהּ אוֹתוֹ בֶּן זוּגָהּ, וְהוּא יוֹצֵא מִן הָעוֹלָם הַזֶּה לְבַדּוֹ יְחִידִי.</p>\n<p>וְאִם אָמֹר יֹאמַר, הֲרֵי בֵּאֲרוּ הַחֲבֵרִים כִּפְשַׁט הַכָּתוּב. וְאִם אָמֹר - בְּרֵאשִׁית שֶׁל שֵׁשׁ הַשָּׁנִים. יֹאמַר - בְּסוֹף שֵׁשׁ הַשָּׁנִים טֶרֶם תִּכָּנֵס הַשְּׁבִיעִית. שֶׁהֲרֵי אִם אָמַר כְּשֶׁהוּא אֲפִלּוּ בְּיוֹם אֶחָד מֵהַשְּׁבִיעִית - דְּבָרָיו בְּטֵלִים. מָה הַטַּעַם? כָּתוּב הָעֶבֶד, בְּעוֹד שֶׁהוּא עֶבֶד, בַּשָּׁנָה הַשִּׁשִּׁית. אָמַר בְּרֵאשִׁית שֶׁל שֵׁשׁ הַשָּׁנִים וְלֹא אָמַר בְּסוֹף שֵׁשׁ הַשָּׁנִים - אֵינוֹ כְלוּם. וּמִשּׁוּם כָּךְ פַּעֲמַיִם אָמֹר יֹאמַר.</p>\n<p>וְכָאן בְּעוֹד שֶׁהוּא בָּאִשָּׁה הַזּוֹ, מַרְבֶּה תְפִלּוֹת וּבַקָּשׁוֹת בְּכָל יוֹם לַמֶּלֶךְ הַקָּדוֹשׁ. כְּמוֹ שֶׁהָיָה הָרֵאשִׁית בְּרַחֲמִים, כָּךְ הוּא הַסּוֹף בְּרַחֲמִים. וְזֶהוּ אָמֹר יֹאמַר. אָמֹר - בַּתְּחִלָּה, כְּשֶׁהִקְדִּים בְּרַחֲמִים. יֹאמַר - בַּסּוֹף, וְיִתְקַבֵּל בְּרַחֲמִים. וּמַה יֹּאמַר? אָהַבְתִּי אֶת אֲדנִי. שֶׁבִּגְלַל זֶה וּבְרֹב הַתְּפִלּוֹת אוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. מְתַקֵּן מַעֲשָׂיו, וְאוֹמֵר אָהַבְתִּי אֶת אֲדֹנִי אֶת אִשְׁתִּי וְאֶת בָּנָי לֹא אֵצֵא חָפְשִׁי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתוֹ בְּאוֹתָהּ תְּשׁוּבָה וּבְאוֹתָן הַתְּפִלּוֹת הָרַבּוֹת.</p>\n<p>מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? מַה שֶּׁהָיָה מְזֻמָּן לְהַחֲזִירוֹ בְגִלְגּוּל וְלִסְבֹּל עֳנָשִׁים בָּעוֹלָם הַזֶּה עַל מַה שֶּׁעָשָׂה - לֹא מַחֲזִירוֹ לָעוֹלָם הַזֶּה. וּמָה עוֹשֶׂה? מְקָרֵב אוֹתוֹ לְבֵית דִּין שֶׁל יְשִׁיבַת הָרָקִיעַ, וְדָנִים אוֹתוֹ וּמוֹסְרִים אוֹתוֹ לְבֵית הַמַּלְקוּת, וְרוֹשֵׁם אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֵיךְ נִמְסָר לְבֵית הָעֹנֶשׁ, וּפוֹגֵם אוֹתוֹ לִהְיוֹת תַּחַת שִׁלְטוֹן הָעָרְלָה (ומצוה אותו להיות תחת שלטון היובל) עַד זְמַן יָדוּעַ, וְאַחַר כָּךְ גּוֹאֵל אוֹתוֹ.</p>\n<p>אִם בְּאוֹתוֹ זְמַן שֶׁעוֹשִׂים לוֹ פְּגָם, אִם הִגִּיעַ יוֹבֵל, אֲפִלּוּ יוֹם אֶחָד לַיּוֹבֵל - נֶחְשָׁב כְּמִי שֶׁמָּצָא זְמַן עַד הַיּוֹבֵל. כָּךְ נֶעֱנָשׁ וְלֹא יוֹתֵר. בָּא הַיּוֹבֵּל וְנִגְאָל, וּמַכְנִיסִים אוֹתוֹ לְתוֹךְ הַפַּרְגּוֹד. עַד כָּאן. הִסְתִּיר אוֹתוֹ זָקֵן אֶת עֵינָיו רֶגַע אֶחָד.</p>\n<p>פָּתַח וְאָמַר, (מיכה ו) שִׁמְעוּ הָרִים אֶת רִיב ה' וְהָאֵתָנִים מֹסְדֵי אָרֶץ כִּי רִיב לַה' עִם עַמּוֹ וְגוֹ'. אֵי זָקֵן, עַד כָּאן הָיִיתָ בְּעִמְקֵי הַיָּם, וְעַכְשָׁו דִּלַּגְתָּ עַל הָרִים חֲזָקִים לַעֲשׂוֹת עִמָּהֶם קְרָב?! אֶלָּא וַדַּאי עַד עַכְשָׁו אַתָּה בַּיָּם הֶחָזָק, אֲבָל עַד שֶׁהָלַכְתָּ לְעִמְקֵי הַיָּם, פָּגַשְׁתָּ אֶת אוֹתָם הָרִים חֲזָקִים שֶׁבְּתוֹךְ הַיָּם וְנִתְקַלְתָּ בָּהֶם. עַכְשָׁו יֵשׁ לְךְ לַעֲרֹךְ קְרָב בְּעִמְקֵי הַיָּם וּבֶהָרִים הַלָּלוּ.</p>\n<p>זָקֵן עֲיֵף כֹּחַ, מִי נְתָנְךְ בָּזֶה? הָיִיתָ בְּשָׁלוֹם, וְרָצִיתָ אֶת כָּל זֶה?! אַתָּה עָשִׂיתָ - אַתָּה סוֹבֵל. עַכְשָׁו אֵין לְךְ אֶלָּא לַעֲרֹךְ קְרָב וּלְנַצֵּחַ אֶת הַכֹּל וְלֹא לַחֲזֹר לְאָחוֹר. הִתְחַזֵּק בְּכֹחֲךְ, חֲגֹר מָתְנֶיךְ וְאַל תִּפְחַד לִשְׁבֹּר אֶת הֶהָרִים הַלָּלוּ שֶׁלֹּא יִתְחַזְּקוּ עָלֶיךְ. אֱמֹר לָהֶם: הָרִים רָמִים, הָרִים חֲזָקִים, אֵיךְ אַתֶּם מִתְגַּבְּרִים?</p>\n<p>שְׁנֵי פְסוּקִים כְּתוּבִים. אֶחָד כָּתוּב, (שם) קוּם רִיב אֶת הֶהָרִים וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ, וְאֶחָד כָּתוּב, שִׁמְעוּ הָרִים אֶת רִיב ה'. אֶלָּא יֵשׁ הָרִים וְיֵשׁ הָרִים. יֵשׁ הָרִים שֶׁהֵם הָרִים רָמִים לְמַעְלָה לְמַעְלָה, לְאֵלֶּה כָּתוּב שִׁמְעוּ הָרִים אֶת רִיב ה'. וְיֵשׁ הָרִים שֶׁהֵם הָרִים תַּחְתּוֹנִים לְמַטָּה מֵהֶם, וּלְאֵלֶּה כָּתוּב קוּם רִיב אֶת הֶהָרִים, שֶׁהֲרֵי רוֹדֵף מְרִיבוֹת יֵשׁ לָהֶם. וְלָכֵן יֵשׁ הָרִים וְיֵשׁ הָרִים.</p>\n<p>וְאִם תֹּאמַר, זָקֵן, הֲרֵי כָּתוּב וְתִשְׁמַעְנָה הַגְּבָעוֹת, אֵלֶּה גְבָעוֹת כָּל אוֹתָם שֶׁלְּמַטָּה, וְעַכְשָׁו אַתָּה עוֹשֶׂה אוֹתָם הָרִים? אֶלָּא כָּךְ הוּא - לְאוֹתָם הָרִים רָמִים נִקְרָאִים גְּבָעוֹת. כְּשֶׁהֵם לְבַדָּם הֵם נִקְרָאִים הָרִים.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב וְהָאֵתָנִים מֹסְדֵי אָרֶץ. כֵּיוָן שֶׁכָּתוּב שִׁמְעוּ הָרִים, מִי הֵם הָרִים וּמִי הֵם אֵתָנִים? אֶלָּא הָרִים וְאֵתָנִים הַכֹּל דָּבָר אֶחָד. אֲבָל אוֹתָם שְׁלֹשָׁה עֶלְיוֹנִים מֵעַל רָאשֵׁיהֶם, וְאוֹתָם שְׁלֹשָׁה לְמַטָּה מֵהֶם, וְכֻלָּם אֶחָד. הָרִים לְמַעְלָה, וַעֲלֵיהֶם אָמַר דָּוִד, (תהליםקכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. וְאֵלֶּה הֵם שְׁלֹשָׁה הָרִאשׁוֹנִים. וְהָאֵתָנִים מֹסְדֵי אָרֶץ, אֵלֶּה הֵם שְׁלֹשָׁה אַחֲרוֹנִים, לְמַטָּה מֵהֶם, שְׁנֵי עַמּוּדֵי הַבַּיִת וְאֶחָד שִׂמְחַת הַבַּיִת, וְאֵלֶּה נִקְרְאוּ מֹסְדֵי אָרֶץ. אֵתָנִים הֵם, וְאֵתָנִים נִקְרְאוּ.</p>\n<p>זָקֵן זָקֵן, הֲרֵי יָדַעְתָּ, מִי שֶׁעוֹרֵךְ קְרָב, אִם לֹא יוֹדֵעַ לְהִשָּׁמֵר, לֹא יְנַצַּח בַּקְּרָבוֹת. צָרִיךְ לְהַכּוֹת בְּיָדוֹ וּלְהִשָּׁמֵר בְּרַעְיוֹנוֹ, מַה שֶּׁיִּהְיֶה אַחֵר חָשׁוּב, שֶׁיִּהְיֶה הוּא חָשׁוּב, וְיַד יָמִין מְזֻמֶּנֶת תָּמִיד לְהַכּוֹת. וּמַחְשְׁבוֹתָיו וְיָד שְׂמָאלִית זְמִינִים תָּמִיד לְקַבֵּל וּלְהִשָּׁמֵר, וְיָמִין הַכֹּל.</p>\n<p>עֵכְשָׁו אָמַרְתָּ וְהָאֵתָנִים. אֵיתָנִים הֵם לְמַטָּה, וְהָרִים לְמַעְלָה. הִשָּׁמֵר זָקֵן, שֶׁהֲרֵי רַעְיוֹן אַחֵר כְּנֶגְדְּךְ, שֶׁכָּתוּב (שם פט) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. וְזֶהוּ אַבְרָהָם הַזָּקֵן, וְנִקְרָא אֵיתָן. וְאִם אַבְרָהָם הוּא אֵיתָן, יִצְחָק וְיַעֲקֹב נִקְרְאוּ אֵיתָנִים. קוּם זָקֵן, שֶׁהֲרֵי יָדַעְתָּ רַעְיוֹן זֶה הָיָה מַכֶּה אֶת רַעְיוֹנְךְ.</p>\n<p>וַיִּשָּׂא מְשָׁלוֹ וַיֹּאמַר אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ (במדבר כד). אֵיתָן - זֶה בּקֶר שֶׁל אַבְרָהָם, וְהַיְנוּ (בראשית מד) הַבֹּקֶר אוֹר. זֶה הָעַמּוּד שֶׁכָּל הָעוֹלָם עוֹמֵד עָלָיו, וְאֶת אוֹרוֹ יָרַשׁ מֵאַבְרָהָם. נִקְרָא נָהָר הַיּוֹצֵא מֵעֵדֶן. אִי זָקֵן זָקֵן, הִנֵּה רַעְיוֹן אַחֵר כְּנֶגְדְּךְ, וְלֹא יָדַעְתָּ לְהִשָּׁמֵר אֵיךְ עוֹרְכִים קְרָב. זָקֵן, אֵיפֹה הַכֹּחַ שֶׁלְּךְ? וַדַּאי לֹא לַגִּבּוֹרִים הַמִּלְחָמָה.</p>\n<p>כָּתוּב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, וְכָתוּב מַשְׂכִּיל לְדָוִד. זֶה נָהָר הַיּוֹצֵא מֵעֵדֶן, שֶׁהוּא תֻּרְגְּמָן לְדָוִד לְהוֹדִיעַ לוֹ מֵאוֹתָם דְּבָרִים הַנִּסְתָּרִים הָעֶלְיוֹנִים. אִם מַשְׂכִּיל הוּא נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, אָז אֵיתָן הָאֶזְרָחִי אַבְרָהָם הוּא לְמַעְלָה וַדַּאי. זֶה יָדַעְתִּי. וְאַף עַל גַּב שֶׁאֲנִי זָקֵן, עַל רַעְיוֹן זֶה אֲנִי מוֹחֶה. אֵיתָן הָאֶזְרָחִי הֵם שְׁתֵּי דְרָגוֹת, כְּמוֹ שֶׁנֶּאֱמַר בֹּקֶר אוֹר. אוֹר זֶה אַבְרָהָם. בֹּקֶר זֶה נָהָר. אַף כָּךְ אֵיתָן הָאֶזְרָחִי. אֶזְרָח הוּא אַבְרָהָם.</p>\n<p>אֵיתָן, כְּמוֹ שֶׁנֶּאֱמַר, זֶה אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן. עֵכְשָׁו, זָקֵן, קוּם עֲמֹד עַל מֶרְכַּבְתְּךְ, שֶׁעַכְשָׁו תִּפֹּל וְלֹא תוּכַל לָקוּם. הֲרֵי שְׁלֹמֹה הַמֶּלֶךְ בָּא בְּכֹחוֹתָיו וּמַרְכְּבוֹתָיו וּגְבָרָיו וּפָרָשָׁיו וּבָא כְּנֶגְדְּךְ. קוּם צֵא מִן הַשָּׂדֶה, שֶׁלֹּא יִמְצָא אוֹתְךְ שָׁם. כָּתוּב (מלכים אח) וַיִּקָּהֲלוּ אֶל הַמֶּלֶךְ שְׁלֹמֹה כָּל אִישׁ יִשְׂרָאֵל בְּיֶרַח הָאֵתָנִים בֶּחָג וְגוֹ'. יֶרַח שֶׁנּוֹלְדוּ בוֹ הָאֵיתָנִים, וּמִי הֵם? הָאָבוֹת, וְהֵם אֵיתָנֵי הָעוֹלָם, וְיֶרַח זֶה הוּא תִּשְׁרֵי. שֶׁאַלְפָא בֵּיתָא חוֹזֵר לְמַפְרֵעַ מִמַּטָּה לְמַעְלָה.</p>\n<p>וְעוֹד מִדְּבָרֶיךְ, נָאֶה שֶׁתֵּצֵא מִן הַשָּׂדֶה וְלֹא תִמָּצֵא שָׁם. אִלּוּ כָּתוּב מַשְׂכִּיל אֵיתָן הָאֶזְרָחִי - אָז כְּמוֹ שֶׁאָמַרְתָּ. אֲבָל עַכְשָׁו שֶׁכָּתוּב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, הַקְּרָב שֶׁלְּךְ אֵינוֹ כְלוּם, וְתֵצֵא מִן הַשָּׂדֶה בְּעַל כָּרְחֲךְ וְלֹא תִתְרָאֶה שָׁם.</p>\n<p>אֵי זָקֵן, עָנִי מִסְכֵּן, אֵיךְ תֵּצֵא? אִם כָּךְ, יְנַצְּחוּ אוֹתְךְ וְתִבְרַח מִן הַשָּׂדֶה, כָּל בְּנֵי הָעוֹלָם יִרְדְּפוּ אַחֲרֶיךְ, וְאֵין לְךְ פָּנִים לְהֵרָאוֹת לִפְנֵי אִישׁ לְעוֹלָמִים. כָּאן נִשְׁבָּע אֲנִי שֶׁלֹּא אֵצֵא מֵהַשָּׂדֶה, וְכָאן אֶרָאֶה פָּנִים בְּפָנִים בִּשְׁלמֹה הַמֶּלֶךְ, וְכָל אִישׁ יִשְׂרָאֵל, וְהַגְּבָרִים וְהַפָּרָשִׁים וְהַמֶּרְכָּבוֹת שֶׁלּוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא יְסַיַּע לְךְ, זָקֵן, שֶׁהֲרֵי אַתָּה עֲיֵף כֹּחַ. קוּם זָקֵן, הִתְגַּבֵּר בְּכֹחֲךְ וְהִתְחַזֵּק, שֶׁעַד הַיּוֹם הַזֶּה הָיִיתָ גִּבּוֹר חָזָק בַּגְּבָרִים.</p>\n<p>פָּתַח וְאָמַר, מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. אִלּוּ כָּתוּב מַשְׂכִּיל לְדָוִד - אָז כְּמוֹ שֶׁאָמַרְתָּ, אֲבָל מַשְׂכִּיל לְאֵיתָן כָּתוּב. יֵשׁ מַשְׂכִּיל וְיֵשׁ מַשְׂכִּיל. יֵשׁ מַשְׂכִּיל לְמַעְלָה וְיֵשׁ מַשְׂכִּיל לְמַטָּה. מַשְׂכִּיל לְאֵיתָן, בִּזְמַן שֶׁאוֹתוֹ אִישׁ (נהר) עוֹמֵד בִּתְשׁוּקָה, כָּל הָאֵיבָרִים שְׂמֵחִים וּמִתְחַבְּרִים עִמּוֹ. וְאִם הוּא עוֹלֶה, עַד שֶׁהַמֹּחַ הָעֶלְיוֹן מִתְפַּיֵּס אֵלָיו וְשָׂמֵחַ כְּנֶגְדּוֹ. וְאָז מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, מַשְׂכִּיל אוֹתוֹ וּמוֹדִיעַ לוֹ עַל יְדֵי אַבְרָהָם (על ידיו של אברהם) אוֹהֲבוֹ כָּל מַה שֶּׁצָּרִיךְ, וְאוֹתוֹ מֹחַ עֶלְיוֹן מַשְׂכִּיל לְאֵיתָן. וּכְשֶׁדָּוִד הַמֶּלֶךְ נִתְקָן בִּתְשׁוּקָה אֵלָיו, הוּא מַשְׂכִּיל לְדָוִד, כְּמוֹ שֶׁהָיָה הַמֹּחַ הָעֶלְיוֹן מַשְׂכִּיל אוֹתוֹ. וְלָכֵן יֵשׁ מַשְׂכִּיל וְיֵשׁ מַשְׂכִּיל. (יש משכיל).</p>\n<p>בְּיֶרַח הָאֵתָנִים, שֶׁנּוֹלְדוּ הָאֵיתָנִים בַּיֶּרַח הַזֶּה. הַבִּנְיָן לְמַטָּה הוּא כְּמוֹ שֶׁלְּמַעְלָה, וְנוֹלְדוּ בוֹ הָרִים וְאֵיתָנִים. הָרִים נִסְתָּרִים. אֵתָנִים - יְרֵכַיִם חֲזָקוֹת כִּנְחֹשֶׁת, וְאוֹתוֹ הָאֵיתָן בֵּינֵיהֶם.</p>\n<p>קוּם זָקֵן, תַּכֶּה לְכָל הַצְּדָדִים. בְּשָׁעָה שֶׁעָלָה מֹשֶׁה לְקַבֵּל תּוֹרָה, מָסַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁבְעִים מַפְתְּחוֹת שֶׁל הַתּוֹרָה. כְּשֶׁהִגִּיעַ לַחֲמִשִּׁים (לששים) וְתִשְׁעָה, הָיָה מַפְתֵּחַ אֶחָד גָּנוּז וְנִסְתָּר, שֶׁלֹּא הָיָה מוֹסֵר לוֹ. הִתְחַנֵּן לְפָנָיו. אָמַר לוֹ: מֹשֶׁה, כָּל הַמַּפְתְּחוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים תְּלוּיִים בַּמַּפְתֵּחַ הַזֶּה. אָמַר לְפָנָיו: רִבּוֹן הָעוֹלָם, מַה שְּׁמוֹ? אָמַר לוֹ: אֵיתָן. וְכָל אוֹתָם אֵיתָנִים תְּלוּיִים בּוֹ, וּבוֹ עוֹמְדִים מִחוּץ לַגּוּף, שֶׁתּוֹרָה שֶׁבִּכְתָב הוּא, מוֹדִיעַ לוֹ וּמַשְׂכִּיל אוֹתוֹ, הוּא עִקָּר וְהַמַּפְתֵּחַ שֶׁל תּוֹרָה שֶׁבִּכְתָב.</p>\n<p>וּכְשֶׁנִּתְקְנָה תוֹרָה שֶׁבְּעַל פֶּה אֵלָיו, עִקַּר הַהֵיכָל הוּא הַמַּפְתֵּחַ שֶׁלָּהּ (אליו), וַדַּאי שֶׁאָז מַשְׂכִּיל לְדָוִד. וּמִתּוֹךְ שֶׁיָּרְשָׁה תוֹרָה שֶׁבְּעַל פֶּה (אליו) אוֹתִיּוֹת לְמַפְרֵעַ. וְעַל זֶה הוּא נִקְרָא תִשְׁרֵ\"י, הוּא תש\"ר, אֲבָל מִשּׁוּם שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ, חָתוּם בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹת שֶׁל שְׁמוֹ י'. בַּמִּזְבֵּחַ חָתוּם בּוֹ ה', הָרֶשֶׁת עַד חֲצִי הַמִּזְבֵּחַ. בָּאָה דְבוֹרָה וְחָתְמָה בּוֹ ו', וְהַיְנוּ מַה שֶּׁכָּתוּב (שופטים ה) וַתָּשַׁר דְּבוֹרָה. וּבַמָּקוֹם הַזֶּה הַחוֹתָם שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁחָתַם בּוֹ.</p>\n<p>וְאוֹתוֹ הַמַּפְתֵּחַ, כְּשֶׁפּוֹתֵחַ בַּתּוֹרָה שֶׁבְּעַל פֶּה, צְרִיכִים לְהִוָּדַע לוֹ, וְזֶהוּ תַּנְיָא, אֵיתָן מוֹשָׁבֶךְ, בָּרַיְתָא מִחוּץ לַגּוּף. אֵיתָנִים הֵם תַּנָּאִים, עַמּוּדִים תּוֹמְכִים מִחוּץ לַגּוּף. עַכְשָׁו יֵשׁ לְהוֹדִיעַ דָּבָר, בִּזְמַן שֶׁאֵלֶּה לַתּוֹרָה שֶׁבִּכְתָב נִקְרָאִים אֵיתָנִים - לַתּוֹרָה שֶׁבְּעַל פֶּה נִקְרָאִים תַּנָּאִים. אֵיתָן אֶל הַתּוֹרָה שֶׁבִּכְתָב. תַּנְיָא אֶל הַתּוֹרָה שֶׁבְּעַל פֶּה, וְהַכֹּל כָּרָאוּי.</p>\n<p>חֲבֵרִים, הֲרֵינִי בַּשָּׂדֶה. שְׁלֹמֹה הַמֶּלֶךְ וְהַגִּבּוֹרִים הַחֲזָקִים שֶׁלּוֹ יָבֹא וְיִמְצָא זָקֵן אֶחָד עָיֵף בְּכֹחוֹ, חָזָק גִּבּוֹר, מְנַצֵּחַ קְרָבוֹת. הֲרֵינִי יוֹדֵעַ שֶׁיָּבא, וְעוֹמֵד אַחַר סֶלַע הַשָּׂדֶה וְהוּא מַשְׁגִּיחַ בִּי וְאֵיךְ גְּבוּרָתִי עוֹמֶדֶת בַּשָּׂדֶה, לְבַדּוֹ מַשְׁגִּיחַ, שֶׁהוּא אִישׁ שָׁלוֹם, בַּעַל הַשָּׁלוֹם, וְהוֹלֵךְ לוֹ. עַכְשָׁו, זָקֵן, גְּבוּרָתְךְ עָלֶיךְ, וְאַתָּה לְבַד בַּשָּׂדֶה, שׁוּב לִמְקוֹמְךְ וְהַתֵּר כְּלִי זֵינְךְ מֵעָלֶיךְ.</p>\n<p>(כמי שיוצא מן השדה). שִׁמְעוּ הָרִים אֶת רִיב ה' וְהָאֵתָנִים מֹסְדֵי אָרֶץ (מיכה ו). שִׁמְעוּ הָרִים, כְּמוֹ שֶׁאָמַרְנוּ. וְהָאֵתָנִים מֹסְדֵי אָרֶץ, מֹסְדֵי אָרֶץ וַדַּאי, שֶׁהֲרֵי מִמֶּנּוּ נִזּוֹנֵית, וּמֵהֶם מְקַבֶּלֶת כָּל יוֹם, וְהֵם מֹסְדֵי אָרֶץ.</p>\n<p>כִּי רִיב לַה' עִם עַמּוֹ. מִי הוּא זֶה שֶׁיָּכוֹל לָקוּם בְּרִיב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (כָּל שֶׁכֵּן) בְּיִשְׂרָאֵל? וְעַל זֶה אָמַר לְאֵלֶּה, שִׁמְעוּ הָרִים אֶת רִיב ה' - זֶהוּ רִיב אֶחָד. קוּם רִיב אֶת הֶהָרִים - זֶה רִיב שֵׁנִי. שֶׁמְּנַצֵּחַ בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל הָרִיבוֹת הַלָּלוּ לְיִשְׂרָאֵל, וְכָל אוֹתָם תּוֹכָחוֹת, כֻּלָּם כְּאָב הַמּוֹכִיחַ אֶת בְּנוֹ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בְּיַעָקֹב כָּתוּב בְּשָׁעָה שֶׁרָצָה לְנַצֵּחַ עִמּוֹ, מַה כָּתוּב? (הושעיב) וְרִיב לַה' עִם יְהוּדָה וְלִפְקֹד עַל יַעֲקֹב. מַהוּ הָרִיב? כַּכָּתוּב, בַּבֶּטֶן עָקַב אֶת אָחִיו. עַל דָּבָר זֶה בָּאָה תוֹכָחָה, וְכָל אוֹתָם רִיבוֹת. וְכִי לֹא דָבָר גָּדוֹל הוּא, בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'? זֶה אֵינוֹ דָבָר קָטָן מַה שֶּׁעָשָׂה בַּבֶּטֶן. וְכִי רַמָּאוּת עָשָׂה בַּבֶּטֶן? כֵּן, וַדַּאי.</p>\n<p>ס\"א (והרי נאמר) (אבל) שֶׁבַּכֹּל דָּחָה יַעֲקֹב אֶת עֵשָׂו אָחִיו, כְּדֵי שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק כְּלָל. עֵשָׂו לֹא הִתְרַעֵם אֶלָּא מֵאֶחָד שֶׁהֵם שְׁנַיִם, שֶׁכָּתוּב (בראשית כז) וַיַּעְקְבֵנִי זֶה פַעֲמַיִם. פַּעֲמַיִם הָיָה צָרִיךְ (לכתב), מַה זֶּה \"זֶה\"? אֶלָּא אֶחָד שֶׁהִקִּישׁ לִשְׁנַיִם, אֶחָד שֶׁיָּצָא לִשְׁנַיִם, וּמַהוּ? בְּכֹרָתִי. שֶׁהִתְהַפְּכוּ הָאוֹתִיּוֹת וְנִהְיֶה בִּרְכָתִי. זֶה פַעֲמַיִם - אֶחָד שֶׁהֻקַּשׁ לִשְׁנַיִם.</p>\n<p>וְלֹא יָדַע עֵשָׂו מַה שֶּׁעָשָׂה לוֹ בַּבֶּטֶן, אֲבָל הַשַּׂר הַמְמֻנֶּה שֶׁלּוֹ הָיָה יוֹדֵעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רִגֵּשׁ אֶת הַשָּׁמַיִם וְחֵילֵיהֶם לַקּוֹל הַזֶּה, שֶׁהֲרֵי בְּרָכָה וּבְכוֹרָה לֹא תָבַע הַמְמֻנֶּה שֶׁלּוֹ, וְלֹא אָמַר. שֶׁהֲרֵי בְּרָכָה הָיָה לוֹ לִתְבּעַ וְלֹא תָבַע. אָחִיו הֲרֵי וַדַּאי שֶׁתָּבַע, שֶׁכָּתוּב (ישעיה נח) וּמִבְּשָׂרְךְ לֹא תִתְעַלָּם, וְלֹא רָצָה יַעֲקֹב לָתֵת לוֹ לֶאֱכֹל, עַד שֶׁנָּטַל מִמֶּנּוּ אֶת בְּכוֹרָתוֹ.</p>\n<p>אֵיזוֹ בְּכוֹרָה נָטַל מִמֶּנּוּ? הַבְּכוֹרָה שֶׁלְּמַעְלָה וּלְמַטָּה. בְּכֹרָה חָסֵר ו'. אָז הוּא עָקַב אֶת אָחִיו. וַדַּאי שֶׁעָשָׂה אוֹתוֹ עָקֵב וְזָרַק אוֹתוֹ לְאָחוֹר. אֵיזֶה אָחוֹר? שֶׁהִקְדִּים אוֹתוֹ, שֶׁיָּצָא בָּרִאשׁוֹנָה לָעוֹלָם הַזֶּה. אָמַר יַעֲקֹב לְעֵשָׂו, טֹל אַתָּה אֶת הָעוֹלָם הַזֶּה בַּתְּחִלָּה, וַאֲנִי אַחַר כָּךְ.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וְאַחֲרֵי כֵן יָצָא אָחִיו וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו. מַה זֶּה בַּעֲקֵב עֵשָׂו? וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁהָיָה אוֹחֵז אֶת יָדוֹ בְּרַגְלוֹ? לֹא כָּךְ. אֶלָּא יָדוֹ אוֹחֶזֶת בְּמִי שֶׁהוּא הָיָה עָקֵב. וּמִיהוּ? עֵשָׂו, שֶׁהֲרֵי עֵשָׂו נִקְרָא עָקֵב מִשָּׁעָה שֶׁעָקַב אֶת אָחִיו, וּמִיּוֹם שֶׁנִּבְרָא הָעוֹלָם קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עָקֵב, שֶׁכָּתוּב הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אַתָּה שֶׁנִּקְרָא עָקֵב תְּשׁוּפֶנּוּ בַּתְּחִלָּה, וּלְבַסּוֹף הוּא שֶׁיִּמְחֶה אֶת רֹאשְׁךְ מֵעָלֶיךְ. וּמִיהוּ? סמא\"ל, שֶׁהוּא רֹאשׁ שֶׁל הַנָּחָשׁ שֶׁמַּכֶּה בָּעוֹלָם הַזֶּה.</p>\n<p>וְעַל זֶה בַּבֶּטֶן עָקַב אֶת אָחִיו, שָׂם עָלָיו לִקְיוֹת עָקֵב, וְנָטַל עֵשָׂו אֶת הָעוֹלָם הַזֶּה בַּהַתְחָלָה. וְזֶה סוֹד הַכָּתוּב וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. וְזֶהוּ הַסּוֹד שֶׁאָמַר שְׁלֹמֹה הַמֶּלֶךְ, (משלי כ) נַחֲלָה מְבֹהֶלֶת בָּרִאשׁוֹנָה וְאַחֲרִיתָהּ לֹא תְבֹרָךְ, בְּסוֹף הָעוֹלָם.</p>\n<p>וְעַל זֶה (הושע יב) בַּבֶּטֶן עָקַב אֶת אָחִיו וּבְאוֹנוֹ שָׂרָה אֶת אֱלֹהִים. מַה זֶה וּבְאוֹנוֹ? כָּךְ אָמְרוּ, בְּכֹחַ וְהַתֹּקֶף שֶׁלּוֹ נָאֶה. אֲבָל לֹא כָּךְ. בֵּרוּר הַדָּבָר - שֶׁיַּעֲקֹב הָיָה דְיוֹקָן עֶלְיוֹן וְגוּף קָדוֹשׁ, שֶׁאֵין גּוּף מִיּוֹם שֶׁהָיָה אָדָם הָרִאשׁוֹן כְּמוֹ הַגּוּף שֶׁל יַעֲקֹב. וְיָפְיוֹ שֶׁל אָדָם, מַמָּשׁ אוֹתוֹ הַיֹּפִי הָיָה לְיַעֲקֹב. וּדְיוֹקָן שֶׁל יַעֲקֹב, דְּיוֹקָן שֶׁל אָדָם הָרִאשׁוֹן מַמָּשׁ.</p>\n<p>אָדָם הָרִאשׁוֹן, בְּשָׁעָה שֶׁבָּא הַנָּחָשׁ וְהִתְפַּתָּה עַל יָדוֹ, יָכֹל לוֹ הַנָּחָשׁ. מָה הַטַּעַם? כִּי לֹא הָיָה כֹּחַ לְאָדָם הָרִאשׁוֹן, וְעַד עַכְשָׁו לֹא נוֹלַד מִי שֶׁהָיָה הַכֹּחַ שֶׁלּוֹ. וּמִיהוּ תָקְפּוֹ שֶׁל אָדָם הָרִאשׁוֹן? זֶה שֵׁת, שֶׁהָיָה בִּדְיוֹקָן שֶׁל אָדָם הָרִאשׁוֹן מַמָּשׁ, שֶׁכָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת. מַה זֶּה בִּדְמוּתוֹ כְּצַלְמוֹ? שֶׁהָיָה מָהוּל. וּכְשֶׁבָּא הַמְמֻנֶּה שֶׁל עֵשָׂו אֶל יַעֲקֹב, כְּבָר נוֹלַד תָּקְפּוֹ שֶׁל יַעֲקֹב, שֶׁהוּא יוֹסֵף, וְזֶהוּ וּבְאוֹנוֹ שָׂרָה אֶת אֱלֹהִים. (עד כאן מצאתי).</p>\n<p>הַקּוֹל הַזֶּה שֶׁל הָאִשָּׁה שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהֵאָחֵז בָּהּ כְּמוֹ כֶלֶב בְּכַלְבָּה, מַה הוּא? אֶלָּא בּא וּרְאֵה שֶׁאֵין בְּכָל קוֹלוֹת הַנָּשִׁים שֶׁל הָעוֹלָם שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהִדָּבֵק בּוֹ וּלְהֵאָחֵז בּוֹ וּלְהִשְׁתַּתֵּף בּוֹ. אֶלָּא שְׁתֵּי נָשִׁים הֵן שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהֵאָחֵז בָּהֶן - אַחַת זוֹ שֶׁלֹּא שׁוֹמֶרֶת טֻמְאַת נִדָּה וִימֵי לִבּוּנָהּ כָּרָאוּי, אוֹ שֶׁמַּקְדִּימָה יוֹם אֶחָד לִטְבֹּל, וְאַחַת זוֹ אִשָּׁה שֶׁמְּאַחֶרֶת לְבַעְלָהּ אֶת עוֹנָתָהּ לַעֲשׂוֹת צַעַר לְבַעְלָהּ, פְּרָט אִם אֵינוֹ מַקְפִּיד וְלֹא מַשְׁגִּיחַ עַל זֶה.</p>\n<p>אֵלּוּ הֵן שְׁתֵּי נָשִׁים. שֶׁהֲרֵי כְּמוֹ שֶׁהִקְדִּימוּ, כָּךְ הֵן מִתְאַחֲרוֹת לְקוֹל הַנָּחָשׁ, עַד שֶׁנִּדְבָּק קוֹל בְּקוֹל, וּכְמוֹ שֶׁמִּתְאַחֲדוֹת לַעֲשׂוֹת צַעַר לְבַעְלָהּ (בעבודה) בְּעִכּוּב מִצְוָה, כָּךְ מַקְדִּים קוֹל הַנָּחָשׁ לְהִדָּבֵק בְּקוֹל אוֹתָהּ הָאִשָּׁה. וְאֵלּוּ הֵן שְׁתֵּי נָשִׁים שֶׁקּוֹל הַנָּחָשׁ אוֹחֵז בַּקּוֹל שֶׁלָּהֶן כְּמוֹ כֶלֶב בְּכַלְבָּה, טֻמְאָה אַחַר טֻמְאָה, מִין אַחַר מִינוֹ.</p>\n<p>וְאִם תֹּאמַר, מָה אִכְפַּת לָנוּ אִם אוֹחֵז קוֹל בְּקוֹל וְאִם לֹא אוֹחֵז? אוֹי שֶׁכָּךְ מִתְאַבְּדִים בְּנֵי הָעוֹלָם בְּלִי דַעַת. הַקּוֹל הַזֶּה שֶׁל הָאִשָּׁה, כְּשֶׁמִּתְעָרֵב וּמִשְׁתַּתֵּף יַחַד עִם קוֹל הַנָּחָשׁ, בְּשָׁעָה שֶׁהָרְשָׁעָה וּמִרְשַׁעַת יוֹצֵאת מִתּוֹךְ (האיפה) וּמְשׁוֹטֶטֶת בָּעוֹלָם, אִם הִיא פּוֹגֶשֶׁת בְּאוֹתָם שְׁנֵי קוֹלוֹת, קוֹל הַנָּחָשׁ וְקוֹל הָאִשָּׁה, וְהָאִשָּׁה מִתְחַמֶּמֶת בָּהֶם וְהֵם בָּהּ, וְכֵיוָן (שמתחממים נעשים רוח והולכים עמה), שֶׁמִתְחַמֶּמֶת נַעֲשִׂים רוּחַ, וּמִתְגַּשֵּׁם עִמָּהּ, עַד שֶׁמְּשׁוֹטֶטֶת וְנִכְנֶסֵת לִמְעֵי אוֹתָהּ הָאִשָּׁה.</p>\n<p>וְהַתִּינוֹקֹ הַזֶּה שֶׁיּוֹלֶדֶת, כְּשֶׁבָּאָה אוֹתָהּ רְשָׁעִית (לילי\"ת), פּוֹקֶדֶת אֶת אוֹתָהּ הָרוּחַ שֶׁהוּא חִבּוּר רַע, קוֹל הַנָּחָשׁ שֶׁמְּכַשְׁכֵּשׁ בָּהּ, וְהוּא צוֹחֵק בַּתִּינוֹק, עַד שֶׁבָּאָה אוֹתָהּ הָרְשָׁעִית (לילי\"ת) כְּמוֹ אִשָּׁה שֶׁפּוֹקֶדֶת בֵּן לְאִשָּׁה אַחֶרֶת, וּמְפַטְפֶּטֶת לוֹ וְצוֹחֶקֶת לוֹ בְּפִטְפּוּט עַד שֶׁתָּבֹא אִמּוֹ. כָּךְ עוֹשָׂה אוֹתָהּ הָרוּחַ. וּפְעָמִים רַבּוֹת שֶׁהוּא שָׁלִיחַ שֶׁל אוֹתָהּ הָרְשָׁעִית, וְהוֹרֶגֶת אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (קהלת ד) וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ, וְלֹא כְּמוֹ שֶׁאַתֶּם אוֹמְרִים, אֶלָּא אוֹתוֹ כֹּחַ שֶׁל אוֹתָהּ רוּחַ. וְעַל זֶה פַּעֲמַיִם כָּתוּב בַּפָּסוּק הַזֶּה וְאֵין לָהֶם מְנַחֵם - אֶחַד מִלִּילִית הָרְשָׁעָה, וְאֶחָד מֵאוֹתָהּ הָרוּחַ.</p>\n<p>אֵי סָבָא, עַתָּה יֵשׁ לְךְ רַחֲמִים, וְאַתָּה מְדַבֵּר כְּמִי שֶׁלֹּא רָאָה אֵלּוּ הַיּוֹצְאִים לִקְרָב, הֲרֵי כֻּלָּם בְּשָׁלוֹם עִמְּךְ. עַתָּה מִכָּאן וּלְהָלְאָה לֹא</p>\n<p>אֶפְשּט מֵעָלַי כְּלֵי הַקְּרָב בַּעֲבוּר שֶׁאַזְכִּיר שְׁמִי. אוֹתוֹ חַטָּאת רֹבֵץ עוֹמֵד עַל הַפֶּתַח כְּמוֹ כֶלֶב. בִּזְמַן שֶׁהַקּוֹל הָאַחֲרוֹן שֶׁנּוֹתֶנֶת הָאִשָּׁה יוֹצֵא, הוּא מְדַלֵּג מֵעַל הַפֶּתַח וְעוֹבֵר מִשָּׁם וְהוֹלֵךְ אַחֲרֶיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ מַפְתֵּחַ אֶחָד שֶׁלּוֹ, וְהַקּוֹל פּוֹרֵחַ, וְהַמַּפְתֵּחַ בָּא, וְהַנָּחָשׁ הוֹלֵךְ אַחַר הַקּוֹל שֶׁהוּא יוֹצֵא לָעוֹלָם, וְעַד הָהָר שֶׁבַּבֶּטֶן הוֹלֵךְ וּמְכַשְׁכֵּשׁ, עַד הַזְּמַן שֶׁמִּתְנַקֵּית מֵאוֹתָהּ הַזֻּהֲמָה שֶׁל נְשִׁיכוֹת הַנָּחָשׁ הָרָע. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים וְעוֹשֶׂה מַעֲשִׂים כָּרָאוּי.</p>\n<p>וְכָל זֶה מִשּׁוּם שֶׁאוֹתָהּ הַבֶּטֶן נִדְחֲתָה. הֲרֵי וַדַּאי שֶׁנִּדְחָה מֵאוֹתָהּ הַבֶּטֶן, וְאֵין לוֹ חֵלֶק, וְנִדְחָה מֵהַבֶּטֶן שֶׁלְּמַטָּה שֶׁל שְׁאָר נְשׁוֹת הָעוֹלָם. שֶׁאַף עַל גַּב שֶׁעוֹשֶׂה צַעַר, לֹא נִתֶּנֶת לוֹ רְשׁוּת לִשְׁלֹט בָּהֶם. וְאֵיזוֹ בֶּטֶן נִתֶּנֶת לוֹ וְשׁוֹלֵט עָלֶיהָ? אוֹתָהּ הַבֶּטֶן שֶׁל הַסּוֹטָה, שֶׁכָּתוּב (במדבר ה) וְצָבְתָה בִטְנָהּ. מִשּׁוּם שֶׁבַּבֶּטֶן הַזּוֹ עוֹשֶׂה בָּהּ נְקָמוֹת כִּרְצוֹנוֹ, וְהַבֶּטֶן הַזּוֹ הִיא שֶׁלּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ בִּשְׁבִיל שֶׁלֹּא יִדָּחֶה מֵהַכֹּל. עַכְשָׁו, אֲהוּבִים שֶׁלִּי, הַקְשִׁיבוּ. לֹא רָאִיתִי אֶתְכֶם וְדִבַּרְתִּי עִמָּכֶם, (קהלת א) כָּל הַדְּבָרִים יְגֵעִים, לֹא יָכוֹל אִישׁ לְדַבֵּר, אֲפִלּוּ דִּבְרֵי הַתּוֹרָה הֵם יְגֵעִים.</p>\n<p>כָּתוּב (בראשית לה) וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וַיֵּאָבֵק אִישׁ עִמּוֹ, וְכָתוּב וַיַּרְא כִּי לֹא יָכֹל לוֹ וַיִּגַּע בְּכַף יְרֵכוֹ. וְאוֹתָהּ יָרֵךְ שֶׁהִרְוִיחַ מִיַּעֲקֹב. וְאוֹתָהּ הַיָּרֵךְ בְּחֻלְשָׁתָהּ עַד שֶׁבָּא שְׁמוּאֵל. מַה זֶּה בְּחֻלְשָׁה? שֶׁלֹּא מָשַׁךְ נְבוּאָה. כְּשֶׁבָּא שְׁמוּאֵל, נָטַל אוֹתָהּ יָרֵךְ וְהֶעֱלָה אוֹתָהּ מֵאוֹתוֹ מָקוֹם וְחָטַף אוֹתָהּ מִמֶּנּוּ, וּמֵאוֹתוֹ זְמַן הָעָבְרָה מִמֶּנּוּ וְלֹא הָיָה לוֹ חֵלֶק בַּקְּדֻשָּׁה כְּלָל.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא לֹא קִפַּח וְלֹא דָחָה אוֹתוֹ מִן הַכֹּל, מִשּׁוּם שֶׁשְּׁמוּאֵל נָטַל אֶת הַיָּרֵךְ שֶׁלּוֹ, אֶלָּא נָתַן לוֹ חֵלֶק אֶחָד, וּמַהוּ? נָתַן לוֹ אוֹתָהּ יָרֵךְ וּבֶטֶן שֶׁל הַסּוֹטָה תְּמוּרַת אוֹתָהּ יָרֵךְ וּבֶטֶן שֶׁהֶעֱבִיר מִמֶּנּוּ, וְלָכֵן אֶת שְׁנֵיהֶם נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִהְיוֹת הַמָּקוֹם הַקָּדוֹשׁ פָּנוּי מִכָּל טֻמְאָה.</p>\n<p>וְלַנְפִּל יָרֵךְ. מַה זֶה וְלַנְפִּל? וְנָפְלָה יְרֵכָהּ הָיָה צָרִיךְ לִהְיוֹת! וְלַצְבּוֹת, וְצָבְתָה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמִי שֶׁזּוֹרֵק עֶצֶם לַכֶּלֶב וְאוֹמֵר לוֹ: טֹל אֶת זֶה לְחֶלְקְךְ. וּמֵהַכֹּל לֹא הֵרַע לְפָנָיו אֶלָּא שֶׁגָּזְלוּ (שהוציאו) מִמֶּנּוּ יָרֵךְ, מִשּׁוּם שֶׁהוּא יָגַע וְהִתְעַיֵּף עָלֶיהָ וְהִרְוִיחַ אוֹתָהּ וְהוֹצִיאוּ אוֹתָהּ מִמֶּנּוּ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא הִפִּיל לוֹ אֶת הָעֶצֶם הַזּוֹ שֶׁל הַסּוֹטָה וְהוֹצִיא אוֹתוֹ לוֹ, כְּמוֹ שֶׁאָמַרְנוּ, וּבָזֶה הוּא רָוָה וְשָׂמַח.</p>\n<p>כָּל אוֹתָן הַמֶּרְכָּבוֹת וְהַסִּיּוּעַ שֶׁלּוֹ תָּמִיד רוֹצִים יָרֵךְ, וְהוֹלְכִים בִּתְשׁוּקָה אַחֲרֶיהָ, וּמִשּׁוּם כָּךְ הַבִּרְכַּיִם שֶׁל הָרַבָּנִים עֲיֵפִים, וְזֶה מִן זֶה. שֶׁכָּל הַתְּשׁוּקָה שֶׁלָּהֶם אַחַר הַיָּרֵךְ הִיא, וְכָל שֶׁכֵּן יָרֵךְ שֶׁל חֲכָמִים, וְכָל דָּבָר חוֹזֵר לִמְקוֹמוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא גוֹרֵעַ כְּלוּם מִכָּל מַה שֶּׁצָּרִיךְ, וְלֹא רוֹצֶה שֶׁיִּתְקָרֵב לַקְּדֻשָּׁה חוּץ מֵעַמּוֹ וְגוֹרָלוֹ, חֶלְקוֹ וְנַחֲלָתוֹ. כְּמוֹ שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, כָּךְ עוֹשִׂים יִשְׂרָאֵל לְמַטָּה וְכָךְ צָרִיךְ לַעֲשׂוֹת. וְכָךְ שָׁנִינוּ, אָסוּר לְיִשְׂרָאֵל לְלַמֵּד תּוֹרָה לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁכָּתוּב (תהליםקמז) מַגִּיד דְּבָרָיו לְיַעֲקֹב וְגוֹ', לֹא עָשָׂה כֵן לְכָל גּוֹי וְגוֹ'.</p>\n<p>וְלָכֵן דָּחָה אוֹתוֹ יַעֲקֹב וְדָחָה אוֹתוֹ שְׁמוּאֵל, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בַּקְּדֻשָּׁה. וּמִשּׁוּם כָּךְ כָּל שְׁמִירַת הַשִּׂנְאָה לְיִשְׂרָאֵל הִיא עַל כָּךְ. לְכֶלֶב שֶׁחָטַף עוֹף טָהוֹר מֵהַשּׁוּק וְהֵבִיא אוֹתוֹ, וְטֶרֶם שֶׁנִּשְׁבַּר בָּא אִישׁ אֶחָד וְחָטַף אוֹתוֹ מִמֶּנּוּ, וְאַחַר כָּךְ נָתַן לוֹ עֶצֶם נִגְרֶרֶת אַחַת בְּלִי תוֹעֶלֶת.</p>\n<p>כָּךָ לְשָׂרוֹ שֶׁל עֵשָׂו הוֹצִיאוּ אוֹתוֹ מֵאוֹתָהּ הַבֶּטֶן, חָטְפוּ מִמֶּנּוּ אֶת אוֹתָהּ הַיָּרֵךְ, אַחַר כָּךְ נָתְנוּ לוֹ עֶצֶם אַחַת - אוֹתָהּ הַבֶּטֶן וְאוֹתָהּ הַיָּרֵךְ שֶׁל הַסּוֹטָה, וְלֹא אַחֵר. זוֹ הָעֶצֶם שֶׁנָּתְנוּ לְחֶלְקוֹ וּלְגוֹרָלוֹ וְעָרְבָה לוֹ. וּמִשּׁוּם כָּךְ כָּל דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם דִּינֵי אֱמֶת, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים לַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם בְּדֶרֶךְ אֱמֶת. הִיא הִסְטְתָה אֶת עַצְמָהּ מִבַּעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר (משלי ב) הַעֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְגוֹ'. אַף כָּךְ הָאִשָּׁה כְּגוֹן שֶׁלָּהּ בָּאָרֶץ.</p>\n<p>בֹּא וּרְאֵה, מִי שֶׁמּוֹצֵא חָבֵר כְּמוֹתוֹ שֶׁעוֹשֶׂה כְמַעֲשָׂיו בָּעוֹלָם, אוֹהֵב אוֹתוֹ וְנִדְבָּק עִמּוֹ וְעוֹשֶׂה עִמּוֹ טוֹב. אֲבָל הַצַּד הָאַחֵר לֹא כָּךְ; כֵּיוָן שֶׁמּוֹצֵא מִי שֶׁעָזַב אֶת צַד הַקְּדֻשָּׁה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשֶׂה כְמַעֲשָׂיו וְנִדְבָּק בּוֹ, אָז הוּא רוֹצֶה לְכַלּוֹתוֹ וּלְהוֹצִיאוֹ מִן הָעוֹלָם. הָאִשָּׁה הַזּוֹ עָשְׂתָה כְמַעֲשָׂיו וְנִדְבְּקָה בּוֹ, רְאֵה מַה הוּא עָשָׂה בָּהּ - וְצָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ כָּךְ; מִי שֶׁעוֹזֵב אֶת הַצַּד הָאַחֵר וְנִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז אוֹהֵב אוֹתוֹ וְעוֹשֶׂה לוֹ כָּל טוּב שֶׁבָּעוֹלָם. עַכְשָׁו, זָקֵן, תַּקֵּן עַצְמְךְ, שֶׁהֲרֵי הַנָּחָשׁ הָלַךְ לוֹ וְרוֹצֶה לְהִתְגָּרוֹת בְּךְ וְלֹא יָכוֹל.</p>\n<p>פָּתַח וְאָמַר, (קהלת א) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ. וְכִי לֹא בָא שְׁלֹמֹה אֶלָּא לְלַמֵּד דָּבָר זֶה? אִלּוּ אָמַר (וכי מה בא שלמה המלך ללמד בדבר זה, ' ועוד, אלו אמר) בַּעֲמָלוֹ שֶׁיַּעֲמֹל - יָפֶה, שֶׁהֲרֵי נִשְׁאָר עָמָל שֶׁיֵּשׁ בּוֹ יִתְרוֹן. אֶלָּא כֵּיוָן שֶׁכָּתוּב בְּכָל עֲמָלוֹ, הֲרֵי הַכְּלָל שֶׁל הַכֹּל - שֶׁלֹּא נִשְׁאָר כְּלוּם שֶׁיֵּשׁ בּוֹ יִתְרוֹן.</p>\n<p>אֶלָּא שֶׁלֹּא לְכָל אָדָם אָמַר שְׁלֹמֹה אֶת הַדָּבָר הַזֶּה, אֶלָּא יֵשׁ אָדָם בָּעוֹלָם שֶׁמִּשְׁתַּדֵּל תָּמִיד בְּרַע וּלְהָרַע, וְלֹא מִשְׁתַּדֵּל בְּטוֹב אֲפִלּוּ רֶגַע אֶחָד, וְעַל זֶה כָּתוּב עֲמָלוֹ וְלֹא כָתוּב יְגִיעוֹ. עֲמָלוֹ - כְּמוֹ שֶׁנֶּאֱמַר (תהלים ס) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ. וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל. יְגִיעוֹ - כְּמוֹ שֶׁנֶּאֱמַר (שם קכח) יְגִיעַ כַּפֶּיךְ כִּי תֹאכֵל וְגוֹ'. וְכָתוּב (בראשית לא) וְאֶת יְגִיעַ כַּפַּי רָאָה אֱלֹהִים. אֲבָל עֲמָלוֹ, כָּתוּב (תהלים י) עָמָל וָכַעַס. הִשְׁתַּדְּלוּתוֹ הִיא תָּמִיד לְרַע, וְעַל כָּךְ הוּא תַּחַת הַשָּׁמֶשׁ.</p>\n<p>בְּשָׁעָה שֶׁהָאָדָם הַזֶּה מִשְׁתַּדֵּל בְּרַע, עַל זֶה כָּתוּב (איוב יח) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגוֹ', שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה שֶׁלֹּא יַעֲשֶׂה תוֹלָדוֹת, שֶׁאִלְמָלֵא יַעֲשֶׂה תוֹלָדוֹת, הָיָה מַחֲרִיב אֶת הָעוֹלָם, וְעַל זֶה כָּתוּב מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ. וּמִי שֶׁלֹּא מִשְׁתַּדֵּל לַעֲשׂוֹת תּוֹלָדוֹת, נִדְבָּק בַּצַּד הַזֶּה שֶׁל אָדָם רַע, וְנִכְנָס תַּחַת כְּנָפָיו.</p>\n<p>רוּת אָמְרָה, (רות ג) וּפָרַשְׂתָּ כְנָפֶיךְ עַל אֲמָתְךְ, כְּדֵי לְהִזְדַּוֵּג עִם הַצַּדִּיק, לַעֲשׂוֹת תּוֹלָדוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹרֵס כְּפָנָיו עַל בֶּן אָדָם כְּדֵי לְהִתְרַבּוֹת בָּעוֹלָם, וּמִי שֶׁלֹּא רוֹצֶה לַעֲשׂוֹת תּוֹלָדוֹת, בְּגַפּוֹ יָבֹא - בְּגַפּוֹ שֶׁל אוֹתוֹ רַע, שֶׁהוּא הוֹלֵךְ עֲרִירִי כַּנָּחָשׁ הַזֶּה שֶׁהוֹלֵךְ יְחִידִי. בְּגַפּוֹ יֵצֵא - כְּמוֹ שֶׁנִּתְבָּאֵר, הוּא שֶׁלֹּא הִשְׁתַּדֵּל לַעֲשׂוֹת תּוֹלָדוֹת, הֲרֵי נִתְבָּאֵר כָּל מַה שֶּׁצָּרִיךְ. (בא וראה שיש לחזר זקן בדברים הראשונים).</p>\n<p>הָרִיב שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הֲרֵי נֶאֱמַר, רִיב - שֶׁכָּתוּב (מיכה ו) קוּם רִיב אֶת הֶהָרִים. מִי הֵם? אֶלָּא אוֹתָם הָרִים שֶׁלְּמַטָּה. לָמָּה הָרִיב הַזֶּה? מִשּׁוּם שֶׁבָּהֶם תְּלוּיִים כָּל הַחֲטָאִים שֶׁעוֹשִׂים יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם. מָה הַטַּעַם? כִּי יִשְׂרָאֵל הָיוּ יוֹדְעִים שִׁמּוּשׁ שֶׁל כָּל הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁבַּשָּׁמַיִם, וְלֹא נֶעְלָם מֵהֶם אֲפִלּוּ שְׁמוֹ שֶׁל אֶחָד מֵהֶם, וְכָל הַשִּׁמּוּשׁ שֶׁלָּהֶם.</p>\n<p>וּבִשְׁנֵי צְדָדִים הָיוּ טוֹעִים אַחֲרֵיהֶם. אֶחָד - שֶׁהָיוּ יוֹדְעִים לִמְשֹׁךְ אֶת כֹּחָם שֶׁל הַכּוֹכָבִים וְהַמַּזָלוֹת לָאָרֶץ. וְאֶחָד - שֶׁהָיוּ יוֹדְעִים אֵיךְ לְהַשְׁבִּיעָם בְּכָל מַה שֶּׁהִצְטָרְכוּ, וְלָכֵן רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בָּהֶם רִיב וְדִין. וְכֵיוָן שֶׁבָּהֶם יִהְיֶה רִיב וְדִין, כָּל הַשַּׁלְשֶׁלֶת נוֹפֶלֶת, שֶׁהֲרֵי לֹא תִהְיֶה בּוֹ תּוֹעֶלֶת, וּמִשּׁוּם כָּךְ קוּם רִיב וְגוֹ'. וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ, מִי הַגְּבָעוֹת? אֵלֶּה הֵן הָאִמָּהוֹת, הַדְּרָגוֹת שֶׁנִּקְרָאוֹת בְּתוּלוֹת אַחֲרֶיהָ וְגוֹ', וּמִשּׁוּם כָּךְ וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ.</p>\n<p>שֶׁכָּךְ הָיוּ עוֹשִׂים יִשְׂרָאֵל עַד שֶׁהִשְׁתַּתְּפוּ בִּדְרָגוֹת תַּחְתּוֹנוֹת. בֹּא וּרְאֵה שֶׁיֵּשׁ לַחֲזֹר, זָקֵן, לִדְבָרִים רִאשׁוֹנִים, שֶׁכָּךְ הָיוּ עוֹשִׂים יִשְׂרָאֵל עַד שֶׁהִשְׁתַּתְּפוּ בַדְּרָגוֹת הַתַּחְתּוֹנוֹת. הַיָּרֵךְ שֶׁאָמַרְנוּ, הַרְבֵּה הִתְקִיפוּ אֶת יִשְׂרָאֵל בְּאוֹתָהּ הַיָּרֵךְ. מָרְדְּכַי הָיָה מַרְאֶה לְאוֹתוֹ הָמָן הָרָשָׁע אֶת אוֹתָהּ יָרֵךְ שֶׁלּוֹ, וְלָכֵן הָיָה רוֹגֵז, דָּבָר שֶׁנִּרְאָה לוֹ, וְהוּא הִרְגִּיז אוֹתוֹ עִמּוֹ. רְאוּ הַחֲבֵרִים מַה כָּתוּב - (בראשית כז) וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדֹל הַחֲמֻדת וְגוֹ'. בַּלְּבוּשׁ הַלָּלוּ שֶׁלּוֹ גָּזַל אוֹתוֹ וְהוֹצִיא אוֹתוֹ מִכָּל בִּרְכוֹתָיו וּמֵהַבְּכוֹרָה.</p>\n<p>וּמִשּׁוּם כָּךְ, הָעִלָּה שֶׁמָּצְאוּ הַמֶּרְכָּבוֹת שֶׁלּוֹ לַחֲכָמִים הוּא הַחִכּוּךְ שֶׁלָּהֶם עִם בִּגְדֵי רַבּוֹתֵינוּ תָּמִיד לַיְרֵכַיִם שֶׁלָּהֶם וְלַבְּגָדִים שֶׁלָּהֶם. וְאֵלּוּ שְׁנֵי הַדְּבָרִים הָיוּ שֶׁל הַצַּד הָאַחֵר, וְכָל זֶה מִשּׁוּם שֶׁגָּזְלוּ מִמֶּנּוּ אוֹתָם, וְאֵין לָהֶם עִלָּה אֶלָּא לַחֲכָמִים. וּמִשּׁוּם כָּךְ הַבְּגָדִים הַלָּלוּ שֶׁל הַחֲכָמִים הֵם מִתְבַּלִּים מֵהַחִכּוּךְ שֶׁלָּהֶם, וְהַבִּרְכַּיִם הַכּוֹשְׁלוֹת הַלָּלוּ זֶה מֵהֶם וַדַּאי, וּמִשֶּׁלָּהֶם הָיוּ, וּמֵהֶם נוֹטְלִים תּוֹאֲנָה, וּמִמַּה שֶּׁהָיוּ מֵהֶם. וְרוֹצִים לַחֲכָמִים, שֶׁהֵם כְּלָל שֶׁל אוֹתוֹ שֶׁיּוֹשֵׁב אֹהָלִים, וְלָכֵן אֵין עִלָּה בְּלִי עִלָּה, וְלָכֵן אֵין דָּבָר בְּלִי דִין, וְכָל דָּבָר שָׁב לִמְקוֹמוֹ.</p>\n<p>שְׁלֹמֹה אָמַר, (קהלת ד) וְשַׁבְתִּי אֲנִי וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשִׂים תַּחַת הַשָּׁמֶשׁ וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ וְאֵין לָהֶם מְנַחֵם. הַפָּסוּק הַזֶּה רָמַזְנוּ בוֹ וְנִתְבָּאֵר. אֲבָל שַׁבְתִּי אֲנִי, וְכִי מֵאֵיזֶה מָקוֹם שָׁב שְׁלֹמֹה? אִם נֹאמַר, לְאַחַר שֶׁאָמַר דָּבָר זֶה שָׁב כְּמוֹ מִקֹּדֶם וְאָמַר דָּבָר אַחֵר - יָפֶה. אֲבָל שַׁבְתִּי וָאֶרְאֶה.</p>\n<p>שָׁם שָׁנִינוּ, בְּכָל יוֹם הָיָה מַקְדִּים שְׁלֹמֹה בַּבֹּקֶר וְהָיָה שָׂם פָּנָיו לְצַד מִזְרָח וְרוֹאֶה מַה שֶּׁרוֹאֶה, וְאַחַר כָּךְ שָׁב לְצַד דָּרוֹם וְרוֹאֶה מַה שֶּׁרוֹאֶה, וְאַחַר כָּךְ שָׁב לְצַד צָפוֹן וְעוֹמֵד שָׁם. מַנְמִיךְ עֵינָיו וּמֵרִים רֹאשׁוֹ.</p>\n<p>בַּשָּׁעָה הַזּוֹ הֲרֵי עַמּוּד אֵשׁ וְעַמּוּד עָנָן הָיוּ בָאִים, וְעַל אוֹתוֹ עַמּוּד הֶעָנָן הָיָה בָּא נֶשֶׁר אֶחָד, וְאוֹתוֹ הַנֶּשֶׁר הוּא גָּדוֹל וְחָזָק. וְכָךְ הָיָה בָּא: כָּנָף יָמִין עַל גַּבֵּי עַמּוּד הָאֵשׁ, וְהַגּוּף וְכָנָף שְׂמֹאל עַל גַּבֵּי עַמּוּד הָעָנָן. וְאוֹתוֹ נֶשֶׁר הָיָה מֵבִיא שְׁנֵי עָלִים בְּפִיו. בָּא עַמּוּד הֶעָנָן וְעַמּוּד הָאֵשׁ, וְאוֹתוֹ הַנֶּשֶׁר עֲלֵיהֶם, וּמִשְׁתַּחֲוִים לִפְנֵי שְׁלֹמֹה הַמֶּלֶךְ.</p>\n<p>בָּא הַנֶּשֶׁר וְהִנְמִיךְ לְפָנָיו, וְנָתַן לוֹ אוֹתָם עָלִים. לוֹקֵחַ אוֹתָם הַמֶּלֶךְ שְׁלֹמֹה וּמֵרִיחַ בָּהֶם, וְהָיָה יוֹדֵעַ בָּהֶם סִימָן וְאוֹמֵר: זֶהוּ הַנּוֹפֵל, וְזֶהוּ גְּלוּי הָעֵינַיִם. בְּשָׁעָה שֶׁשְּׁנֵי עָלִים הָיוּ, הָיָה יוֹדֵעַ שֶׁשְּׁנֵיהֶם - נוֹפֵל וּגְלוּי עֵינַיִם - רוֹצִים לְהוֹדִיעוֹ דְבָרִים.</p>\n<p>מֶה עָשָׂה? חָתַם אֶת כִּסְאוֹ בְּחוֹתָם שֶׁהָיָה חָקוּק בּוֹ הַשֵּׁם הַקָּדוֹשׁ, וְנוֹטֵל טַבַּעַת שֶׁחָקוּק עָלֶיהָ הַשֵּׁם הַקָּדוֹשׁ, וְעוֹלֶה לַגַּג וְרוֹכֵב עַל אוֹתוֹ הַנֶּשֶׁר וְהוֹלֵךְ לוֹ. וְאוֹתוֹ נֶשֶׁר הָיָה מִתְעַלֶּה לְרוּם הָעֲנָנִים, וּבְכָל מָקוֹם שֶׁהוּא עָבַר, הָיָה הָאוֹר נֶחְשָׁךְ. הַחֲכָמִים שֶׁהָיוּ בְּאוֹתוֹ הַמָּקוֹם שֶׁחָשַׁךְ הָאוֹר, הָיוּ יוֹדְעִים, וְהָיוּ אוֹמְרִים: שְׁלֹמֹה הַמֶּלֶךְ הֲרֵי הוֹלֵךְ וְעוֹבֵר כָּאן. וְלֹא יוֹדְעִים לְאֵיזֶה מָקוֹם הָיָה הוֹלֵךְ. הַטִּפְּשִׁים שֶׁהָיוּ שָׁם הָיוּ אוֹמְרִים, שֶׁהֵם הָיוּ עֲנָנִים שֶׁהוֹלְכִים וּמַחְשִׁיכִים אֶת הָעוֹלָם.</p>\n<p>הִגְבִּיהַּ הַנֶּשֶׁר עִמּוֹ וּפוֹרֵחַ אַרְבַּע מֵאוֹת פַּרְסָאוֹת, עַד שֶׁמַּגִּיעַ לְהָרֵי הַחֹשֶׁךְ. שָׁם הוּא תַּרְמוּד בַּמִּדְבָּר בֶּהָרִים, וְהוּא יוֹרֵד שָׁם. מֵרִים רֹאשׁוֹ וְרוֹאֶה הַר חָשׁוּךְ, וְשָׁם הָיָה יוֹדֵעַ כָּל מַה שֶּׁצָּרִיךְ, וְהָיָה יוֹדֵעַ שֶׁשָּׁם יִכָּנֵס. הָיָה רוֹכֵב עַל הַנֶּשֶׁר כְּמִקֹּדֶם, וְטָס וְנִכְנָס לְתוֹךְ הֶהָרִים עַד אוֹתוֹ מָקוֹם שֶׁשָּׁם הַזַּיִת, קוֹרֵא בְחַיִל וְאוֹמֵר, ה' רָמָה יָדְךְ בַּל יֶחֱזָיוּן וְגוֹ'.</p>\n<p>נִכְנָס לְשָׁם, עַד שֶׁקָּרַב לְאוֹתוֹ מָקוֹם, וְשָׂם טַבַּעַת לִפְנֵיהֶם וְקָרַב, וְשָׁם הָיָה יוֹדֵעַ כָּל מַה שֶּׁרָצָה מֵאוֹתָן חָכְמוֹת זָרוֹת שֶׁרָצָה לָדַעַת. כֵּיוָן שֶׁהָיוּ אוֹמְרִים לוֹ כָּל מַה שֶּׁרָצָה, אָז הָיָה רוֹכֵב עַל אוֹתוֹ נֶשֶׁר, וְשָׁב לִמְקוֹמוֹ. כֵּיוָן שֶׁהָיָה יוֹשֵׁב עַל כִּסְאוֹ, הִתְיַשֵּׁב בְּדַעְתּוֹ וְהָיָה מְדַבֵּר בְּדַעְתּוֹ דִּבְרֵי חָכְמָה נִכְבָּדָה. בְּאוֹתָהּ שָׁעָה הָיָה אוֹמֵר, וְשַׁבְתִּי אֲנִי וָאֶרְאֶה. שַׁבְתִּי וַדַּאי מֵאוֹתָהּ דֶּרֶךְ, שַׁבְתִּי מֵאוֹתָהּ חָכְמָה וְהִתְיַשְּׁבָה בְּלִבִּי וּבְדַעְתִּי. וְאָז, וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים. (וכי מעטים הם בעולם שהוא אמר את כל העשוקים, ').</p>\n<p>(העלה על דעתך שכל העשוקים שהיו בעולם היה רואה שלמה המלך?!) אֶלָּא מִי הָעֲשׁוּקִים הַלָּלוּ שֶׁהוּא אָמַר? אוֹתָם הַתִּינוֹקוֹת שֶׁמֵּתִים בְּחֵיק אִמּוֹתֵיהֶם, שֶׁהֲרֵי הֵם עֲשׁוּקִים מִכַּמָּה צְדָדִים - עֲשׁוּקִים בְּמָקוֹם עֶלְיוֹן שֶׁלְּמַעְלָה, וַעֲשׁוּקִים לְמַטָּה. וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, וְכָךְ הוּא, אֲבָל רַבִּים הֵם. קוּם זָקֵן, הִתְעוֹרֵר בְּכֹחֲךְ. זָקֵן, אֱמֹר דְּבָרְךְ, שֶׁוַּדַּאי תֹּאמַר בְּלִי פַּחַד.</p>\n<p>אֵין עָשׁוּק כְּאוֹתָם עֲשׁוּקִים, שֶׁהָיָה הוּא עָשׁוּק בַּהַתְחָלָה, אוֹ מִשְּׁלִישִׁי לְאַחֵר, כַּכָּתוּב (שמות לד) פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים וְעַל בְּנֵי בָנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים.</p>\n<p>אֵיךָ הָיָה עוֹשֵׁק? שְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (משלי כח) אָדָם עָשֻׁק בְּדַם נָפֶשׁ עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. כֵּיוָן שֶׁהוּא עָשׁוּק בְּדַם נֶפֶשׁ, הוּא אוֹ בְּנוֹ אוֹ בֶּן בְּנוֹ יִהְיוּ עֲשׁוּקִים בְּמֹאזְנַיִם, שֶׁכָּתוּב עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. עַד אוֹתוֹ הַבּוֹר רַק יָנוּס מִמָּקוֹם קָדוֹשׁ, וְאַל יִתְמְכוּ בוֹ בָּעוֹלָם הַזֶּה. כֵּיוָן שֶׁהוּא עָשׁוּק בְּדַם נֶפֶשׁ, הוּא אוֹ זַרְעוֹ יִהְיוּ עֲשׁוּקִים מֵאוֹתוֹ הַצַּד הָאַחֵר.</p>\n<p>יִשִׁ עָשׁוּק מִשְּׁאָר עֲשׁוּקִים, כְּמוֹ שֶׁנֶּאֱמַר לֹא תַעֲֹשק אֶת רֵעֲךְ. הוּא עָבַר וְעָשַׁק, הוּא עָשׁוּק כְּבָנָיו, מֵאוֹתוֹ הַצַּד הָאַחֵר, וּמִשּׁוּם כָּךְ אָמַר אֶת כָּל הָעֲשׁוּקִים. אָמַר שְׁלֹמֹה, עָמַדְתִּי בְּכָל אוֹתָם עֲשׁוּקִים בְּכָל הַצְּדָדִים שֶׁעָשַׁק.</p>\n<p>וְלָמָּה הֵם עֲשׁוּקִים? אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ. אֲשֶׁר נַעֲשׂוּ? אֲשֶׁר גָּרוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֲשֶׁר נַעֲשׂוּ? אִם הָעֲשִׂיָּה הִיא לְשֶׁבַח, אֵין עֲשִׂיָּה שֶׁלָּהֶם אֶלָּא לְמַעְלָה מִן הַשֶּׁמֶשׁ.</p>\n<p>אֲבָל וַדַּאי נַעֲשׂוּ. אֵיךְ נַעֲשׂוּ? אֶלָּא כֵּיוָן שֶׁעֲשׁוּקִים מֵרוּחָם שָׁם, לָמָּה בָּאִים לָעוֹלָם הַזֶּה? אֶלָּא וַדַּאי רוּחוֹת נַעֲשׂוּ, נַעֲשׂוּ בְרוּחוֹת וְגוּף בָּעוֹלָם הַזֶּה. כֵּיוָן שֶׁנִּתְקַן הַגּוּף שֶׁלָּהֶם וְנֶעֶשְׂתָה אוֹתָהּ רוּחַ בְּגוּף זַךְ וְנָקִי בְּלִי לִכְלוּךְ שֶׁל חֲטָאִים בָּעוֹלָם הַזֶּה, אָז נֶעֱשַׁק הַגּוּף כְּמוֹ שֶׁנֶּעֶשְׁקָה הָרוּחַ. וְזֶהוּ הַגּוּף שֶׁנֶּהֱנָה בּוֹ יוֹתֵר מֵהַכֹּל. וְיֵשׁ עֲשׁוּקִים אֲחֵרִים בְּכַמָּה מִינִים מֵרוּחוֹת שָׁם, וְלֹא נַעֲשׂוּ בְגוּפִים. אֲבָל אֵלֶּה הֵם עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ.</p>\n<p>יִשִׁ אֲחֵרִים אֲשֶׁר נַעֲשׂוּ, וְהִטְרִיחוּ בְּנֵי אָדָם אֶת רִבּוֹנָם. וּמִי הֵם? מִי שֶׁעָשַׁק אֵשֶׁת חֲבֵרוֹ בַּסֵּתֶר אוֹ בַּגָּלוּי, וְאוֹתוֹ וָלָד שֶׁנּוֹלָד מֵהֶם הוּא עָשׁוּק, בְּלִי רְצוֹן רִבּוֹנָם, וְלֹא יוֹדֵעַ בַּעַל הָאִשָּׁה שֶׁאוֹתָם הַמַּעֲשִׂים הֵם עֲשׁוּקִים, וְהִטְרִיחוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָהֶם גּוּף וּלְצַיֵּר לָהֶם צוּרָה. אֵלּוּ עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ. אֲשֶׁר נַעֲשׂוּ וַדַּאי הַגּוּפִים שֶׁלָּהֶם עַל כֹּרַח. מִשּׁוּם כָּךְ שְׁלֹמֹה הַמֶּלֶךְ אוֹמֵר, (קהלת ד) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים, בְּכָל מִינֵי עֲשׁוּקִים עָמַדְתִּי, אוֹתָם אֲשֶׁר נַעֲשׂוּ וְנַעֲשׂוּ בַּעֲשִׂיָּה.</p>\n<p>כְּמוֹ שֶׁאֵלֶּה (הואבערלה, אינו גדל ועושה, ואחר כך עושקים אותו ממגו, כך) אוֹתָם עֲשׁוּקִים, שֶׁכְּבָר נַעֲשׂוּ בְעָרְלָה, וְהִתְרַבָּה וְנָטַל וְגָדַל הַגּוּף, וְעָשָׂה אוֹתוֹ, וְאַחַר כָּךְ עוֹשְׁקִים אוֹתָם מִמֶּנּוּ וְלוֹקְחִים אוֹתָם, הֲרֵי עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ, וְעַל הַכֹּל עָמַד הַמֶּלֶךְ שְׁלֹמֹה וְאָמַר, עָמַדְתִּי עַל כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ.</p>\n<p>וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים, כֻּלָּם שׁוֹפְכִים דְּמָעוֹת עִם טַעֲנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אֵלּוּ שׁוֹפְכִים דְּמָעוֹת, שֶׁהֲרֵי הָעָרְלָה מַרְבָּה וּמְגַדֶּלֶת אוֹתָם עַד שְׁלֹשׁ עֶשְׂרֵה שָׁנִים, וְאַחַר כָּךְ עוֹשְׁקִים אוֹתָם מֵהָעָרְלָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא לוֹקֵחַ אוֹתָם. הֲרֵי לְךְ עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ כְּבָר.</p>\n<p>עָבַר עֲבֵרָה - הוֹרְגִים אוֹתוֹ. לָהֶם יֵשׁ טַעֲנָה, וַעֲתִידִים לוֹמַר: רִבּוֹן הָעוֹלָם, תִּינוֹק בֶּן יוֹמוֹ שֶׁחָטָא, דָּנִים אוֹתוֹ דִּין? אֲנִי בֶּן יוֹמִי הָיִיתִי, שֶׁהֲרֵי מֵאוֹתוֹ יוֹוֹ קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּן, שֶׁכָּתוּב (תהליםב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. רִבּוֹן הָעוֹלָם, יְלִיד בֶּן יוֹם, דִּין עוֹשִׂים לוֹ? הֲרֵי דִּמְעַת אוֹתָם הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם.</p>\n<p>וְיִשִׁ עָשׁוּק אַחֵר, אוֹתוֹ עָשׁוּק שֶׁנִּקְרָא מַמְזֵר, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם, מִיָּד מַפְרִידִים אוֹתוֹ מִקְּהִלַּת הָעָם הַקָּדוֹשׁ. אוֹתוֹ מַמְזֵר, עָנִי מִסְכֵּן, שׁוֹפֵךְ דְּמָעוֹת לִפֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְטוֹעֵן לְפָנָיו: רִבּוֹן הָעוֹלָם, אִם אֲבוֹתַי חָטְאוּ, אֵיזֶה חֵטְא אֲנִי עָשִׂיתִי? הֲרֵי מַעֲשַׂי תְּקִינִים הָיוּ לְפָנֶיךְ, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם. וְכֵן לְכָל אוֹתָם עֲשׁוּקִים יֵשׁ לָהֶם טַעֲנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמֵאוֹתָהּ טַעֲנָה אֵין לָהֶם מְנַחֵם, וְאֵין שֶׁיָּשִׁיב דָּבָר עַל לִבָּם.</p>\n<p>וּמַה שֶּׁאָמַר וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים - אֵלּוּ אוֹתָם שֶׁמֵּתִים בְּחֵיק אִמּוֹתֵיהֶם, אֵלֶּה עוֹשִׂים לִשְׁפֹּךְ דְּמָעוֹת לְכָל בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁאֵין דְּמָעוֹת שֶׁיּוֹצְאוֹת מִן הַלֵּב כַּדְּמָעוֹת הַלָּלוּ, שֶׁכָּל בְּנֵי הָעוֹלָם תּוֹהִים וְאוֹמְרִים: דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם אֱמֶת, וְהוֹלְכִים עַל דֶּרֶךְ אֱמֶת. הַתִּינוֹקוֹת הַמִּסְכֵּנִים הַלָּלוּ שֶׁלֹּא חָטְאוּ, לָמָּה מֵתוּ? אֵיפֹה דִּין הָאֱמֶת שֶׁעוֹשֶׂה רִבּוֹן הָעוֹלָם? אִם בַּחֲטָאֵי אֲבוֹתָם מִסְתַּלְּקִים מִן הָעוֹלָם - לָמָּה? וַדַּאי אֵין לָהֶם מְנַחֵם.</p>\n<p>עוֹד, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים - אוֹתָהּ דִּמְעָה שֶׁלָּהֶם בְּאוֹתוֹ הָעוֹלָם, שֶׁמְּגִנִּים עַל הַחַיִּים. שֶׁשָּׁנִינוּ, יֵשׁ מָקוֹם מְתֻקָּן לָהֶם בְּאוֹתוֹ עוֹלָם שֶׁאֲפִלּוּ צַדִּיקִים גְּמוּרִים לֹא יְכוֹלִים לַעֲמֹד שָׁם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם וְנִדְבָּק בָּהֶם, וּמְתַקֵּן בָּהֶם אֶת הַיְשִׁיבָה הָעֶלְיוֹנָה שֶׁלּוֹ, וַעֲלֵיהֶם כָּתוּב (תהלים ח) מִפִּי עוֹלְלִים וְיֹנְקִים יִסַּדְתָּ עֹז. וּמָה הַתּוֹעֶלֶת שֶׁעוֹשִׂים שָׁם, וְלָמָּה עוֹלִים לְשָׁם? שֶׁכָּתוּב לְמַעַן צוֹרְרֶיךְ לְהַשְׁבִּית אוֹיֵב וּמִתְנַקֵּם. וְכֵן יֵשׁ מָקוֹם אַחֵר לְבַעֲלֵי תְשׁוּבָה.</p>\n<p>שָׁנִינוּ, עֲשָׂרָה דְבָרִים נִבְרְאוּ בְּעֶרֶב שַׁבָּת וְכוּ'. הַכְּתָב וְהַמִּכְתָּב וְהַלּוּחוֹת, שֶׁכָּתוּב (שמות לב) וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא. מָה הַמְדֻבָּר מִכָּךְ שֶׁהָיָה עֶרֶב שַׁבָּת, וְאוּלַי זֶה הָיָה אֶלֶף שָׁנָה אַחַר כָּךְ, אוֹ בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי? אֶלָּא וַדַּאי שֶׁזֶּה הָיָה בְּעֶרֶב שַׁבָּת. בֹּא וּרְאֵה, בְּכָל מַעֲשֵׂה בְרֵאשִׁית לֹא נֶאֱמַר שֵׁם מָלֵא, אֶלָּא אֱלֹהִים אֱלֹהִים בְּכָל מַה שֶּׁנִּבְרָא, וְכֻלָּם שֵׁם אֱלֹהִים, עַד שֶׁכָּל הַמַּעֲשֶׂה נִתְקַן בְּעֶרֶב שַׁבָּת. מִשֶּׁנִּתְקְנוּ כָּל הַמַּעֲשִׂים, נִקְרָא ה' אֱלֹהִים, שֵׁם מָלֵא.</p>\n<p>וְאַף עַל גַּב שֶׁהַכֹּל נִבְרָא בְּשֵׁם אֱלֹהִים, לֹא נִתְקַן בָּעֲשִׂיָּה כָּל מַה שֶּׁנִּבְרָא עַד עֶרֶב שַׁבָּת. בְּאוֹתָהּ שָׁעָה הַכֹּל נִתְקַן בָּעֲשִׂיָּה, שֶׁכָּתוּב (בראשית ב) מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. וְעוֹמֵד בְּמַעֲשֶׂה. וְלָכֵן כָּתוּב וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים, כְּשֶׁנִּתְקַן הָעוֹלָם בְּשֵׁם אֱלֹהִים בְּמַעֲשֶׂה, וְלֹא אַחַר כָּךְ, שֶׁכָּתוּב ה' אֱלֹהִים. וּבָזֶה נִתְקַן הָעוֹלָם וְעָמַד עַל קִיּוּמוֹ.</p>\n<p>בֹּא וּרְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁשָּׁבַר מֹשֶׁה אֶת הַלּוּחוֹת, שֶׁכָּתוּב (שמות לב) וַיְשַׁבֵּר אֹתָם תַּחַת הָהָר, צָף הָאוֹקְיָנוֹס מִמְּקוֹמוֹ וְעָלָה לִשְׁטֹף אֶת הָעוֹלָם. רָאָה מֹשֶׁה שֶׁאוֹקְיָנוֹס עוֹלֶה אֲלֵיהֶם וְהָיָה רוֹצֶה לִשְׁטֹף אֶת הָעוֹלָם, מִיָּד - וַיִּקַּח אֶת הָעֵגֶל אֲשֶׁר עָשׂוּ וַיִּשְׂרֹף בָּאֵשׁ וְגוֹ', וַיִּזֶר עַל פְּנֵי הַמַּיִם. עָמַד מֹשֶׁה עַל מֵי הָאוֹקְיָנוֹס וְאָמַר: מַיִם מַיִם, מָה אַתֶּם רוֹצִים? אָמְרוּ: וְכִי מִתְקַיֵּם הָעוֹלָם אֶלָּא בְּתוֹרַת הַלּוּחוֹת?! וְעַל הַתּוֹרָה שֶׁשִּׁקְּרוּ בָהּ בְּנֵי יִשְׂרָאֵל (ועשואתעגלהזהבאנורוציםלשטף את העולם).</p>\n<p>מִיָּד אָמַר לָהֶם: הֲרֵי כָּל מַה שֶּׁעָשׂוּ בְּחֵטְא הָעֵגֶל, הֲרֵי מָסוּר לָכֶם, וְלֹא דַי כָּל אוֹתָם הָאֲלָפִים שֶׁנָּפְלוּ מֵהֶם?! מִיָּד - וַיִּזֶר עַל פְּנֵי הַמַּיִם. וְלֹא הָיוּ הַמַּיִם שׁוֹכְכִים עַד שֶׁנָּטַל מֵהֶם וְהִשְׁקָה אוֹתָם. מִיָּד נִשְׁקַע הָאוֹקְיָנוֹס בִּמְקוֹמוֹ.</p>\n<p>שֶׁהֲרֵי בְּאוֹתוֹ הַמִּדְבָּר לֹא הָיוּ מַיִם, שֶׁכָּתוּב (במדבר כ) לֹא מְקוֹם זֶרַע וְגוֹ'. וּמַיִם אַיִן לִשְׁתּוֹת. וְאִם תֹּאמַר, לִבְאֵר מִרְיָם זָרַק - חַס וְשָׁלוֹם שֶׁשָּׁם יִזְרֹק מֹשֶׁה אֶת הַזִּכָּרוֹן הָרָע הַזֶּה לִשְׁתּוֹת מִמֶּנּוּ אַחַר כָּךְ. וְעוֹד, שֶׁעַד עַכְשָׁו לֹא הָיְתָה לָהֶם בְּאֵר, עַד שֶׁבָּאוּ לְמִדְבַּר מַתָּנָה, שֶׁכָּתוּב בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. וּמִמִּדְבָּר מַתָּנָה. מִשָּׁם יָרְשׁוּ בְאֵר. כָּתוּב עַל פְּנֵי הַמַּיִם, וְכָתוּב שָׁם עַל פְּנֵי תְהוֹם.</p>\n<p>חָרוּת עַל הַלֻּחֹת. מַה זֶּה חָרוּת עַל הַלֻּחֹת? כָּךְ פֵּרְשׁוּהָ, חֵרוּת מִמַּלְאַךְ הַמָּוֶת, חֵרוּת מִשִּׁעְבּוּד מַלְכֻיּוֹת, חֵרוּת מֵהַכֹּל. כָּךְ הוּא. וּמַה זֶּה חֵרוּת? חוֹתָם שֶׁל הָעוֹלָם הַבָּא, שֶׁבּוֹ יֵשׁ חֵרוּת בְּכָל מִינֵי חֵרוּת. וְאִלְמָלֵא לֹא נִשְׁבְּרוּ, כָּל מַה שֶּׁבָּא לָעוֹלָם אַחַר כָּךְ - לֹא בָא, וְהָיוּ יִשְׂרָאֵל בִּדְיוֹקְנָאוֹת שֶׁל מַלְאָכִים עֶלְיוֹנִים שֶׁלְּמַעְלָה. וְעַל כָּךְ מַכְרִיז הַכָּתוּב וְאוֹמֵר וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים וְגוֹ'. אַל תֹּאמַר שֶׁלְּאַחַר שֶׁהָעוֹלָם נִתְקַן וְנִזְכַּר שֵׁם מָלֵא הָיוּ, אֶלָּא בְּשָׁעָה שֶׁנִּתְקַן בְּשֵׁם אֱלֹהִים, טֶרֶם שֶׁנִּכְנְסָה שַׁבָּת.</p>\n<p>הֵמָּה, מַה זֶּה הֵמָּה? הָפוּךְ מה\"ה הָיוּ, מִשְּׁנֵי צְדָדִים הָיוּ - אֶחָד בְּמַעֲשֶׂה, וְאֶחָד מֵחֵרוּת שֶׁל מַעְלָה. רָשׁוּם לְמַעְלָה לִשְׁמֹר אֶת הַכֹּל. וְעַל זֶה הֵמָּ\"ה. וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא - אֵשׁ שְׁחֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה. מִכְתַּב אֱלֹהִים הוּא, הַיְנוּ שֶׁכָּתוּב וְעָבַד הַלֵּוִי הוּא. חָרוּת, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי יוֹבֵל נִקְרָא חֵרוּת, וְעוֹשֶׂה חֵרוּת לְכָל הָעוֹלָמוֹת.</p>\n<p>לָכֵן, חֲבֵרִים, מִכָּאן וָהָלְאָה תֵּדְעוּ שֶׁהֲרֵי הַצַּד הָרָע לֹא שׁוֹלֵט עֲלֵיכֶם, וַאֲנִי יֵיבָא סָבָא עוֹמֵד לִפְנֵיכֶם לְעוֹרֵר דְּבָרִים אֵלּוּ. קָמוּ הֵם, כְּמִי שֶׁהִתְעוֹרֵר מִשְּׁנָתוֹ, וְהִשְׁתַּטְּחוּ לְפָנָיו, וְלֹא הָיוּ יְכוֹלִים לְדַבֵּר. אַחַר כְּשָׁעָה הֵם בָּכוּ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ כַּחוֹתָם עַל זְרוֹעֶךְ וְגוֹ'. שִׂימֵנִי כַחוֹתָם, בְּשָׁעָה שֶׁנִּדְבְּקָה כְּנֶסֶת יִשְׂרָאֵל בְּבַעְלָהּ, הִיא אָמְרָה שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ. דֶּרֶךְ הַחוֹתָם, כֵּיוָן שֶׁנִּדְבָּק בְּאוֹתוֹ מָקוֹם שֶׁנִּדְבָּק, מַשְׁאִיר בּוֹ אֶת כָּל דְּיוֹקְנוֹ. אַף עַל גַּב שֶׁאוֹתוֹ חוֹתָם הוֹלֵךְ כָּאן וְכָאן וְלֹא עוֹמֵד שָׁם וְנֶעֱבָר מִמֶּנּוּ, כָּל דְּיוֹקְנוֹ מַשְׁאִיר שָׁם, וְשָׁם עוֹמֵד. אַף כָּךְ אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, כֵּיוָן שֶׁנִּדְבַּקְתִּי בְךְ, כָּל דְּיוֹקְנִי יִהְיֶה חָקוּק בְּךְ, שֶׁאַף עַל גַּב שֶׁאֵלֵךְ לְכָאן וּלְכָאן, תִּמְצָא אֶת דְּיוֹקְנִי חָקוּק בְּךְ וְתִזְכֹּר אוֹתִי.</p>\n<p>וְכַחוֹתָם עַל זְרוֹעֶךְ, כְּמוֹ שֶׁכָּתוּב (שירב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי, אַף כָּךְ יִהְיֶה דְיוֹקְנִי חָקוּק שָׁם, וּבְכֵן אֶהְיֶה דְבוּקָה בְּךְ לְעוֹלָמִים וְאַל אֶשְׁתַּכַּח מִמְּךְ. כִּי עַזָּה כַמָּוֶת אַהֲבָה, חֲזָקָה כַּמָּוֶת אַהֲבָה, בְּחֹזֶק חָזָק, כְּמוֹ אוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה בּוֹ הַמָּוֶת. אַהֲבָה - אוֹתוֹ מָקוֹם שֶׁנִּקְרָא אַהֲבַת עוֹלָם.</p>\n<p>קָשָׁה כִשְׁאוֹל קִנְאָה - אַף כָּךְ, שֶׁהֲרֵי אֵלּוּ הַשֵּׁמוֹת הֵם מֵאוֹתוֹ צַד. רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ, מַה הֵם רִשְׁפֵּי אֵשׁ הַלָּלוּ? אוֹתָם אֲבָנִים וּמַרְגָּלִיּוֹת טוֹבוֹת שֶׁנּוֹלְדוֹ מֵאוֹתָהּ אֵשׁ. שַׁלְהֶבֶת יָהּ, מֵאוֹתָהּ שַׁלְהֶבֶת שֶׁיּוֹצֵאת מִן הָעוֹלָם הָעֶלְיוֹן וְנֶאֶחְזָה בִּכְנֶסֶת יִשְׂרָאֵל, לִהְיוֹת הַכֹּל יִחוּד אֶחָד. וְאָנוּ, הֲרֵי אַהֲבָה וְרִשְׁפֵּי שַׁלְהֶבֶת שֶׁל הַלֵּב אַחֲרֶיךְ, יְהִי רָצוֹן שֶׁהַדְּיוֹקָן שֶׁלָּנוּ יִהְיֶה חָקוּק בְּלִבְּךְ כְּמוֹ שֶׁהַדְּיוֹקָן שֶׁלְּךְ חָקוּק בְּלִבֵּנוּ. נָשַׁק אוֹתָם וּבֵרַךְ אוֹתָם וְהָלְכוּ.</p>\n<p>כְּשֶׁהִגִּיעוּ אֶל רַבִּי שִׁמְעוֹן וְסִפְּרוּ לוֹ כָּל מַה שֶּׁקָּרָה לָהֶם, שָׂמַח וְתָמַהּ וְאָמַר, אַשְׁרֵיכֶם שֶׁזְּכִיתֶם לְכָל זֶה. וּמָה הֱיִיתֶם עִם הָאַרְיֵה הָעֶלְיוֹן גִּבּוֹר חָזָק, שֶׁכַּמָּה גִבּוֹרִים לֹא הָיוּ אֵלָיו כְּלוּם, וְלֹא יְדַעְתֶּם לְהִוָּדַע לוֹ מִיָּד, תָּמַהְתִּי אֵיךְ נִצַּלְתֶּם מֵעָנְשׁוֹ, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַצִּילְכֶם. קָרָא עֲלֵיהֶם, וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל. (ישעיהס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. (עד כאן מן רב ייבא סבא).</p>"],[9522011665,"<p>כִּי יִנָּצוּ אֲנָשִׁים - אֵלּוּ מִיכָאֵל וְס\"מ. וְנָגְפוּ אִשָּׁה הָרָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְיָצְאוּ יְלָדֶיהָ - בַּגָּלוּת. עָנוֹשׁ יֵעָנֵשׁ - זֶה ס\"מ. כַּאֲשֶׁר יָשִׁית עָלָיו בַּעַל הָאִשָּׁה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011666,"<p>מִצְוָה (מא) אַחַר זוֹ - לְהָשִׁיב אֲבֵדָה, וְאַחֲרָיו - לְהָשִׁיב הַגָּזֵל. אָמַר מְנוֹרָה הַקְּדוֹשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲזִיר לְךְ אֶת הָאֲבֵדוֹת שֶׁאִבַּדְתָּ מִשּׁוּם הָעֵרֶב רַב, וְזוֹ הַכַּלָּה שֶׁלְּךְ, שֶׁבִּזְמַן שֶׁעָשׂוּ הָעֵרֶב רַב אֶת הָעֵגֶל, יָצְאָה הַכַּלָּה שֶׁלְּךְ. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּשְׁלֵךְ מִיָּדָו אֶת הַלֻּחֹת.</p>\n<p>וְנֶאֱמַר בְּךְ לֶךְ רֵד. שָׁם נִרְמְזָה יְרִידָה שֶׁלְּךְ לַגָּלוּת הָרְבִיעִית. לֶךְ - כְּמוֹ (בראשית יב) לֶךְ לְךְ מֵאַרְצְךְ וְגוֹ'. כָּאן שׁ, (איוב לב) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר. כָּאן רוֹמֵז לֶךְ לְךְ שָׁלֹשׁ פְּעָמִים (בגלגול) בַּגָּלוּת. בָּרְבִיעִית רֵד, בִּשְׁבִיל בַּת יְחִידָה, הַכַּלָּה שֶׁלְּךְ שֶׁנָּפְלָה. זֶהוּ שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם. וּמִיָּד שֶׁאַתָּה יוֹרֵד בִּשְׁבִילָהּ, תָּקוּם עָלִיּךְ, וזו (זו השבת אבדה, וזו התורה שהתגלתה על ידך, זו) הִיא הֲשָׁבַת הָאֲבֵדָה שֶׁלְּךְ.</p>\n<p>שֶׁלֹּא לְחִנָּם נִגְלְתָה לְךְ תּוֹרָה יוֹתֵר מִכָּל יִשְׂרָאֵל וְעָלְתָה אֵלֶיךְ כְּמוֹ מֵי הַבְּאֵר שֶׁעָלוּ אֵלֶיךְ, וְלֹא לָאָבוֹת וְלֹא לְאִישׁ, שֶׁהֲרֵי הַבְּאֵר מַכִּירָה אֶת אֲדוֹנֶיהָ. וְעַל הַתּוֹרָה הַזּוֹ נֶאֱמַר (במדבר כא) וּמִשָּׁם בְּאֵרָה הִיא הַבְּאֵר וְגוֹ'. הַבְּאֵר הִיא מְלֵאָה, וְלֹא יוֹצְאִים מֵימֶיהָ הַחוּצָה, וְהִיא בְּאֵר מֵי הַתּוֹרָה שֶׁמּוֹצִיאָה כָּל הַמַּיִם, וְכָל הַמַּיִם שֶׁל הָעוֹלָם נִכְנָסִים בָּהּ, וְלֹא יוֹצְאִים מֵימֶיהָ הַחוּצָה.</p>\n<p>וְהִיא הַבְּאֵר שֶׁאֲפִלּוּ כָּל בְּנֵי הָעוֹלָם שׁוֹאֲבִים מִמֶּנָּה מַיִם וַאֲפִלּוּ כָּל עַנְנֵי הָעוֹלָם, לֹא חֲסֵרִים מִמֶּנָּה אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה. מִשּׁוּם שֶׁבְּאֵר זוֹ אֵין לָהּ סוֹף. יוֹתֵר עֲמֻקָּה הִיא מִן הַתּוֹרָה שֶׁנֶּאֱמַר בָּהּ (איוב יא) וּרְחָבָה מִנִּי יָם. וּבַכַּד שֶׁל מִי שֶׁשּׁוֹאֵב מִמֶּנָּה מַיִם, הוּא בּוֹלֵעַ (כל מימות וכל חכמות) אֶת כָּל חָכְמוֹת הָעוֹלָם. כָּל שֶׁכֵּן הַבְּאֵר עַצְמָהּ.</p>\n<p>וְכֵן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲזִיר לְךְ אֶת הַגָּזֵל שֶׁלְּךְ, שֶׁהוּא הַמַּטֶּה, שֶׁנֶּאֱמַר בּוֹ (שמואל ב כג) וַיִּגְזל אֶת הַחֲנִית מִיַּד הַמִּצְרִי, שֶׁעָלֶיךְ נֶאֱמַר אִישׁ מִצְרִי. וּבַגָּלוּת שֶׁלְּךְ וּבַגִּלְגּוּל שֶׁלְּךְ יַפְרִישׁ לְךְ עָרֵי מִקְלָט לְהִנָּצֵל מִכַּמָּה שֶׁרוֹדְפִים אַחֲרֶיךְ שֶׁאֵין לָהֶם סוֹף.</p>"],[9522011667,"<p>וְזוֹהִי מִצְוָה (מב) (אחת) לְהַפְרִישׁ עָרֵי מִקְלָט לְמִי שֶׁהָרַג, מִשּׁוּם אוֹתוֹ הַמִּצְרִי שֶׁהָרַגְתָּ בְּמִצְרַיִם, שֶׁשָּׁם הָיָה נָחָשׁ הַקַּדְמוֹנִי וְכָל מַחֲנוֹת שֶׁהָיוּ מַקִּיפִים אוֹתוֹ, וְהָרַגְתָּ אוֹתוֹ בְּלִי זְמַנּוֹ, וְלֹא פָחַדְתָּ מֵהָרוֹדְפִים שֶׁלּוֹ, שֶׁבְּכַמָּה מְקוֹמוֹת רָדְפוּ אַחֲרֶיךְ כַּמָּה נָשִׁים בְּנַעֲרוּתְךְ, שֶׁהֵן נַעֲמָ\"ה אַגְרַ\"ת לִילִי\"ת שְׁחֹרָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְךְ עָרֵי מִקְלָט לְהִנָּצֵל מֵהֶן, וְהֵם שַׁעֲרֵי תְשׁוּבָה.</p>\n<p>מִשּׁוּם שֶׁאַתָּה בֶּן יָהּ, בֵּן שֶׁל אַבָּא וְאִמָּא. אַחַר שֶׁחָזַרְתָּ בְּהֵ\"א בִּתְשׁוּבָה, עָלִיתָ לְבִינָה, יה\"ו, עֵץ הַחַיִּים, וּבִגְלָלָהּ זָכִיתָ לָאוֹת ה', מִשּׁוּם שֶׁהִכְנַסְתָּ אֶת עַצְמְךְ אַחֲרֶיהָ בִּתְשׁוּבָה לְהַחֲזִירָהּ לְרִבּוֹנְךְ וּלְהַעֲלוֹתָהּ מֵהַגָּלוּת, וְלֹא שֶׁתְּקַבֵּל אַתָּה שָׂכָר.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא שָׂם שְׁמוֹ בְּךְ, וּמִשּׁוּם שֶׁמַּחֲשַׁבְתְּךְ הָיְתָה לְעִלַּת הָעִלּוֹת, שָׂם בְּךְ מַחֲשַׁבְתּוֹ, שֶׁהִיא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְעִלַּת הָעִלּוֹת הוּא מְיַחֵד אֶת הָאוֹתִיּוֹת הַלָּלוּ בְּךְ כְּדֵי לְהַכִּיר אוֹתוֹ בָּאוֹתִיּוֹת הַלָּלוּ.</p>\n<p>וּמִשּׁוּם שֶׁאַתָּה הָיִיתָ גּוֹמֵל חֶסֶד עִם הַשְּׁכִינָה, שֶׁכָּל הַמִּצְווֹת שֶׁלְּךְ לְקַיֵּם, אֵיזֶהוּ חָסִיד? הַמִּתְחַסֵּד עִם קוֹנוֹ - נָתַן לְךְ מִדַּת חֶסֶד. וּמִשּׁוּם שֶׁשָּׁמַרְתָּ מִצְווֹת לֹא תַעֲשֶׂה, וְהָיָה לְךְ לְהִתְגַּבֵּר עַל יִצְרְךְ, לִקְשֹׁר אוֹתוֹ תַּחַת יָדְךְ, וְלֹא הִשְׁתַּדַּלְתָּ בַּמִּצְוָה הַזּוֹ, אֶלָּא לִקְשֹׁר אֶת סמא\"ל תַּחַת יָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבַת זוּגוֹ, שֶׁהִיא שִׁפְחָה רָעָה, תַּחַת יַד גְּבִרְתָּהּ, אוֹתָם וְאֶת כָּל הַמְמֻנִּים וְהַמַּחֲנוֹת שֶׁלָּהֶם - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְךְ אֶת מִדַּת גְּבוּרָתוֹ לִהְיוֹת בְּעֶזְרְךְ שֶׁיִּתְחַלְחֲלוּ וְיִפְחֲדוּ מִמְּךְ סמא\"ל וּבַת זוּגוֹ, וְכָל הַמְמֻנִּים וְהַמַּחֲנוֹת שֶׁלָּהֶם, וְיִהְיוּ קְשׁוּרִים בְּשַׁלְשְׁלָאוֹת תַּחַת יָדְךְ.</p>\n<p>וּמִשּׁוּם שֶׁחָזַרְתָּ בִּתְשׁוּבָה בְּאוֹת הַבְּרִית, יָרְדָה בִּינָה יה\"ו לְהִתְחַבֵּר בְּצַדִּיק. בִּשְׁבִילְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לְךְ אוֹת בְּרִית צַדִּיק שֶׁלּוֹ. וּמִשּׁוּם שֶׁבְּמַחֲשָׁבָה טוֹבָה עָשִׂיתָ אֶת הַכֹּל, כָּךְ יָרַד שֵׁם הַמְפֹרָשׁ (של רבונך) עָלֶיךְ, וּמִשָּׁם (הרשם שירד) יָרַד עָלֶיךְ.</p>\n<p>וּמִשּׁוּם שֶׁאַתָּה תִּשְׁתַּדֵּל בְּכָל יוֹם בִּשְׁתֵּי הַשְּׂפָתַיִם שֶׁלְּךְ בִּתְפִלָּה, לְשַׁבֵּחַ אֶת רִבּוֹנְךְ בַּאדנָי שְׂפָתַי תִּפְתָּח בִּשְׁתֵּי הַשְּׂפָתַיִם שֶׁלְּךְ, בִּנְבִיאִים וּבַכְּתוּבִים, וּבְכָל מִינֵי זֶמֶר וְנִגּוּן בַּתְּפִלָּה - הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד אוֹתָם בַּשְּׂפָתַיִם שֶׁלְּךְ. כָּל שֶׁכֵּן הַדַּרְגָּה שֶׁלְּךְ, עַמּוּד הָאֶמְצָעִי, וּבוֹ הִשְׁתַּדַּלְתָּ בְּכָל יָמֶיךְ בֶּאֱמֶת - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אוֹתוֹ לְךְ לְהַעֲלוֹת אוֹתְךְ בּוֹ, בְּתוֹרַת אֱמֶת, כְּלוּלָה מִכָּל הַמִּדּוֹת וְהָאוֹתִיּוֹת, בַּשֵּׁם הַמְפֹרָשׁ בְּאַרְבַּע הָאוֹתִיּוֹת.</p>\n<p>שֶׁקֹּדֶם שֶׁחָזַרְתָּ בִּתְשׁוּבָה לֹא הָיִיתָ אֶלָּא בָּעֵץ שֶׁל טוֹב וְרַע. עֶבֶד וְנַעַר הָיָה שִׁמְךְ בַּתְּחִלָּה, וְהִנֵּה נַעַר בֹּכֶה, עֶבֶד נֶאֱמָן. זֶהוּ שֶׁכָּתוּב (במדבר יב) לֹא כֵן עַבְדִּי מֹשֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְאוֹתוֹ הָרָע, הַשֻּׁתָּף שֶׁל הָעֶבֶד, גָּרַם לְךְ לַחֲטֹא בַּסֶּלַע, מִשּׁוּם שֶׁהַמַּטֶּה שֶׁנִּמְסַר לְךְ (בידך) הָיָה שֶׁל הָעֵץ טוֹב וָרָע. מטטרו\"ן טוֹב, סמא\"ל רַע.</p>"],[9522011668,"<p>וּכְשֵׁם שֶׁחָזַרְתָּ בִּתְשׁוּבָה וְנִדְבַּקְתָּ בְּעֵץ הַחַיִּים, הֲרֵי יָצָאתָ מֵעֶבֶד, וְהָפַכְתָּ לִהְיוֹת בֵּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְהַמַּטֶּה שֶׁנִּמְסַר בְּיָדְךְ יִהְיֶה עֵץ הַחַיִּים, ו', שֶׁהוּא בֶּן יָ\"הּ, וְתִכָּנֵס בְּאַרְבָּעִים וְתֵשַׁע הַפָּנִים שֶׁלְּךְ בַּתּוֹרָה, וְיֵעָשֶׂה מוֹט, וְיִתְקַיֵּם בְּךְ (תהלים נה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. אַרְבָּעִים וְתֵשַׁע פָּנִים, אַרְבָּעִים וְתֵשַׁע אוֹתִיּוֹת שֶׁל שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, שֵׁשׁ תֵּבוֹת הַתֵּבוֹת שֶׁל הַיִּחוּד הָעֶלְיוֹן, ו' עֶלְיוֹנָה תִּפְאֶרֶת. שֵׁשׁ תֵּבוֹת שְׁנִיּוֹת שֶׁל בָּרוּךְ שֵׁם, ו' שֵׁנִי צַדִּיק. מ\"ט. בָּאֶמְצַע ו. וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם.</p>\n<p>בְּלֹא וָא\"ו בָּאֶמְצַע, הוּא מ\"ט. (בלא א' האמצעית של ו\"ו) וְצַדִּיק מָ\"ט לִפְנֵי רָשָׁע, וּמִי גָרַע אֶת זֶה? א'. אֶחָד מֵחֲמִשִּׁים, שֶׁחֲמִשִּׁים שְׁעָרִים נִתְּנוּ לְךְ חָסֵר אֶחָד, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, חֲמִשִּׁים שַׁעֲרֵי בִינָה נִמְסְרוּ לְמֹשֶׁה חוּץ מֵאֶחָד. וְזֶהוּ א' שֶׁחָסֵר מֵחֲמִשִּׁים, וְנִשְׁאֲרוּ מ\"ט, וְזֶה גָּרַם לְךְ צַדִּיק מָ\"ט לִפְנֵי רָשָׁע. מִי הָרָשָׁע? זֶה סמא\"ל.</p>\n<p>וְזְהִוּ מ\"ט, מֵהַמַּטֶּה שֶׁלְּךְ, שֶׁנֶּאֱמַר בּוֹ (שמות יז) וּמַטֵּה הָאֱלֹהִים בְּיָדִי. הַמַּטֶּה שֶׁלְּךְ הוּא הַמַּטֶּה שֶׁל מֹשֶׁה, וּמִשּׁוּם זֶה א, שֶׁהִיא בִּינָה, חוֹזֶרֶת לְךְ, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּמִּשְׁנָה, אָלֶף בִּינָה. שֶׁהִיא חוֹזֶרֶת לְךְ בִּתְשׁוּבָה וְתִכָּנֵס בֵּין וָ\"ו, וְתֵעָשֶׂה וָא\"ו, לְקַיֵּם בְּךְ לְיִשְׂרָאֵל, (ישעיה נד) וּבְרַחֲמִים גְּדלִים אֲקַבְּצֵךְ (ירמיה לא) (ובתחנונים אובילם). מִשָּׁם וְאֵילָךְ יִתְקַיֵּם בְּךְ, לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק.</p>\n<p>בְּאוֹתוֹ זְמַן יִתְקַיְּמוּ בְךְ שְׁתֵּי מִצְווֹת: אַחַת - (דברים כב) הָקֵם תָּקִים עִמּוֹ. שְׁנִיָּה - עָזֹב תַּעֲזֹב עִמּוֹ. הָקֵם עִם ו' עֶלְיוֹנָה, מָשִׁיחַ רִאשׁוֹן. תָּקִים עִם ו' שְׁנִיָּה. עִמּוֹ - זֶה בֶּן עַמְרָם, שֶׁעָלִיתָ לַבִּינָה שֶׁהִיא א'.</p>\n<p>וְאֶת מִי הָקֵם תָּקִים? אֶת אוֹת ה', שֶׁנָּפְלָה בָּאֶלֶף הַחֲמִישִׁי אַחַר ע\"ב, כְּמִנְיַן עָזוֹ\"ב תַּעֲזוֹב עִמּוֹ. עָזוֹב - ע\"ב ז\"ו. וְזֶה שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וַיִּסַּע וַיָּבֹא וַיֵּט. זֶה וָא\"ו מִן וה\"ו, שָׁם עֵזֶר, וְלֹא קִימָה, וְזֶהוּ עָזב תַּעֲזב, שָׁם (שם יא) בְּעִתּוֹ יוֹרֶה וּמַלְקוֹשׁ וְאָסַפְתָּ דְגָנֶךְ וְתִירשְׁךְ וְיִצְהָרֶךְ, שֶׁהֵם יִשְׂרָאֵל. לֶקֶט שִׁכְחָה וּפֵאָה, (ויקרא יט) לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם. כָּאן לָמַדְנוּ מִצְוָה שְׁלִישִׁית.</p>\n<p>וְצָרִיךְ לַחֲזר עֲלֵיהֶם, שֶׁהֲרֵי מִצַּד הַצַּדִּיק, עָנִי - עָזֹב תַּעֲזֹב, צַדִּיק. עִמּוֹ - זֶה בֶּן עַמְרָם. וְזֶהוּ לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם. גֵּר אַתָּה כְּמוֹ שֶׁנֶּאֱמַר בְּךְ בַּתְּחִלָּה עַם עָנִי, (שמות יח) גֵּר הָיִיתִי בְּאֶרֶץ נָכְרִיָּה.</p>\n<p>אֲבָל הֲקָמָה בַּדַּרְגָּה שֶׁלְּךְ, הָקֵם - ו' תַּחְתּוֹנָה. תָּקִים עִמּוֹ - עִם בֶּן עַמְרָם, בְּדַרְגָּה עֶלְיוֹנָה שֶׁלְּךְ, תִּפְאֶרֶת. בְּמ\"ה שֶׁלְּךְ הַשֵּׁם הַמְפֹרָשׁ בִּשְׁלֵמוּת. אַחַר ק' ק' שֶׁל הָקֵם תָּקִים (ומשוםכךהקםתקים) נִשְׁאָר תים. מַה זֶּה מַרְאֶה? (בראשית כה) יַעֲקֹב אִישׁ תָּם. עִמּוֹ - עִם בֶּן עַמְרָם יָקִים. הָקֵם - צַדִּיק. תָּקִים - תָּם.</p>"],[9522011669,"<p>מִצְוָה אַחַר זוֹ לִפְדּוֹת עֶבֶד עִבְרִי וְאָמָה הָעִבְרִיָּה, לְיַעֵד אָמָה הָעִבְרִיָּה לָדוּן בְּקִנְיַן עֶבֶד עִבְרִי, הַעֲנֵיק תַּעֲנִיק לוֹ. זֶהוּ שֶׁכָּתוּב כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד. מָהֵן שֵׁשׁ שָׁנִים יַעֲבֹד, וּמַהוּ קִנְיָנוֹ? אֶלָּא בְּסִתְרֵי תוֹרָה, מְטַטְרוֹ\"ן עֶבֶד ה' כּוֹלֵל שִׁשָּׁה צְדָדִים כְּחֶשְׁבּוֹן שֵׁשׁ אוֹתִיּוֹתָיו, שִׁשָּׁה סִדְרֵי מִשְׁנָה. וּבָהֶן יֵשׁ לָאָדָם לַעֲבֹד לְרִבּוֹנוֹ לִהְיוֹת לוֹ עֶבֶד (ממכר), לַעֲשׂוֹת קִנְיַן כַּסְפּוֹ שֶׁל כֶּסֶף יָמִין, שֶׁאַבְרָהָם חֶסֶד הוּא הַדַּרְגָּה שֶׁלּוֹ, הַתּוֹרָה נִתְּנָה מִשָּׁם.</p>\n<p>וּמִי שֶׁמִּשְׁתַּדֵּל בָּהּ כְּדֵי לִזְכּוֹת לָעוֹלָם הַבָּא, נִקְרָא קִנְיָן. כַּסְפּוֹ - עוֹלַם הַכִּסּוּף. קִנְיָן - עַל שֵׁם (בראשית יד) אֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ. קְנֵה חָכְמָה קְנֵה בִינָה. קָנָה לוֹ דִּבְרֵי תוֹרָה.</p>\n<p>רַבּוֹ אַחַר שֶׁקָּנָה לוֹ, גְּאֻלָּה תִּהְיֶה לּוֹ. יֵשׁ שֶׁהוּא קָנוּי (לו) לְעוֹלָם, וְיֵשׁ שֶׁהוּא קָנוּי לוֹ שֵׁשׁ שָׁנִים. מִי שֶׁהוּא קָנוּי לוֹ לְעוֹלָם, כָּתוּב בּוֹ וְרָצַע אֲדנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ וַעֲבָדוֹ לְעֹלָם. אֵין עוֹלָם אֶלָּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁהֵם חֲמִשִּׁים. וְזוֹ קְרִיאַת שְׁמַע שֶׁשָּׁם כ\"ה כ\"ה אוֹתִיּוֹת, עַרְבִית וְשַׁחֲרִית. חֲמִשִּׁים שַׁעֲרֵי בִינָה.</p>\n<p>אַחַר שֶׁמְּיַחֵד בָּהֶם הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עֶבֶד שֶׁלּוֹ, בְּעֹל תְּפִלִּין עַל רֹאשׁוֹ, וְאָזְנוֹ נִרְצְעָה וּפְתוּחָה לִשְׁמֹעַ קְרִיאַת שְׁמַע, הֲרֵי שְׁמַע - בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ, שֶׁהַיְנוּ מַשְׁמָעוּת.</p>\n<p>שֶׁמִּי שֶׁפִּדְיוֹנוֹ תָּלוּי בַּקְּרִיאַת שְׁמַע, שֶׁהוּא סוֹד שֶׁל חֲמִשִּׁים, אֵין לוֹ פִּדְיוֹן עַל יְדֵי אַחֵר בְּגִלְגּוּל, שֶׁרָצוּעַ הוּא לְרִבּוֹנוֹ. כָּאן לֹא נֶאֱמַר אוֹ דוֹדוֹ אוֹ בֶן דוֹדוֹ יִגְאָלֶנּוּ. שֶׁבִּתְפִלַּת הָאָדָם הוּא כְּמוֹ עֶבֶד שֶׁנֶּאֱמַר בּוֹ שֵׁשׁ שָׁנִים יַעֲבֹד, וְאֵין עֲבוֹדָה אֶלָּא תְּפִלָּה. שֵׁשׁ שָׁנִים יַעֲבֹד - ג' רִאשׁוֹנוֹת וְג' אַחֲרוֹנוֹת שֶׁל שְׁלִיחַ צִבּוּר מוֹצִיא אֶת הָאָדָם יְדֵי חוֹבָתוֹ לְמִי שֶׁלֹּא יוֹדֵעַ לְהִתְפַּלֵּל בָּהֶם, שֶׁצַּדִּיק חַי הָעוֹלָם נִקְרָא בָהֶם עַל שְׁמוֹ. בּעַז, צַדִּיק, גּוֹאֵל, קָרוֹב וְנֶאֱמָן.</p>\n<p>(ושם) קָרוֹב ה' לְכָל קֹרְאָיו. וְטוֹב לוֹ לָאָדָם שָׁכֵן קָרוֹב מֵאָח רָחוֹק, שֶׁהַיְנוּ עַמּוּד הָאֶמְצָעִי, שֶׁהוּא בֶּן יָהּ, שֶׁהִתְעַלָּה לְמַעְלָה שֶׁהוּא לְבִינָה, שֶׁעוֹלָם זֶה הוּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁהוּא חֲמִשִּׁים אוֹתִיּוֹת הַיִּחוּד. שֶׁבָּעוֹלָם הַזֶּה יָכוֹל אָדָם לִהְיוֹת לוֹ פִּדְיוֹן בְּצַדִּיק ו' שָׁנִים שֶׁכּוֹלֵל שָׁלֹשׁ רִאשׁוֹנוֹת, וְשָׁלֹשׁ אַחֲרוֹנוֹת שֶׁל הַתְּפִלָּה. ו' קְטַנָּה הוּא שֵׁשׁ שָׁנִים יַעֲבֹד.</p>\n<p>אֲבָל בָּעוֹלָם הַבָּא, שֶׁהוּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁשָּׁם חֲמִשִּׁים אוֹתִיּוֹת שֶׁל קְרִיאַת שְׁמַע, אֵין שְׁלִיחַ צִבּוּר מוֹצִיא אוֹתוֹ יְדֵי חוֹבָתוֹ, מִשּׁוּם שֶׁאֵין לוֹ פִּדְיוֹן עַל יְדֵי אֲחֵרִים, וּמִשּׁוּם כָּךְ שְׁמַע, בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ. וּמִשּׁוּם כָּךְ רוֹמֵז, אִם אֵין אֲנִי לִי מִי לִי. מִ\"י - וַדַּאי עוֹלָמוֹ שֶׁל יוֹבֵל.</p>"],[9522011670,"<p>מִיָּד שֶׁשָּׁמְעוּ דְבָרִים הַלָּלוּ רָאשֵׁי הַיְשִׁיבוֹת שֶׁהָיוּ יוֹרְדִים עִם הַמְּנוֹרָה הַקְּדוֹשָׁה, פָּתְחוּ וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, פִּי הַשְּׁכִינָה הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה, שֶׁבִּשְׁתֵּיהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא דִּבֵּר עִמְּךְ פֶּה אֶל פֶּה בִּקְרִיאַת שְׁמַע, שֶׁנֶּאֱמַר בּוֹ (תהלים קמט) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. שֶׁהֲרֵי וַדַּאי י' רֹאשׁ הַחֶרֶב שֶׁסּוֹבֶבֶת אֶת הַשָּׂפָה שֶׁלְּךְ. ו' לְשׁוֹן הַחֶרֶב שֶׁלְּךְ. ה' ה' שְׁתֵּי פִיפִיּוֹת, בִּשְׁתֵּי שִׂפְתוֹתֶיךְ. וַהֲרֵי וַדַּאי שֵׁם רִבּוֹנְךְ מְדַבֵּר בְּפִיךְ. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א הוּא בְּמַחֲשַׁבְתְּךְ שֶׁמּוֹצִיא אֶת הַחֲמִשִּׁים הַלָּלוּ מִפִּיךְ.</p>\n<p>בְּוַדַּאי מִשּׁוּם הַדְּבָרִים הַלָּלוּ אֵלִיָּהוּ הִתְעַכֵּב לְמַעְלָה, שֶׁהוּא תָּפוּס, שֶׁלֹּא יוֹרֵד אֵלֶיךְ, שֶׁהֲרֵי בְּכַמָּה עֹשֶׁר הָיָה יוֹרֵד אֵלֶיךְ, וְהוּא תָּפוּס לְמַעְלָה, שֶׁלֹּא יוֹרֵד אֵלֶיךְ. מִשּׁוּם שֶׁהָעֹנִי שֶׁלְּךְ הוּא גְּאֻלָּה לְיִשְׂרָאֵל, וּמִשּׁוּם כָּךְ אָמַר מָשִׁיחַ, עַד שֶׁיָּבא עָנִי, וְזֶהוּ שֶׁכָּתוּב (ישעיה נג) וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ.</p>\n<p>אָמַר לָהֶם, אִם כָּךְ, נַעֲשֶׂה לוֹ הַתָּרָה וְיֵרֵד אֵלַי, שֶׁחָשׁוּב הוּא לִי מִכָּל מָמוֹן שֶׁל הָעוֹלָם, וַהֲרֵינִי מוֹחֵל וּמְשַׁחְרֵר אוֹתוֹ וּמַתִּיר לוֹ אֶת הַשְּׁבוּעָה, וְאַף אַתֶּם הַתִּירוּ לוֹ. וְאִם צָרִיךְ הַתָּרָה יוֹתֵר, נִשְׁתַּדֵּל בְּהַתָּרָתוֹ, כְּדֵי שֶׁיֵּרֵד אֵלַי.</p>"],[9522011671,"<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, שְׁבוּעַת ה', הִיא שְׁכִינָה, בַּת יְחִידָה. וְלֹא לְחִנָּם תִּקְּנוּ שְׁלֹשֶׁת בְּנֵי אָדָם לִפְטֹר אוֹתוֹ, אֶלָּא ש' שֶׁל שַׁבָּת, שְׁלֹשֶׁת עַנְפֵי הָאָבוֹת, בַּת יְחִידָה, שְׁבוּעָה שֶׁהִשְׁתַּתְּפָה (בה כסא ודאי) בָּהֶם.</p>\n<p>בְּוַדַּאי שְׁבוּעָה לֹא חָלָה אֶלָּא עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֶדֶר חָל אֲפִלּוּ עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, וַהֲרֵי פֵּרְשׁוּהָ בַּמִּשְׁנָה. וְלֹא עוֹד, אֶלָּא יוֹתֵר אָמְרוּ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים, וְכָל הַנִּשְׁבָּע כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ, וְכָל הַנּוֹדֵר כְּאִלּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ.</p>\n<p>אָמַר לָהֶם רוֹעֶה הַנֶּאֱמָן, רָאשֵׁי יְשִׁיבוֹת, יָדַעְתִּי בָכֶם שֶׁאַתֶּם יוֹדְעִים, אֲבָל אוֹתוֹ שֶׁמְּחַדֵּשׁ בְּכָל יוֹם מַעֲשֵׂה בְרֵאשִׁית יְחַדֵּשׁ לָכֶם חִדּוּשִׁים, שֶׁהֲרֵי וַדַּאי קֹהֶלֶת אָמַר, (קהלתא) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ. אֲבָל לְמַעְלָה מִן הַשֶּׁמֶשׁ יֵשׁ לוֹ. וּבְסִתְרֵי תוֹרָה אֲנִי רוֹצֶה לוֹמַר, (תהלים סד) שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים צְבָאוֹת, בָּעוֹלָם שֶׁלּוֹ, וְלֹא בְּעוֹלָם שֶׁל הֶדְיוֹט. אַף עַל גַּב שֶׁזֶּה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים, מִתּוֹךְ הַחֲשֵׁכָה יוֹצֵא הָאוֹר.</p>\n<p>וּבְוַדַּאי בָּעוֹלָם הַבָּא, בִּינָה הִיא לְמַעְלָה מֵהַשֶּׁמֶשׁ, שֶׁהוּא עַמּוּד הָאֶמְצָעִי. מִשָּׁם עוֹלִים נְדָרִים עַל גַּבֵּי שְׁבוּעָה וְחָלִים עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, מִשּׁוּם שֶׁהַשְּׁבוּעָה הוּא הָעוֹלָם הַזֶּה, שֶׁאֵין לוֹ קִיּוּם אֶלָּא עַל יְסוֹד. זֶהוּ שֶׁכָּתוּב (משליי) וְצַדִּיק יְסוֹד עוֹלָם.</p>\n<p>וּבוֹ שְׁבוּעָה, שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁשְּׁכִינָה תַּחְתּוֹנָה, כֹּתֶל מַעֲרָבִי הוּא הַדִּיּוּר שֶׁלָּהּ, עַל שֵׁם שֶׁהוּא תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. כּ\"וֹ תֵּ\"ל, יְדוָ\"ד כּ\"וֹ, וַדַּאי שְׁכִינָה הִיא תֵּל שֶׁלּוֹ, עַל שֵׁם (שיר ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים שְׁחֹרוֹת כָּעוֹרֵב. וּפֵרְשׁוּהָ עַל כָּל קוֹץ וְקוֹץ תִּלֵּי תִלִּים שֶׁל הֲלָכוֹת. (קוץ) ד' מִן אֶחָד, תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. וְהַקּוֹץ הַזֶּה אָחוּז בֵּין א\"ח וּבֵין ד'. זֶהוּ שֶׁכָּתוּב כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יְהוֹנָתָן, שֶׁאָחוּז בַּשָּׁמַיִם וּבָאָרֶץ.</p>\n<p>וְעָלָיו בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה בַּחֲגִיגָה, עַל מָה הָעוֹלָם עוֹמֵד? עַל עַמּוּד אֶחָד שֶׁשְּׁמוֹ צַדִּיק, שֶׁנֶּאֱמַר וְצַדִּיק יְסוֹד עוֹלָם. וּבְוַדַּאי הוּא בְּרִית שֶׁל שְׁבוּעָה שֶׁעָלָיו עוֹמְדִים א\"ח ד', שֶׁהֵם שָׁמַיִם וָאָרֶץ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. א\"ח שָׁמַיִם, זֶהוּ שֶׁכָּתוּב (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. ד' הָאָרֶץ, זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי.</p>\n<p>וּמִשּׁוּם שֶׁבְּרִית אֲחוּזָה בֵּין שָׁמַיִם וָאָרֶץ וּבָהּ שְׁבוּעָה, זֶהוּ שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. מִי שֶׁנִּשְׁבָּע בִּשְׁמוֹ לַשֶּׁקֶר, כְּאִלּוּ הָרַס אֶת בִּנְיַן הַשָּׁמַיִם וְהָאָרֶץ וְהֶחֱזִיר אֶת הָעוֹלָם לְתֹהוּ וָבהוּ. שֶׁאִם אָדָם יָזִיז הַקּוֹץ שֶׁל ד' מִן אֶחָד, יִשָּׁאֵר אַחֵר, סמא\"ל בִּמְקוֹמוֹ שֶׁקֶר. וּכְאִלּוּ אוֹתוֹ אִישׁ בּוֹנֶה שָׁמַיִם וָאָרֶץ עַל שֶׁקֶר. וֶאֱמֶת עוֹמֵד, שֶׁקֶר לֹא עוֹמֵד. הָרַס הַבִּנְיָן, וְנָפְלוּ שָׁמַיִם וָאָרֶץ.</p>\n<p>וְזְהִוּ כְּאִלּוּ הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. שֶׁמִּי נוֹתֵן אֶרֶץ בַּשָּׁמַיִם, שֶׁאָמַר (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ? וַדַּאי זוֹ שְׁכִינָה, וְתִפְאֶרֶת עִמָּהּ, שֶׁלֹּא נִפְרָד מִמֶּנָּה בִּנְפִילָתָהּ, לְקַיֵּם בָּהּ (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. וּמִנַּיִן לָנוּ שֶׁאֱמֶת נָפַל עִמָּהּ? שֶׁכָּתוּב (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה. וּמִי שֶׁנִּשְׁבָּע אֱמֶת הוּא מְקַיֵּם (תהלים פה) אֱ\"מֶת מֵ\"אֶרֶץ תִּ\"צְמָח. שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי שֶׁבּוֹ הַבִּנְיָן קַיָּם. זֶהוּ שֶׁכָּתוּב בָּרָ\"א אֱלֹהִי\"ם אֵ\"ת, וְאַחַר כָּךְ - הַשָּׁמַיִם וְאֵת הָאָרֶץ.</p>\n<p>וּמִשּׁוּם שֶׁשְּׁבוּעָה הִיא בִּנְיָן שֶׁל הָעוֹלָם הַזֶּה, אֵין לוֹ קִיּוּם לְלֹא יְסוֹד, דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֶדֶר, שֶׁהוּא עוֹלָם הַבָּא, עוֹלֶה עַל גַּבֵּי שְׁבוּעָה, וְהוּא חָל עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, שֶׁלֹּא צְרִיכָה יְסוֹד לַעֲמֹד עָלָיו, שֶׁהוּא בְּרִית, שֶׁבּוֹ תַּשְׁמִישׁ הַמִּטָּה. וּמִשּׁוּם כָּךְ בְּיוֹם הַכִּפּוּרִים, הָעוֹלָם הַבָּא, שֶׁבּוֹ תִּקְּנוּ כָּל נִדְרֵי, אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה.</p>\n<p>שָׁם אוֹת בְּרִית, י' הִיא תָּג עַל סֵפֶר תּוֹרָה צַדִּיק, כְּמוֹ שֶׁבֵּאֲרוּהָ, הָעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה וְלֹא תַּשְׁמִישׁ הַמִּטָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם.</p>\n<p>וּמִשּׁוּם שֶׁאֵין שִׁמּוּשׁ בָּעוֹלָם הַזֶּה בְּתָג, בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַמִּשְׁתַּמֵּשׁ בְּתָגָא חֲלָף. שֶׁתָּג לְמַטָּה הוּא בָּעוֹלָם הַזֶּה. הַנְּקֻדָּה שִׁמּוּשׁ הָאוֹתִיּוֹת. אֲבָל בָּעוֹלָם הַבָּא אֵין שִׁמּוּשׁ בָּאוֹתִיּוֹת, וְלָכֵן בְּסֵתֶר תּוֹרָה אֵין נִקּוּד בְּאוֹתִיּוֹתָיו, אֶלָּא תָּגִים. וְלָכֵן מִי שֶׁמִּשְׁתַּמֵּשׁ בְּסֵפֶר תּוֹרָה חוֹלֵף, וְכָךְ מִי שֶׁמִּשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, עָלָיו בֵּאֲרוּ רַבּוֹתֵינוּ שֶׁהַמִּשְׁתַּמֵּשׁ בְּתָגָא - חוֹלֵף.</p>\n<p>בָּאוּ כָּל רָאשֵׁי הַיְשִׁיבוֹת וְהִשְׁתַּטְּחוּ לְפָנָיו וְאָמְרוּ, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר בְּפִיךְ, וְלוֹ אָנוּ מִשְׁתַּחֲוִים. וְאָנוּ מַכִּירִים בַּדְּבָרִים הַלָּלוּ שֶׁאֵין יְלוּד אִשָּׁה אַחֵר פְּרָט לְךְ שֶׁיָּכוֹל לְדַבֵּר אוֹתָם. וַדַּאי שֶׁהַדְּבָרִים הַלָּלוּ מְעִידִים בְּךְ שֶׁאַתָּה הוּא שֶׁנֶּאֱמַר בּוֹ (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אֵין לְעַכֵּב אֶת אֵלִיָּהוּ אֵלֶיךְ, אֶלָּא לְפַיֵּס אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיּוֹרִיד אוֹתוֹ אֵלֶיךְ, מָלֵא עֹשֶׁר וּמָלֵא סְגֻלּוֹת אֵלֶיךְ.</p>"]]});
